struct UsbEnumerationDevice {
    slot: u8,
    root_port: u8,
    vendor_id: u16,
    product_id: u16,
    route: u32,
    speed: u32,
    depth: u8,
    parent_hub_slot: u8,
    parent_hub_port: u8,
    parent_tt_port: u8,
    parent_tt_think_time: u8,
    device_context_offset: usize,
    ep0_ring_offset: usize,
    ep0_enqueue: u16,
    ep0_cycle: bool,
}

impl UsbEnumerationDevice {
    const fn empty() -> Self {
        Self {
            slot: 0,
            root_port: 0,
            vendor_id: 0,
            product_id: 0,
            route: 0,
            speed: 0,
            depth: 0,
            parent_hub_slot: 0,
            parent_hub_port: 0,
            parent_tt_port: 0,
            parent_tt_think_time: 0,
            device_context_offset: 0,
            ep0_ring_offset: 0,
            ep0_enqueue: 0,
            ep0_cycle: true,
        }
    }

    const fn child(&self, port: u8, speed: u32) -> Self {
        let shift = (self.depth as u32).saturating_mul(4);
        let route = self.route | ((port as u32 & 0x0f) << shift);
        Self {
            slot: 0,
            root_port: self.root_port,
            vendor_id: 0,
            product_id: 0,
            route,
            speed,
            depth: self.depth.saturating_add(1),
            parent_hub_slot: self.slot,
            parent_hub_port: port,
            parent_tt_port: port,
            parent_tt_think_time: 0,
            device_context_offset: 0,
            ep0_ring_offset: 0,
            ep0_enqueue: 0,
            ep0_cycle: true,
        }
    }

    fn child_with_hub_info(&self, port: u8, speed: u32, hub: UsbHubInfo) -> Self {
        let mut child = self.child(port, speed);
        let (tt_port, tt_think_time) =
            usb_normalize_hub_tt_profile(port, hub.multi_tt, hub.tt_think_time);
        child.parent_tt_port = tt_port;
        child.parent_tt_think_time = tt_think_time;
        child
    }
}

