#[cfg(target_os = "none")]
const MINI_UART_IO_OFFSET: usize = 0x40;
#[cfg(target_os = "none")]
const MINI_UART_IER_OFFSET: usize = 0x44;
#[cfg(target_os = "none")]
const MINI_UART_IIR_OFFSET: usize = 0x48;
#[cfg(target_os = "none")]
const MINI_UART_LCR_OFFSET: usize = 0x4c;
#[cfg(target_os = "none")]
const MINI_UART_MCR_OFFSET: usize = 0x50;
#[cfg(target_os = "none")]
const MINI_UART_LSR_OFFSET: usize = 0x54;
#[cfg(target_os = "none")]
const MINI_UART_CNTL_OFFSET: usize = 0x60;
#[cfg(target_os = "none")]
const AUX_ENABLES_OFFSET: usize = 0x04;
#[cfg(target_os = "none")]
const MINI_UART_LSR_RX_READY: u32 = 1;
#[cfg(target_os = "none")]
const MINI_UART_LSR_TX_EMPTY: u32 = 1 << 5;
#[cfg(target_os = "none")]
const MINI_UART_LSR_TX_IDLE: u32 = 1 << 6;
#[cfg(target_os = "none")]
const MINI_UART_TX_SPIN_LIMIT: usize = 65_536;
const MINI_UART_RX_DRAIN_LIMIT: usize = 128;
const MINI_UART_RX_QUEUE_CAPACITY: usize = 512;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SerialRuntimeRxQueue {
    bytes: [u8; MINI_UART_RX_QUEUE_CAPACITY],
    head: usize,
    len: usize,
    drops: u32,
}

impl SerialRuntimeRxQueue {
    const fn new() -> Self {
        Self {
            bytes: [0; MINI_UART_RX_QUEUE_CAPACITY],
            head: 0,
            len: 0,
            drops: 0,
        }
    }

    fn reset(&mut self) {
        *self = Self::new();
    }

    fn push(&mut self, byte: u8) -> bool {
        if self.len == MINI_UART_RX_QUEUE_CAPACITY {
            self.drops = self.drops.saturating_add(1);
            return false;
        }
        let tail = (self.head + self.len) % MINI_UART_RX_QUEUE_CAPACITY;
        self.bytes[tail] = byte;
        self.len += 1;
        true
    }

    fn pop(&mut self) -> Option<u8> {
        if self.len == 0 {
            return None;
        }
        let byte = self.bytes[self.head];
        self.head = (self.head + 1) % MINI_UART_RX_QUEUE_CAPACITY;
        self.len -= 1;
        Some(byte)
    }
}

/// Shared-buffer descriptor passed over the pointer-free driver-task ring.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverFrameDescriptor {
    /// Offset into the ring/shared-buffer arena.
    pub offset: u32,
    /// Valid payload length at `offset`.
    pub len: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
}

impl DriverFrameDescriptor {
    const fn empty() -> Self {
        Self {
            offset: 0,
            len: 0,
            flags: 0,
        }
    }

    fn in_ring_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        len <= MAX_DRIVER_TASK_FRAME_BYTES
            && offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_ring_page_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_runtime_payload(self, shared_payload_bytes: usize) -> bool {
        if self.in_ring_page_payload() {
            return true;
        }
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES + shared_payload_bytes)
    }
}

/// Primitive budget grant encoded in the root/driver ring ABI.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskBudgetGrant {
    /// Maximum HAL operations admitted for the command.
    pub max_ops: u16,
    /// Maximum frames admitted for the command.
    pub max_frames: u16,
    /// Maximum bytes admitted for the command.
    pub max_bytes: u32,
}

/// Fixed command record consumed by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCommandRecord {
    /// Monotonic root-assigned sequence number.
    pub sequence: u32,
    /// Primitive command opcode.
    pub opcode: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
    /// Opcode-specific primitive argument.
    pub arg0: u32,
    /// Second opcode-specific primitive argument.
    pub arg1: u32,
    /// Auxiliary role-specific argument.
    pub aux0: u32,
    /// Second auxiliary role-specific argument.
    pub aux1: u32,
    /// Per-command service budget.
    pub budget: DriverTaskBudgetGrant,
    /// Shared-buffer descriptor for frame-bearing commands.
    pub frame: DriverFrameDescriptor,
}

/// Completion record written by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCompletionRecord {
    /// Completed command sequence.
    pub sequence: u32,
    /// Primitive completion code.
    pub code: u16,
    /// Fault code or role-specific detail.
    pub detail: u16,
    /// Role-specific primitive result.
    pub result: u32,
    /// Shared-buffer descriptor for frame-bearing completions.
    pub frame: DriverFrameDescriptor,
}

impl DriverTaskCompletionRecord {
    const fn progress(sequence: u32, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail: FAULT_NONE,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn progress_with_detail(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn frame_ready(sequence: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_at(sequence: u32, offset: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_with_descriptor(sequence: u32, frame: DriverFrameDescriptor) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: frame.len as u32,
            frame,
        }
    }

    const fn frame_ready_with_detail(
        sequence: u32,
        detail: u16,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail,
            result: frame.len as u32,
            frame,
        }
    }

    const fn keyboard_input_ready(sequence: u32, len: u16) -> Self {
        Self::frame_ready_with_descriptor(
            sequence,
            DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len,
                flags: DRIVER_RUNTIME_USB_KEYBOARD_FRAME_FLAG_INPUT,
            },
        )
    }

    const fn idle(sequence: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail: FAULT_NONE,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn idle_with_detail_and_frame(
        sequence: u32,
        detail: u16,
        result: u32,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail,
            result,
            frame,
        }
    }

    const fn budget_exhausted(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_BUDGET_EXHAUSTED,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result_and_frame(
        sequence: u32,
        detail: u16,
        result: u32,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame,
        }
    }
}

const fn runtime_staged_completion(
    mut completion: DriverTaskCompletionRecord,
) -> DriverTaskCompletionRecord {
    completion.sequence = 0;
    completion
}

/// Service one fixed-layout command without using root pointers.
#[must_use]
#[cfg(not(target_os = "none"))]
pub fn service_command(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    loop {
        match service_command_turn(task_key, command) {
            RuntimeCommandTurn::Pending => {}
            RuntimeCommandTurn::Complete(completion) => return completion,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandTurn {
    Pending,
    Complete(DriverTaskCompletionRecord),
}

fn service_command_turn(task_key: usize, command: DriverTaskCommandRecord) -> RuntimeCommandTurn {
    #[cfg(target_os = "none")]
    let cyw43_transaction = command.sequence != 0 && command.arg0 == HOT_PATH_CYW43_WIFI;

    #[cfg(target_os = "none")]
    if cyw43_transaction && !cyw43_foreground_begin_turn(command) {
        return cyw43_foreground_finish_turn(
            command,
            RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                command.sequence,
                FAULT_CYW43_TRANSPORT_BUS_LINK,
                command.sequence,
            )),
        );
    }

    let turn = if let Some(turn) = service_sdio_pwrseq_command_turn(command) {
        turn
    } else if let Some(turn) = service_cyw43_control_exchange_command_turn(command) {
        turn
    } else {
        RuntimeCommandTurn::Complete(service_command_immediate(task_key, command))
    };

    #[cfg(target_os = "none")]
    if cyw43_transaction {
        return cyw43_foreground_finish_turn(command, turn);
    }
    turn
}

fn service_command_immediate(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    if command.sequence == 0 {
        return DriverTaskCompletionRecord::idle(0);
    }
    if command.opcode == OPCODE_SHUTDOWN {
        return DriverTaskCompletionRecord::progress(command.sequence, 1);
    }
    if command.opcode == OPCODE_SERVICE && command.arg0 == 0 {
        return DriverTaskCompletionRecord::progress(command.sequence, task_key as u32);
    }
    let Some(role) = role_for_hot_path(command.arg0) else {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    };
    if command.arg1 != role {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_COMMAND_VALIDATED,
        command.aux0,
    );
    if command.aux0 == DRIVER_RUNTIME_INIT_AUX {
        return service_runtime_init(task_key, command);
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != command.arg0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_MISMATCH,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
        command.aux0,
    );
    if command_is_engine_init_aux(command.aux0) {
        publish_service_dispatch_progress(command);
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DISPATCH,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
            command.aux0,
        );
        if command.opcode != OPCODE_SERVICE || command.frame.len != 0 {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
            command.aux0,
        );
        match mark_engine_initialized(command) {
            Ok(detail) => {
                publish_runtime_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
                    command.aux0,
                );
                return DriverTaskCompletionRecord::progress_with_detail(
                    command.sequence,
                    detail,
                    1,
                );
            }
            Err(detail) => {
                if command.arg0 == HOT_PATH_CYW43_WIFI {
                    let exact = cyw43_take_last_fault_detail().unwrap_or(detail);
                    return DriverTaskCompletionRecord::fault_with_result(
                        command.sequence,
                        exact,
                        cyw43_take_last_fault_result(),
                    );
                }
                return DriverTaskCompletionRecord::fault(command.sequence, detail);
            }
        }
    }
    if !opcode_matches_hot_path(command.opcode, command.arg0) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_service_dispatch_progress(command);

    match command.arg0 {
        HOT_PATH_SERIAL_CONSOLE => service_serial(command),
        HOT_PATH_USB_KEYBOARD => service_usb_keyboard(command),
        HOT_PATH_HDMI_TEXT => service_hdmi_text(command),
        HOT_PATH_GENET_NIC => service_genet_runtime(command),
        HOT_PATH_CYW43_WIFI => service_cyw43_runtime(command),
        HOT_PATH_SDIO_HOST => service_sdio_host(command),
        HOT_PATH_PCIE_ROOT => service_pcie_root(command),
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

#[must_use]
const fn command_expects_reply(command: DriverTaskCommandRecord) -> bool {
    command.flags & DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY == 0
}

const RUNTIME_IDLE_POLL_PROGRESS_INTERVAL: u32 = 256;

#[must_use]
const fn runtime_idle_poll_progress_due(idle_polls: u32) -> bool {
    idle_polls == 1 || (idle_polls != 0 && idle_polls % RUNTIME_IDLE_POLL_PROGRESS_INTERVAL == 0)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandAdmission {
    None,
    OneWay,
    NeedsReplyCap,
}

#[must_use]
const fn runtime_command_admission(
    command: DriverTaskCommandRecord,
    last_sequence: u32,
) -> RuntimeCommandAdmission {
    if command.sequence == 0 || command.sequence == last_sequence {
        RuntimeCommandAdmission::None
    } else if command_expects_reply(command) {
        RuntimeCommandAdmission::NeedsReplyCap
    } else {
        RuntimeCommandAdmission::OneWay
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimeCommandIntake {
    command: DriverTaskCommandRecord,
    reply_cap_available: bool,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeWake {
    Command(RuntimeCommandIntake),
    Notification(u32),
    None,
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimePendingWakeRoute {
    ContinueForeground,
    ServiceNotification(u32),
    Rejected,
}

#[cfg(any(target_os = "none", test))]
const fn runtime_idle_service_badge(badge: u32) -> Option<u32> {
    let service_badge = badge & !DRIVER_RUNTIME_RESERVED_ROOT_BADGE;
    if service_badge == 0 {
        None
    } else {
        Some(service_badge)
    }
}

#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandLoopRoute {
    WaitForRetainedContinuation,
    WaitForIdleCommand,
    RunForeground,
}

/// Select the receive boundary used by the production runtime loop.
///
/// The idle route deliberately does not depend on whether this runtime has a
/// bound notification. Every non-MCS runtime sleeps on its command endpoint;
/// a retained command sleeps on the combined endpoint/notification receive
/// until root grants its next foreground quantum.
#[cfg(any(target_os = "none", test))]
const fn runtime_command_loop_route(
    retained_command: bool,
    continuation_required: bool,
) -> RuntimeCommandLoopRoute {
    if continuation_required {
        RuntimeCommandLoopRoute::WaitForRetainedContinuation
    } else if retained_command {
        RuntimeCommandLoopRoute::RunForeground
    } else {
        RuntimeCommandLoopRoute::WaitForIdleCommand
    }
}

/// Retained foreground commands release exactly one physical quantum per
/// root-issued endpoint rendezvous.
///
/// Ring sequence commit is the issue boundary. A later matching endpoint
/// message is only a wake grant for that exact retained intake: it cannot
/// republish, mutate, or replay the action. Unlike notification bits, endpoint
/// NBSends cannot coalesce into ambiguous grant counts and can rendezvous with
/// at most one blocked receive. Coalesced peer or IRQ work remains local and
/// alternates with foreground grants, so a continuously asserted level source
/// cannot starve the immutable command. Each delivered wake still selects
/// exactly one service or foreground quantum.
#[cfg(any(target_os = "none", test))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RuntimePendingCommandGate {
    continuation_required: bool,
    deferred_service_badge: u32,
    foreground_due_after_service: bool,
}

#[cfg(any(target_os = "none", test))]
impl RuntimePendingCommandGate {
    const fn new() -> Self {
        Self {
            continuation_required: false,
            deferred_service_badge: 0,
            foreground_due_after_service: false,
        }
    }

    const fn continuation_required(self) -> bool {
        self.continuation_required
    }

    fn retain_after_pending(&mut self) {
        self.continuation_required = true;
    }

    fn complete(&mut self) {
        self.continuation_required = false;
        self.foreground_due_after_service = false;
    }

    fn take_deferred_service(&mut self) -> Option<u32> {
        let badge = self.deferred_service_badge;
        self.deferred_service_badge = 0;
        (badge != 0).then_some(badge)
    }

    fn route_wake(
        &mut self,
        retained: &mut RuntimeCommandIntake,
        wake: RuntimeWake,
    ) -> RuntimePendingWakeRoute {
        if !self.continuation_required {
            return RuntimePendingWakeRoute::Rejected;
        }
        match wake {
            RuntimeWake::Command(candidate) => {
                // The endpoint message is only a rendezvous for the already
                // retained immutable one-way command. It cannot replace the
                // intake, introduce a reply cap, or change any action ticket
                // field. seL4 endpoints do not queue NBSend messages, so one
                // delivered matching doorbell admits exactly one child quantum
                // and all sends while the child is running are discarded.
                if candidate != *retained || candidate.reply_cap_available {
                    return RuntimePendingWakeRoute::Rejected;
                }
                if self.foreground_due_after_service {
                    self.continuation_required = false;
                    self.foreground_due_after_service = false;
                    return RuntimePendingWakeRoute::ContinueForeground;
                }
                if let Some(service_badge) = self.take_deferred_service() {
                    self.foreground_due_after_service = true;
                    return RuntimePendingWakeRoute::ServiceNotification(service_badge);
                }
                self.continuation_required = false;
                self.foreground_due_after_service = false;
                RuntimePendingWakeRoute::ContinueForeground
            }
            RuntimeWake::Notification(badge) => {
                let service_badge = badge & !DRIVER_RUNTIME_RESERVED_ROOT_BADGE;
                self.deferred_service_badge |= service_badge;
                if self.foreground_due_after_service {
                    // A priority-255 linked runtime must not turn a continuously
                    // reasserted level source into a private service loop. Only
                    // the next exact endpoint rendezvous can return to the
                    // retained foreground command.
                    RuntimePendingWakeRoute::Rejected
                } else if let Some(service_badge) = self.take_deferred_service() {
                    // Service at most one persistent-source quantum. Keeping
                    // the continuation requirement armed makes the following
                    // root grant eligible for foreground work even when the
                    // same level IRQ immediately reasserts.
                    self.foreground_due_after_service = true;
                    RuntimePendingWakeRoute::ServiceNotification(service_badge)
                } else {
                    RuntimePendingWakeRoute::Rejected
                }
            }
            RuntimeWake::None => RuntimePendingWakeRoute::Rejected,
        }
    }
}

#[cfg(target_os = "none")]
fn read_runtime_command_record() -> DriverTaskCommandRecord {
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR,
        core::mem::size_of::<DriverTaskCommandRecord>(),
    );
    driver_task_shared_load_barrier();
    // SAFETY: Root maps one command/completion ring page at the fixed
    // driver-local address before starting the runtime.
    unsafe { core::ptr::read_volatile(DRIVER_TASK_RING_VADDR as *const DriverTaskCommandRecord) }
}

#[cfg(target_os = "none")]
fn poll_runtime_command(
    last_sequence: u32,
    task_key_marker: u32,
    publish_ring_read_begin: bool,
) -> Option<RuntimeCommandIntake> {
    if publish_ring_read_begin {
        publish_runtime_progress(
            0,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_RING_READ_BEGIN,
            task_key_marker,
        );
    }
    let mut command = read_runtime_command_record();
    match runtime_command_admission(command, last_sequence) {
        RuntimeCommandAdmission::None => return None,
        RuntimeCommandAdmission::OneWay => {
            return Some(RuntimeCommandIntake {
                command,
                reply_cap_available: false,
            });
        }
        RuntimeCommandAdmission::NeedsReplyCap => {}
    }

    publish_runtime_progress(
        command.sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_POLL_BEGIN,
        command.aux0,
    );

    let mut badge: sel4_sys::seL4_Word = 0;
    // SAFETY: The root task minted `DRIVER_TASK_CHILD_COMMAND_SLOT` into the
    // child CSpace before resuming this TCB. The runtime reads the shared ring
    // before this endpoint poll so one-way bounded turns can make progress even
    // if endpoint wakeup telemetry is inconclusive. Endpoint polling is still
    // required for commands that need a reply cap.
    let tag = unsafe { sel4_sys::seL4_Poll(DRIVER_TASK_CHILD_COMMAND_SLOT, &mut badge) };
    let ipc_delivered = tag.length() != 0;
    let ipc_sequence = if ipc_delivered {
        // SAFETY: Root uses MR0 to carry the primitive request sequence when it
        // sends or calls the command endpoint.
        unsafe { sel4_sys::seL4_GetMR(0) as u32 }
    } else {
        0
    };
    if ipc_delivered && (command.sequence == 0 || command.sequence != ipc_sequence) {
        for _ in 0..8 {
            command = read_runtime_command_record();
            if command.sequence != 0 && command.sequence == ipc_sequence {
                break;
            }
            runtime_poll_pause();
        }
    }
    if command.sequence == 0 || command.sequence == last_sequence {
        return None;
    }
    let expects_reply = command_expects_reply(command);
    if expects_reply && !ipc_delivered {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            command.aux0,
        );
        return None;
    }
    if expects_reply && ipc_sequence != 0 && command.sequence != ipc_sequence {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            ipc_sequence,
        );
        return None;
    }
    Some(RuntimeCommandIntake {
        command,
        reply_cap_available: expects_reply,
    })
}

#[cfg(all(target_os = "none", not(sel4_config_kernel_mcs)))]
fn wait_runtime_command_or_notification(last_sequence: u32) -> RuntimeWake {
    let mut badge: sel4_sys::seL4_Word = 0;
    // SAFETY: The generated local notification is bound to this TCB and root
    // installs the command endpoint in slot 2. A notification therefore wakes
    // this receive with a zero-length tag; endpoint sends/calls carry MR0.
    let tag = unsafe { sel4_sys::seL4_Recv(DRIVER_TASK_CHILD_COMMAND_SLOT, &mut badge) };
    if tag.length() == 0 {
        return RuntimeWake::Notification(badge as u32);
    }
    // SAFETY: The fixed endpoint ABI carries the shared-ring sequence in MR0.
    let ipc_sequence = unsafe { sel4_sys::seL4_GetMR(0) as u32 };
    let mut command = read_runtime_command_record();
    if command.sequence != ipc_sequence {
        for _ in 0..8 {
            command = read_runtime_command_record();
            if command.sequence == ipc_sequence {
                break;
            }
            runtime_poll_pause();
        }
    }
    if command.sequence == 0
        || command.sequence == last_sequence
        || command.sequence != ipc_sequence
    {
        return RuntimeWake::None;
    }
    let reply_cap_available = command_expects_reply(command);
    RuntimeWake::Command(RuntimeCommandIntake {
        command,
        reply_cap_available,
    })
}

#[cfg(all(target_os = "none", sel4_config_kernel_mcs))]
fn wait_runtime_command_or_notification(_last_sequence: u32) -> RuntimeWake {
    RuntimeWake::None
}

#[must_use]
fn validate_runtime_init_descriptor(
    task_key: usize,
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    if command.opcode != OPCODE_SERVICE
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if !descriptor.valid()
        || descriptor.hot_path != command.arg0
        || descriptor.role_bit != command.arg1
        || !descriptor.sealed_identity_valid_for_task(task_key as u32)
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    RUNTIME_DESCRIPTOR.store(descriptor);
    RUNTIME_INIT_HOT_PATH.store(descriptor.hot_path, Ordering::Release);
    RUNTIME_INIT_FLAGS.store(descriptor.flags, Ordering::Release);
    mark_descriptor_ready(descriptor.hot_path);
    if descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor_resources_ready(&descriptor, HOT_PATH_HDMI_TEXT)
    {
        hdmi_render_boot_diagnostics(&descriptor);
        HDMI_RUNTIME_FLAGS.fetch_or(
            ENGINE_STATE_INITIALIZED
                | ENGINE_STATE_DESCRIPTOR_READY
                | ENGINE_STATE_RESOURCE_READY
                | ENGINE_STATE_HW_READY,
            Ordering::AcqRel,
        );
    }
    if descriptor.hot_path == HOT_PATH_PCIE_ROOT {
        let _ = adopt_hal_prepared_pcie_runtime_descriptor(descriptor);
    }
    DriverTaskCompletionRecord::progress(command.sequence, descriptor.hot_path)
}

#[cfg(target_os = "none")]
fn service_runtime_init(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let descriptor_addr = DRIVER_TASK_RING_VADDR + command.frame.offset as usize;
    // SAFETY: The frame descriptor is bounds-checked against the fixed ring
    // page. Root stages `DriverRuntimeInitDescriptor` at an aligned offset in
    // the ring payload before submitting the init command.
    let descriptor =
        unsafe { core::ptr::read_volatile(descriptor_addr as *const DriverRuntimeInitDescriptor) };
    validate_runtime_init_descriptor(task_key, command, descriptor)
}

#[cfg(not(target_os = "none"))]
fn service_runtime_init(
    _task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE)
}

/// Host-test helper for exercising runtime init without mapping the fixed ring.
#[cfg(test)]
#[must_use]
fn service_runtime_init_for_test(
    task_key: usize,
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    validate_runtime_init_descriptor(task_key, command, descriptor)
}

fn role_for_hot_path(hot_path: u32) -> Option<u32> {
    match hot_path {
        HOT_PATH_SERIAL_CONSOLE => Some(ROLE_SERIAL),
        HOT_PATH_USB_KEYBOARD => Some(ROLE_USB),
        HOT_PATH_HDMI_TEXT => Some(ROLE_DISPLAY),
        HOT_PATH_GENET_NIC | HOT_PATH_CYW43_WIFI => Some(ROLE_NET),
        HOT_PATH_SDIO_HOST => Some(ROLE_SDIO),
        HOT_PATH_PCIE_ROOT => Some(ROLE_PCIE),
        _ => None,
    }
}

fn opcode_matches_hot_path(opcode: u16, hot_path: u32) -> bool {
    if hot_path == HOT_PATH_HDMI_TEXT {
        opcode == OPCODE_SUBMIT_FRAME
    } else {
        opcode == OPCODE_SERVICE
    }
}

const fn command_is_engine_init_aux(aux0: u32) -> bool {
    matches!(
        aux0,
        DRIVER_RUNTIME_ENGINE_INIT_AUX
            | DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
            | DRIVER_RUNTIME_NET_INIT_AUX
    )
}

fn publish_service_dispatch_progress(command: DriverTaskCommandRecord) {
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
        command.aux0,
    );
    let phase = match command.arg0 {
        HOT_PATH_HDMI_TEXT => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_HDMI,
        HOT_PATH_USB_KEYBOARD => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_USB,
        HOT_PATH_SDIO_HOST => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_SDIO,
        HOT_PATH_CYW43_WIFI => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_CYW43,
        _ => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
    };
    if phase != DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH {
        publish_runtime_progress(command.sequence, phase, command.aux0);
    }
}

fn runtime_flags_for_hot_path(hot_path: u32) -> Option<&'static AtomicU32> {
    match hot_path {
        HOT_PATH_USB_KEYBOARD => Some(&USB_RUNTIME_FLAGS),
        HOT_PATH_HDMI_TEXT => Some(&HDMI_RUNTIME_FLAGS),
        HOT_PATH_GENET_NIC => Some(&GENET_RUNTIME_FLAGS),
        HOT_PATH_CYW43_WIFI => Some(&CYW43_RUNTIME_FLAGS),
        HOT_PATH_SDIO_HOST => Some(&SDIO_RUNTIME_FLAGS),
        HOT_PATH_PCIE_ROOT => Some(&PCIE_RUNTIME_FLAGS),
        _ => None,
    }
}

fn mark_descriptor_ready(hot_path: u32) {
    if let Some(flags) = runtime_flags_for_hot_path(hot_path) {
        flags.fetch_or(ENGINE_STATE_DESCRIPTOR_READY, Ordering::AcqRel);
    }
}

fn adopt_hal_prepared_pcie_runtime_descriptor(descriptor: DriverRuntimeInitDescriptor) -> bool {
    if !descriptor_resources_ready(&descriptor, HOT_PATH_PCIE_ROOT) {
        return false;
    }
    PCIE_RUNTIME_STATE.with_mut(|state| {
        state.reset();
        state.initialized = true;
        state.link_ready = true;
        state.last_status = PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP;
        state.cfg_vendor_device = PCIE_VL805_PCI_VENDOR_DEVICE;
        state.cfg_class_revision = PCIE_VL805_EXPECTED_CLASS_REV;
    });
    PCIE_RUNTIME_FLAGS.fetch_or(
        ENGINE_STATE_INITIALIZED
            | ENGINE_STATE_DESCRIPTOR_READY
            | ENGINE_STATE_RESOURCE_READY
            | ENGINE_STATE_HW_READY,
        Ordering::AcqRel,
    );
    true
}

#[inline(never)]
fn mark_engine_initialized(command: DriverTaskCommandRecord) -> Result<u16, u16> {
    let hot_path = command.arg0;
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_LOADED,
        command.aux0,
    );
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        if descriptor.hot_path != hot_path
            || RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != hot_path
        {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_READY,
            command.aux0,
        );
        let Some(flags) = runtime_flags_for_hot_path(hot_path) else {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        };
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_BEGIN,
            command.aux0,
        );
        if !descriptor_resources_ready_with_progress(
            descriptor,
            hot_path,
            command.sequence,
            command.aux0,
        ) {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCES_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_BEGIN,
            command.aux0,
        );
        let detail = runtime_engine_init(command.sequence, command.aux0, hot_path, descriptor);
        match detail {
            Ok(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_DONE,
                command.aux0,
            ),
            Err(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
                command.aux0,
            ),
        }
        let detail = detail?;
        let mut bits = ENGINE_STATE_INITIALIZED | ENGINE_STATE_DESCRIPTOR_READY;
        bits |= ENGINE_STATE_RESOURCE_READY | ENGINE_STATE_HW_READY;
        flags.fetch_or(bits, Ordering::AcqRel);
        Ok(detail)
    })
}

fn reset_sdio_register_shadows() {
    SDIO_TRANSFER_MODE_SHADOW.store(0, Ordering::Release);
    SDIO_TRANSFER_MODE_SHADOW_VALID.store(false, Ordering::Release);
    SDIO_ACTIVE_CLOCK_HZ.store(0, Ordering::Release);
    SDIO_REQUESTED_CLOCK_HZ.store(0, Ordering::Release);
}

fn reset_cyw43_sdio_pair_runtime_entry_state() {
    RUNTIME_DESCRIPTOR.store(DriverRuntimeInitDescriptor::empty());
    RUNTIME_INIT_HOT_PATH.store(0, Ordering::Release);
    RUNTIME_INIT_FLAGS.store(0, Ordering::Release);
    CYW43_RUNTIME_FLAGS.store(0, Ordering::Release);
    CYW43_TX_COUNT.store(0, Ordering::Release);
    CYW43_SDIO_BUS_LINK_SEQ.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_ACTIVE.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_EXPECTED_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_ISSUED_UNKNOWN.store(false, Ordering::Release);
    CYW43_SDIO_CHILD_LATE_POLLS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_START_TICKS.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_REAP_TIMEOUT_CYCLES.store(0, Ordering::Release);
    CYW43_SDIO_CHILD_RESTART_SIGNALLED.store(false, Ordering::Release);
    CYW43_SDIO_PAIR_RESTART_REQUIRED.store(false, Ordering::Release);
    CYW43_DPC_DEFERRED.store(false, Ordering::Release);
    CYW43_ACTIVE_PARENT_SEQUENCE.store(0, Ordering::Release);
    CYW43_LAST_FAULT_DETAIL.store(FAULT_NONE as u32, Ordering::Release);
    CYW43_LAST_FAULT_RESULT.store(0, Ordering::Release);
    CYW43_LAST_RELEASE_PHASE.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(0, Ordering::Release);
    SDIO_RUNTIME_FLAGS.store(0, Ordering::Release);
    SDIO_CMD_COUNT.store(0, Ordering::Release);
    SDIO_LAST_TRANSFER_FAILURE.store(0, Ordering::Release);
    SDIO_LAST_TRANSFER_RAW_ERROR_STATUS.store(0, Ordering::Release);
    reset_sdio_register_shadows();
    CYW43_CONTROL_REQUEST.clear();
    #[cfg(target_os = "none")]
    CYW43_FOREGROUND_TRANSACTION.with_mut(Cyw43ForegroundTransaction::clear);
    SDIO_RUNTIME_STATE.with_mut(SdioRuntimeState::reset);
    CYW43_RUNTIME_STATE.with_mut(Cyw43RuntimeState::reset_for_pair_restart);
}

#[inline(never)]
fn runtime_engine_init(
    sequence: u32,
    aux0: u32,
    hot_path: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RUNTIME_ENTRY,
        aux0,
    );
    match hot_path {
        HOT_PATH_USB_KEYBOARD => runtime_engine_init_usb(sequence, aux0, descriptor),
        HOT_PATH_HDMI_TEXT => runtime_engine_init_hdmi(descriptor),
        HOT_PATH_GENET_NIC => runtime_engine_init_genet(),
        HOT_PATH_CYW43_WIFI => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_ENGINE_INIT_BRANCH,
                aux0,
            );
            runtime_engine_init_cyw43(sequence, aux0, descriptor)
        }
        HOT_PATH_SDIO_HOST => runtime_engine_init_sdio(sequence, aux0, descriptor),
        HOT_PATH_PCIE_ROOT => runtime_engine_init_pcie(),
        _ => Ok(FAULT_NONE),
    }
}

#[inline(never)]
fn runtime_engine_init_usb(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    usb_runtime_init(sequence, aux0, descriptor).ok_or(FAULT_DEVICE_UNAVAILABLE)
}

#[inline(never)]
fn runtime_engine_init_hdmi(descriptor: &DriverRuntimeInitDescriptor) -> Result<u16, u16> {
    hdmi_render_boot_diagnostics(descriptor);
    Ok(FAULT_NONE)
}

#[inline(never)]
fn runtime_engine_init_genet() -> Result<u16, u16> {
    GENET_RUNTIME_STATE.with_mut(|state| {
        genet_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_cyw43(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    CYW43_RUNTIME_STATE.with_mut(|state| {
        cyw43_runtime_init(sequence, aux0, state, descriptor)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_sdio(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_ENGINE_INIT_BRANCH,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_BEGIN,
        aux0,
    );
    reset_sdio_register_shadows();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_DONE,
        aux0,
    );
    #[cfg(test)]
    {
        sdio_runtime_init(sequence, aux0, descriptor)
    }
    #[cfg(not(test))]
    {
        // Production SDIO engine initialization is admitted only by
        // `service_sdio_pwrseq_command_turn`, which retains the command across
        // bounded phases. Reaching this immediate path is a fail-closed
        // programming error, never a synchronous power-sequence fallback.
        let _ = descriptor;
        Err(DRIVER_RUNTIME_SDIO_INIT_DETAIL_INVALID_DESCRIPTOR)
    }
}

#[inline(never)]
fn runtime_engine_init_pcie() -> Result<u16, u16> {
    PCIE_RUNTIME_STATE.with_mut(|state| {
        pcie_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

fn descriptor_resource_range_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.resource_range_count).min(DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES)
}

fn descriptor_bus_link_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.bus_link_count).min(DRIVER_RUNTIME_INIT_MAX_BUS_LINKS)
}

fn descriptor_valid_resource_ranges(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        if !descriptor.resource_ranges[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_bus_links(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        if !descriptor.bus_links[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_irqs(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.irq_count) > DRIVER_RUNTIME_INIT_MAX_IRQS {
        return false;
    }
    let mut index = 0usize;
    while index < usize::from(descriptor.irq_count) {
        if !descriptor.irqs[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_ref(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if descriptor.magic != DRIVER_RUNTIME_INIT_MAGIC
        || descriptor.version != DRIVER_RUNTIME_INIT_VERSION
        || descriptor.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
        || descriptor.hot_path < HOT_PATH_SERIAL_CONSOLE
        || descriptor.hot_path > HOT_PATH_PCIE_ROOT
        || descriptor.role_bit == 0
        || (descriptor.flags & DRIVER_RUNTIME_INIT_REQUIRED_FLAGS)
            != DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
        || descriptor.shared_page_count == 0
        || usize::from(descriptor.mmio_page_count) > DRIVER_RUNTIME_INIT_MAX_MMIO_PAGES
        || usize::from(descriptor.dma_page_count) > DRIVER_RUNTIME_INIT_MAX_DMA_PAGES
        || usize::from(descriptor.shared_page_count) > DRIVER_RUNTIME_INIT_MAX_SHARED_PAGES
        || usize::from(descriptor.irq_count) > DRIVER_RUNTIME_INIT_MAX_IRQS
        || usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS
        || usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES
    {
        return false;
    }
    if descriptor.irq_count == 0 {
        if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY == 0 {
            return false;
        }
    } else if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0 {
        return false;
    }
    if descriptor.bus_link_count != 0 && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS == 0
    {
        return false;
    }
    descriptor_valid_resource_ranges(descriptor)
        && descriptor_valid_irqs(descriptor)
        && descriptor_valid_bus_links(descriptor)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeNotificationRoute {
    Unavailable,
    SdioOwner,
    Cyw43Client,
}

const DPC_REASON_SDIO_CARD_INTERRUPT: u16 = 1;
const DPC_REASON_SDIO_SOURCE_PENDING: u16 = 2;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcRingPublishResult {
    Published(u32),
    Full,
    BadEpoch,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcRingConsumeResult {
    Event(DriverRuntimeDpcEventEntry),
    Empty,
    BadEpoch,
    BadSequence,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DpcConsumerWakeRoute {
    SelfSignal,
    OwnerRearm,
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SdioDpcCaptureDisposition {
    HoldPending,
    InspectSource,
    Fault,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcReadinessAction {
    Drain,
    AdvanceAndRearm,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcContinuationRoute {
    DeferredLocalWork,
    CompleteAndRearm,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcRxStartRoute {
    PostStatus,
    Firstread,
    NextFrame(usize),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcEventFrameHint {
    None,
    Frame(usize),
    Invalid,
}

const fn cyw43_dpc_event_frame_hint(flags: u16, signal_status: u32) -> Cyw43DpcEventFrameHint {
    if flags & DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING == 0 {
        return Cyw43DpcEventFrameHint::None;
    }
    let frame_len = signal_status as usize;
    if cyw43_sdpcm_frame_len_valid(frame_len) {
        Cyw43DpcEventFrameHint::Frame(frame_len)
    } else {
        Cyw43DpcEventFrameHint::Invalid
    }
}

const fn cyw43_dpc_post_route_marks_quiescent(route: Cyw43DpcRxStartRoute) -> bool {
    matches!(route, Cyw43DpcRxStartRoute::PostStatus)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcInvalidFirstreadRoute {
    Quiescent,
    Recover,
}

const fn cyw43_dpc_invalid_firstread_route(prefix_empty: bool) -> Cyw43DpcInvalidFirstreadRoute {
    if prefix_empty {
        Cyw43DpcInvalidFirstreadRoute::Quiescent
    } else {
        Cyw43DpcInvalidFirstreadRoute::Recover
    }
}

const fn dpc_generation_next(current: u32) -> u32 {
    let next = current.wrapping_add(1);
    if next == 0 {
        1
    } else {
        next
    }
}

const fn dpc_generation_reset_request_valid(current: u32, requested: u32) -> bool {
    current != 0 && requested == dpc_generation_next(current)
}

const fn cyw43_engine_generation(static_epoch: u32, active_epoch: u32) -> u32 {
    if active_epoch == 0 {
        static_epoch
    } else {
        active_epoch
    }
}

fn dpc_event_ring_reset_generation(
    ring: &mut DriverRuntimeDpcEventRing,
    current: u32,
    requested: u32,
) -> bool {
    if !ring.valid()
        || ring.epoch != current
        || !dpc_generation_reset_request_valid(current, requested)
    {
        return false;
    }
    // Failure counters are cumulative boot history, but the flag word is the
    // health of the admitted generation. A successfully re-enumerated E+1
    // starts clean and earns its own poison/overrun state independently.
    let overruns = ring.overruns;
    let ack_failures = ring.ack_failures;
    *ring = DriverRuntimeDpcEventRing::empty(requested);
    ring.overruns = overruns;
    ring.ack_failures = ack_failures;
    true
}

const fn cyw43_generation_reset_completion_exact(
    completion: DriverTaskCompletionRecord,
    sequence: u32,
    requested: u32,
) -> bool {
    completion.sequence == sequence
        && completion.code == COMPLETION_PROGRESS
        && completion.detail == FAULT_NONE
        && completion.result == requested
        && completion.frame.offset == 0
        && completion.frame.len == 0
        && completion.frame.flags == 0
}

const fn cyw43_dpc_activation_completion_exact(
    completion: DriverTaskCompletionRecord,
    sequence: u32,
    requested: u32,
) -> bool {
    cyw43_generation_reset_completion_exact(completion, sequence, requested)
}

const fn cyw43_dpc_activation_failure_result(completion: DriverTaskCompletionRecord) -> u32 {
    // Preserve the SDIO owner's primitive completion class and typed detail:
    // rejection is 0x0005_0001, transfer failure is 0x0005_5103, and a
    // malformed success is 0x0001_0000. Zero remains reserved for no exact
    // completion (issued-unknown/link timeout).
    (completion.code as u32) << 16 | completion.detail as u32
}

fn cyw43_complete_generation_reset(
    state: &mut Cyw43RuntimeState,
    completion: DriverTaskCompletionRecord,
    sequence: u32,
    requested: u32,
) -> bool {
    if !cyw43_generation_reset_completion_exact(completion, sequence, requested) {
        return false;
    }
    state.dpc_pending_epoch = requested;
    state.dpc_active_sequence = 0;
    // This exact completion was received over the sealed CYW43 -> SDIO child
    // link after the SDIO owner finished the card-reset turn. Treat it as the
    // authoritative proof that the persistent transport link remains usable
    // while the hardware/card state is deliberately rebuilt. A coalesced
    // child/DPC notification may clear the transient readiness observation
    // made before the child call; carrying that stale false value into
    // TRANSPORT_INIT incorrectly reports 0x5310 before CMD0 can start.
    // Re-establish only the compiler-declared link state here. This does not
    // adopt the reset card, advance the epoch, unmask CARD_INT, or admit any
    // legacy/direct SDIO route; those remain gated by fresh enumeration and
    // the separate GENERATION_COMMIT completion below.
    state.bus_link_ready = true;
    state.dpc_link_ready = true;
    // The SDIO owner has completed the WL_ON power cycle, so the former RCA,
    // Function-1 enable, block sizes, host/card lane, and backplane aperture
    // are no longer valid. Force the normal typed TRANSPORT_INIT state machine
    // to perform CMD0/CMD5/CMD3/CMD7 and every subsequent attach gate before
    // another firmware byte can be admitted.
    state.sdio_transport_enumerated = false;
    state.transport_ready = false;
    state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_START;
    state.reset_card_init_state();
    state.backplane_window_valid = false;
    state.recovery_required = true;
    true
}

fn cyw43_complete_generation_commit(
    state: &mut Cyw43RuntimeState,
    completion: DriverTaskCompletionRecord,
    sequence: u32,
) -> bool {
    let requested = state.dpc_pending_epoch;
    if requested == 0 || !cyw43_generation_reset_completion_exact(completion, sequence, requested) {
        return false;
    }
    state.dpc_shared_epoch = requested;
    state.dpc_pending_epoch = 0;
    state.dpc_active_sequence = 0;
    state.recovery_required = false;
    CYW43_SDIO_BUS_LINK_SEQ.store(
        cyw43_sdio_bus_link_sequence_seed(requested),
        Ordering::Release,
    );
    true
}

fn cyw43_mark_issued_unknown(state: &mut Cyw43RuntimeState) {
    state.sdpcm_tx_write_ambiguous = true;
    state.recovery_required = true;
    state.initialized = false;
    state.transport_ready = false;
    state.firmware_released = false;
}

const fn cyw43_dpc_continuation_route(
    rxskip: bool,
    pending_intstatus: u32,
    rxpending: bool,
    sdpcm_next_frame_len: u16,
    _rx_queue_count: u8,
) -> Cyw43DpcContinuationRoute {
    if !rxskip && (pending_intstatus != 0 || rxpending || sdpcm_next_frame_len != 0) {
        Cyw43DpcContinuationRoute::DeferredLocalWork
    } else {
        // A bounded software queue is root-facing work, not device/DPC work.
        // Completing the event unmasks CARD_INT and lets endpoint RX_POLL
        // commands run even while queued frames await root consumption.
        Cyw43DpcContinuationRoute::CompleteAndRearm
    }
}

const fn cyw43_dpc_rx_start_route(
    rxskip: bool,
    pending_intstatus: u32,
    next_frame_len: u16,
    next_frame_from_rframe: bool,
) -> Cyw43DpcRxStartRoute {
    if rxskip {
        return Cyw43DpcRxStartRoute::PostStatus;
    }
    let next_frame_len = next_frame_len as usize;
    if cyw43_sdpcm_frame_len_valid(next_frame_len) {
        if next_frame_from_rframe {
            // RFRAME is only a readiness hint. Linux still obtains the
            // authoritative length/complement pair from the fixed first read.
            return Cyw43DpcRxStartRoute::Firstread;
        }
        return Cyw43DpcRxStartRoute::NextFrame(next_frame_len);
    }
    if pending_intstatus & I_HMB_FRAME_IND != 0 {
        // A latched FRAME_IND authorizes the fixed Function 2 first read even
        // when the diagnostic RFRAME count is zero.
        Cyw43DpcRxStartRoute::Firstread
    } else {
        Cyw43DpcRxStartRoute::PostStatus
    }
}

const fn cyw43_should_run_deferred_dpc(
    command_ready: bool,
    deferred: bool,
    child_active: bool,
) -> bool {
    deferred && !command_ready && !child_active
}

const fn cyw43_dpc_child_blocks_cursor(global_child_active: bool, dpc_child_active: bool) -> bool {
    global_child_active && !dpc_child_active
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcPendingCommandRoute {
    Execute,
    Wait,
    ExecuteRecovery,
    FailQuarantined,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43ForegroundDpcWatermark {
    command_sequence: u32,
    captured_consumer: u32,
    producer_watermark: u32,
    armed: bool,
}

impl Cyw43ForegroundDpcWatermark {
    const fn empty() -> Self {
        Self {
            command_sequence: 0,
            captured_consumer: 0,
            producer_watermark: 0,
            armed: false,
        }
    }

    const fn capture(command_sequence: u32, consumer: u32, producer: u32) -> Self {
        Self {
            command_sequence,
            captured_consumer: consumer,
            producer_watermark: producer,
            armed: producer.wrapping_sub(consumer) <= DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32,
        }
    }

    const fn belongs_to(self, command_sequence: u32) -> bool {
        self.armed && self.command_sequence == command_sequence
    }

    const fn includes(self, event_sequence: u32) -> bool {
        if !self.armed {
            return false;
        }
        let captured = self.producer_watermark.wrapping_sub(self.captured_consumer);
        let event_offset = event_sequence.wrapping_sub(self.captured_consumer);
        event_offset != 0 && event_offset <= captured
    }
}

const fn cyw43_dpc_pending_command_route(
    cursor_active: bool,
    child_active: bool,
    quarantined: bool,
    explicit_recovery: bool,
) -> Cyw43DpcPendingCommandRoute {
    if child_active {
        Cyw43DpcPendingCommandRoute::Wait
    } else if quarantined && explicit_recovery {
        Cyw43DpcPendingCommandRoute::ExecuteRecovery
    } else if quarantined {
        Cyw43DpcPendingCommandRoute::FailQuarantined
    } else if cursor_active || child_active {
        Cyw43DpcPendingCommandRoute::Wait
    } else {
        Cyw43DpcPendingCommandRoute::Execute
    }
}

fn cyw43_dpc_command_requires_preflight(
    pending_command: bool,
    cursor_active: bool,
    child_active: bool,
    quarantined: bool,
    event: DpcRingConsumeResult,
    watermark: Cyw43ForegroundDpcWatermark,
) -> bool {
    if !pending_command || cursor_active || child_active || quarantined {
        return false;
    }
    match event {
        DpcRingConsumeResult::Event(event) => watermark.includes(event.sequence),
        // A malformed or wrong-generation ring is never bypassed by a
        // foreground card operation. Its normal service path records the
        // precise fault and preserves CARD_INT quarantine semantics.
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => true,
        DpcRingConsumeResult::Empty => false,
    }
}

fn cyw43_dpc_explicit_recovery_command(
    command: DriverTaskCommandRecord,
    generation_transport_pending: bool,
) -> bool {
    if command.opcode == OPCODE_SERVICE
        && command.frame.len == 0
        && command_is_engine_init_aux(command.aux0)
    {
        return true;
    }
    if !generation_transport_pending
        || command.opcode != OPCODE_SERVICE
        || command.arg0 != HOT_PATH_CYW43_WIFI
        || command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        return false;
    }
    // A generation reset deliberately leaves the DPC ring poisoned until the
    // CYW43 owner has rebuilt the card-side transport and obtained the SDIO
    // owner's exact GENERATION_COMMIT completion. TRANSPORT_INIT is the only
    // foreground command capable of performing that bounded transition. It
    // must cross quarantine for each one-phase service turn; all firmware,
    // control, RX, and TX descriptors remain rejected until commit clears the
    // recovery state.
    read_cyw43_command_descriptor(command.frame).is_some_and(|descriptor| {
        descriptor.valid() && descriptor.op == DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT
    })
}

const fn cyw43_dpc_generation_quarantined(recovery_required: bool, issued_unknown: bool) -> bool {
    recovery_required || issued_unknown
}

const fn cyw43_dpc_post_capture_has_work(
    rxskip: bool,
    rx_service_quiescent: bool,
    next_frame_len: u16,
    pending_intstatus: u32,
) -> bool {
    pending_intstatus & (I_HMB_FC_CHANGE | I_HMB_HOST_INT) != 0
        || (!rxskip
            && (pending_intstatus & I_HMB_FRAME_IND != 0
                || !rx_service_quiescent
                || next_frame_len != 0))
}

const fn cyw43_dpc_latched_causes(sampled_status: u32) -> u32 {
    sampled_status & (I_HMB_FRAME_IND | I_HMB_FC_CHANGE | I_HMB_HOST_INT)
}

const fn cyw43_dpc_w1c_status(sampled_status: u32) -> u32 {
    sampled_status & HOSTINTMASK
}

const fn cyw43_dpc_status_requires_ack(sampled_status: u32) -> bool {
    cyw43_dpc_w1c_status(sampled_status) != 0
}

const fn runtime_command_poll_due(pending_intake: bool) -> bool {
    !pending_intake
}

const fn cyw43_post_release_dpc_missing(firmware_released: bool, dpc_link_ready: bool) -> bool {
    firmware_released && !dpc_link_ready
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43DpcRecoveryDrainRoute {
    PostNak,
    Retry,
    Quarantine,
}

const fn cyw43_dpc_recovery_drain_route(
    frame_count: u16,
    completed_polls: usize,
    deadline_expired: bool,
) -> Cyw43DpcRecoveryDrainRoute {
    if frame_count == 0 {
        Cyw43DpcRecoveryDrainRoute::PostNak
    } else if completed_polls >= CYW43_RX_SOURCE_RECOVERY_DRAIN_POLLS || deadline_expired {
        Cyw43DpcRecoveryDrainRoute::Quarantine
    } else {
        Cyw43DpcRecoveryDrainRoute::Retry
    }
}

const fn cyw43_dpc_recovery_settle_ready(
    start_ticks: u64,
    settle_cycles: u64,
    current_ticks: u64,
    fallback_turns: u8,
) -> bool {
    if start_ticks != 0 && settle_cycles != 0 && current_ticks != 0 {
        current_ticks.wrapping_sub(start_ticks) >= settle_cycles
    } else {
        fallback_turns == 0
    }
}

fn cyw43_dpc_child_completion_matches(
    child: Cyw43DpcChild,
    completion: DriverTaskCompletionRecord,
) -> bool {
    completion.code == child.expected_code
        && completion.detail == FAULT_NONE
        && completion.result == child.expected_result
        && completion.frame.offset == child.expected_frame_offset
        && completion.frame.len == child.expected_frame_len
        && completion.frame.flags == 0
}

const fn cyw43_dpc_readiness_action(
    initialized: bool,
    transport_ready: bool,
    firmware_execution_started: bool,
    firmware_released: bool,
) -> Cyw43DpcReadinessAction {
    if initialized && transport_ready && firmware_execution_started && firmware_released {
        Cyw43DpcReadinessAction::Drain
    } else {
        // Pre-release CARD_INT edges are advisory: firmware/card bring-up uses
        // synchronous register polling. Completing the event prevents an early
        // edge from leaving SDHCI signaling masked across firmware release.
        Cyw43DpcReadinessAction::AdvanceAndRearm
    }
}

fn dpc_event_ring_publish(
    ring: &mut DriverRuntimeDpcEventRing,
    epoch: u32,
    host_int_status: u32,
    signal_status: u32,
    reason: u16,
    flags: u16,
) -> DpcRingPublishResult {
    if !ring.valid() || ring.epoch != epoch {
        return DpcRingPublishResult::BadEpoch;
    }
    if ring.producer.wrapping_sub(ring.consumer) >= DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH as u32 {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN;
        ring.overruns = ring.overruns.saturating_add(1);
        return DpcRingPublishResult::Full;
    }
    let sequence = ring.producer.wrapping_add(1);
    let slot = ring.producer as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
    ring.entries[slot] = DriverRuntimeDpcEventEntry {
        sequence,
        host_int_status,
        signal_status,
        reason,
        flags,
    };
    ring.producer = sequence;
    DpcRingPublishResult::Published(sequence)
}

fn dpc_event_ring_publish_sequence_last(
    sequence: u32,
    event: DriverRuntimeDpcEventEntry,
    mut write_sequence: impl FnMut(u32) -> bool,
    mut write_body: impl FnMut(DriverRuntimeDpcEventEntry) -> bool,
    mut release: impl FnMut(),
    mut write_producer: impl FnMut(u32) -> bool,
) -> bool {
    if !write_sequence(0) || !write_body(event) {
        return false;
    }
    release();
    if !write_sequence(sequence) {
        return false;
    }
    release();
    write_producer(sequence)
}

fn dpc_event_ring_peek(ring: &DriverRuntimeDpcEventRing, epoch: u32) -> DpcRingConsumeResult {
    if !ring.valid() || ring.epoch != epoch {
        return DpcRingConsumeResult::BadEpoch;
    }
    if ring.producer == ring.consumer {
        return DpcRingConsumeResult::Empty;
    }
    let expected = ring.consumer.wrapping_add(1);
    let slot = ring.consumer as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
    let event = ring.entries[slot];
    if event.sequence != expected || !event.valid() {
        return DpcRingConsumeResult::BadSequence;
    }
    DpcRingConsumeResult::Event(event)
}

fn dpc_event_ring_advance(ring: &mut DriverRuntimeDpcEventRing, epoch: u32, sequence: u32) -> bool {
    if !matches!(
        dpc_event_ring_peek(ring, epoch),
        DpcRingConsumeResult::Event(event) if event.sequence == sequence
    ) {
        return false;
    }
    ring.consumer = sequence;
    true
}

fn dpc_event_ring_set_owner_health(
    ring: &mut DriverRuntimeDpcEventRing,
    card_irq_masked: bool,
    ack_pending: bool,
    poisoned: bool,
    ack_failed: bool,
) {
    // These flags describe only the current admitted epoch. Historical owner
    // failures remain visible through cumulative overrun/ack counters when a
    // clean post-re-enumeration generation replaces a poisoned ring.
    ring.flags &= !(DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED
        | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING);
    if card_irq_masked {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED;
    }
    if ack_pending {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_ACK_PENDING;
    }
    if poisoned {
        ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED;
    }
    if ack_failed {
        ring.ack_failures = ring.ack_failures.saturating_add(1);
    }
}

fn dpc_consumer_wake_route(ring: &DriverRuntimeDpcEventRing, epoch: u32) -> DpcConsumerWakeRoute {
    match dpc_event_ring_peek(ring, epoch) {
        DpcRingConsumeResult::Event(_) => DpcConsumerWakeRoute::SelfSignal,
        DpcRingConsumeResult::Empty => DpcConsumerWakeRoute::OwnerRearm,
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => {
            DpcConsumerWakeRoute::Fault
        }
    }
}

const fn cyw43_dpc_event_has_source(flags: u16) -> bool {
    flags
        & (DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT
            | DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING)
        != 0
}

fn sdio_dpc_capture_disposition(
    ring: &DriverRuntimeDpcEventRing,
    epoch: u32,
) -> SdioDpcCaptureDisposition {
    match dpc_event_ring_peek(ring, epoch) {
        DpcRingConsumeResult::Event(_) => SdioDpcCaptureDisposition::HoldPending,
        DpcRingConsumeResult::Empty => SdioDpcCaptureDisposition::InspectSource,
        DpcRingConsumeResult::BadEpoch | DpcRingConsumeResult::BadSequence => {
            SdioDpcCaptureDisposition::Fault
        }
    }
}

#[cfg(target_os = "none")]
#[derive(Clone, Copy)]
enum RuntimeRingWindowKind {
    Local,
    SdioOwner,
}

#[cfg(target_os = "none")]
#[derive(Clone, Copy)]
enum RuntimeVolatileWidth {
    U8,
    U16,
    U32,
}

#[cfg(target_os = "none")]
impl RuntimeVolatileWidth {
    const fn bytes(self) -> usize {
        match self {
            Self::U8 => core::mem::size_of::<u8>(),
            Self::U16 => core::mem::size_of::<u16>(),
            Self::U32 => core::mem::size_of::<u32>(),
        }
    }
}

#[cfg(target_os = "none")]
fn runtime_volatile_read(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
) -> Option<u32> {
    let (base, len) = match kind {
        RuntimeRingWindowKind::Local => (DRIVER_TASK_RING_VADDR, DRIVER_TASK_RING_PAGE_BYTES),
        RuntimeRingWindowKind::SdioOwner => (
            DRIVER_TASK_SDIO_BUS_RING_VADDR,
            DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
        ),
    };
    let bytes = width.bytes();
    let end = offset.checked_add(bytes)?;
    let address = base.checked_add(offset)?;
    if base == 0 || end > len || address & (bytes - 1) != 0 {
        return None;
    }
    // SAFETY: The caller supplies one of the fixed HAL-admitted runtime
    // mappings. Checked arithmetic, range validation, and natural alignment
    // keep this single volatile primitive access inside that mapping.
    unsafe {
        Some(match width {
            RuntimeVolatileWidth::U8 => u32::from(core::ptr::read_volatile(address as *const u8)),
            RuntimeVolatileWidth::U16 => u32::from(u16::from_le(core::ptr::read_volatile(
                address as *const u16,
            ))),
            RuntimeVolatileWidth::U32 => {
                u32::from_le(core::ptr::read_volatile(address as *const u32))
            }
        })
    }
}

#[cfg(target_os = "none")]
fn runtime_volatile_write(
    kind: RuntimeRingWindowKind,
    offset: usize,
    width: RuntimeVolatileWidth,
    value: u32,
) -> bool {
    let (base, len) = match kind {
        RuntimeRingWindowKind::Local => (DRIVER_TASK_RING_VADDR, DRIVER_TASK_RING_PAGE_BYTES),
        RuntimeRingWindowKind::SdioOwner => (
            DRIVER_TASK_SDIO_BUS_RING_VADDR,
            DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
        ),
    };
    let bytes = width.bytes();
    let Some(end) = offset.checked_add(bytes) else {
        return false;
    };
    let Some(address) = base.checked_add(offset) else {
        return false;
    };
    if base == 0 || end > len || address & (bytes - 1) != 0 {
        return false;
    }
    // SAFETY: The caller supplies one of the fixed HAL-admitted runtime
    // mappings. Checked arithmetic, range validation, and natural alignment
    // keep this single volatile primitive access inside that mapping.
    unsafe {
        match width {
            RuntimeVolatileWidth::U8 => {
                core::ptr::write_volatile(address as *mut u8, value as u8);
            }
            RuntimeVolatileWidth::U16 => {
                core::ptr::write_volatile(address as *mut u16, (value as u16).to_le());
            }
            RuntimeVolatileWidth::U32 => {
                core::ptr::write_volatile(address as *mut u32, value.to_le());
            }
        }
    }
    true
}

#[cfg(target_os = "none")]
#[derive(Clone, Copy)]
struct RuntimeRingWindow {
    kind: RuntimeRingWindowKind,
    start: usize,
    len: usize,
}

#[cfg(target_os = "none")]
impl RuntimeRingWindow {
    const fn local() -> Self {
        Self {
            kind: RuntimeRingWindowKind::Local,
            start: 0,
            len: DRIVER_TASK_RING_PAGE_BYTES,
        }
    }

    fn sdio_owner() -> Option<Self> {
        RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
            let link = descriptor_notification_dpc_link(descriptor)?;
            (descriptor.hot_path == HOT_PATH_CYW43_WIFI
                && link.owner_hot_path == HOT_PATH_SDIO_HOST
                && usize::from(link.event_offset).checked_add(usize::from(link.event_len))?
                    <= DRIVER_TASK_RING_PAGE_BYTES)
                .then_some(Self {
                    kind: RuntimeRingWindowKind::SdioOwner,
                    start: 0,
                    len: DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES,
                })
        })
    }

    fn dpc_at(base: usize) -> Option<Self> {
        let offset = usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let len = core::mem::size_of::<DriverRuntimeDpcEventRing>();
        if base == DRIVER_TASK_RING_VADDR.checked_add(offset)? {
            let link_valid = RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
                descriptor_notification_dpc_link(descriptor).is_some_and(|link| {
                    descriptor.hot_path == HOT_PATH_SDIO_HOST
                        && usize::from(link.event_offset) == offset
                        && usize::from(link.event_len) == len
                })
            });
            return link_valid.then_some(Self {
                kind: RuntimeRingWindowKind::Local,
                start: offset,
                len,
            });
        }
        if base == DRIVER_TASK_SDIO_BUS_RING_VADDR.checked_add(offset)? {
            let owner = Self::sdio_owner()?;
            return Some(Self {
                kind: owner.kind,
                start: offset,
                len,
            });
        }
        None
    }

    fn primitive_offset(self, offset: usize, width: RuntimeVolatileWidth) -> Option<usize> {
        let end = offset.checked_add(width.bytes())?;
        if end > self.len {
            return None;
        }
        self.start.checked_add(offset)
    }

    fn read_u8(self, offset: usize) -> Option<u8> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U8)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U8)
            .map(|value| value as u8)
    }

    fn write_u8(self, offset: usize, value: u8) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U8) else {
            return false;
        };
        runtime_volatile_write(
            self.kind,
            absolute,
            RuntimeVolatileWidth::U8,
            u32::from(value),
        )
    }

    fn read_u16(self, offset: usize) -> Option<u16> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U16)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U16)
            .map(|value| value as u16)
    }

    fn write_u16(self, offset: usize, value: u16) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U16) else {
            return false;
        };
        runtime_volatile_write(
            self.kind,
            absolute,
            RuntimeVolatileWidth::U16,
            u32::from(value),
        )
    }

    fn read_u32(self, offset: usize) -> Option<u32> {
        let absolute = self.primitive_offset(offset, RuntimeVolatileWidth::U32)?;
        runtime_volatile_read(self.kind, absolute, RuntimeVolatileWidth::U32)
    }

    fn write_u32(self, offset: usize, value: u32) -> bool {
        let Some(absolute) = self.primitive_offset(offset, RuntimeVolatileWidth::U32) else {
            return false;
        };
        runtime_volatile_write(self.kind, absolute, RuntimeVolatileWidth::U32, value)
    }
}

#[cfg(target_os = "none")]
fn dpc_event_ring_decode(window: RuntimeRingWindow) -> Option<DriverRuntimeDpcEventRing> {
    let mut ring = DriverRuntimeDpcEventRing::empty(
        window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, epoch))?,
    );
    ring.magic = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, magic))?;
    ring.version = window.read_u16(core::mem::offset_of!(DriverRuntimeDpcEventRing, version))?;
    ring.len = window.read_u16(core::mem::offset_of!(DriverRuntimeDpcEventRing, len))?;
    ring.producer = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, producer))?;
    ring.consumer = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer))?;
    ring.flags = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, flags))?;
    ring.overruns = window.read_u32(core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns))?;
    ring.ack_failures = window.read_u32(core::mem::offset_of!(
        DriverRuntimeDpcEventRing,
        ack_failures
    ))?;
    // The producer is the ring-level commit word. The SDIO owner publishes it
    // only after the selected entry's sequence and body are globally visible.
    // Acquire before observing any entry so body loads cannot move ahead of
    // that publication boundary.
    driver_task_shared_load_barrier();
    let entries_offset = core::mem::offset_of!(DriverRuntimeDpcEventRing, entries);
    for (index, entry) in ring.entries.iter_mut().enumerate() {
        let offset = entries_offset
            .checked_add(index.checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())?)?;
        entry.sequence = window
            .read_u32(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence))?;
        // Each entry sequence is its slot-level commit word. An acquire here
        // pairs with the publisher's sequence-last release, preventing a valid
        // sequence from being combined with a stale or partially written body.
        driver_task_shared_load_barrier();
        entry.host_int_status = window.read_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
        )?;
        entry.signal_status = window
            .read_u32(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status))?;
        entry.reason =
            window.read_u16(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason))?;
        entry.flags =
            window.read_u16(offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags))?;
    }
    Some(ring)
}

#[cfg(target_os = "none")]
fn dpc_event_ring_encode(window: RuntimeRingWindow, ring: DriverRuntimeDpcEventRing) -> bool {
    let header_written = window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, magic),
        ring.magic,
    ) && window.write_u16(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, version),
        ring.version,
    ) && window.write_u16(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, len),
        ring.len,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, epoch),
        ring.epoch,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, producer),
        ring.producer,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        ring.consumer,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        ring.flags,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns),
        ring.overruns,
    ) && window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        ring.ack_failures,
    );
    if !header_written {
        return false;
    }
    let entries_offset = core::mem::offset_of!(DriverRuntimeDpcEventRing, entries);
    ring.entries.iter().enumerate().all(|(index, entry)| {
        let Some(offset) = index
            .checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())
            .and_then(|entry_offset| entries_offset.checked_add(entry_offset))
        else {
            return false;
        };
        window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence),
            entry.sequence,
        ) && window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
            entry.host_int_status,
        ) && window.write_u32(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status),
            entry.signal_status,
        ) && window.write_u16(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason),
            entry.reason,
        ) && window.write_u16(
            offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags),
            entry.flags,
        )
    })
}

#[cfg(target_os = "none")]
fn dpc_event_ring_read_at(base: usize) -> DriverRuntimeDpcEventRing {
    driver_task_shared_invalidate_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
    let ring = RuntimeRingWindow::dpc_at(base)
        .and_then(dpc_event_ring_decode)
        .unwrap_or_else(|| DriverRuntimeDpcEventRing::empty(0));
    ring
}

#[cfg(target_os = "none")]
fn dpc_event_ring_initialize_at(base: usize, epoch: u32) {
    let ring = DriverRuntimeDpcEventRing::empty(epoch);
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return;
    };
    if !dpc_event_ring_encode(window, ring) {
        return;
    }
    driver_task_shared_clean_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
}

#[cfg(target_os = "none")]
fn dpc_event_ring_reset_generation_at(base: usize, current: u32, requested: u32) -> bool {
    let mut ring = dpc_event_ring_read_at(base);
    if !dpc_event_ring_reset_generation(&mut ring, current, requested) {
        return false;
    }
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return false;
    };
    if !dpc_event_ring_encode(window, ring) {
        return false;
    }
    driver_task_shared_clean_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
    true
}

#[cfg(target_os = "none")]
fn dpc_event_ring_publish_at(
    base: usize,
    epoch: u32,
    host_int_status: u32,
    signal_status: u32,
    reason: u16,
    flags: u16,
) -> DpcRingPublishResult {
    let mut snapshot = dpc_event_ring_read_at(base);
    let result = dpc_event_ring_publish(
        &mut snapshot,
        epoch,
        host_int_status,
        signal_status,
        reason,
        flags,
    );
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return DpcRingPublishResult::BadEpoch;
    };
    match result {
        DpcRingPublishResult::Published(sequence) => {
            let slot = sequence.wrapping_sub(1) as usize % DRIVER_RUNTIME_DPC_EVENT_RING_DEPTH;
            let event = snapshot.entries[slot];
            let Some(entry_offset) = slot
                .checked_mul(core::mem::size_of::<DriverRuntimeDpcEventEntry>())
                .and_then(|offset| {
                    core::mem::offset_of!(DriverRuntimeDpcEventRing, entries).checked_add(offset)
                })
            else {
                return DpcRingPublishResult::BadEpoch;
            };
            if !dpc_event_ring_publish_sequence_last(
                sequence,
                event,
                |value| {
                    window.write_u32(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, sequence),
                        value,
                    )
                },
                |event| {
                    window.write_u32(
                        entry_offset
                            + core::mem::offset_of!(DriverRuntimeDpcEventEntry, host_int_status),
                        event.host_int_status,
                    ) && window.write_u32(
                        entry_offset
                            + core::mem::offset_of!(DriverRuntimeDpcEventEntry, signal_status),
                        event.signal_status,
                    ) && window.write_u16(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, reason),
                        event.reason,
                    ) && window.write_u16(
                        entry_offset + core::mem::offset_of!(DriverRuntimeDpcEventEntry, flags),
                        event.flags,
                    )
                },
                driver_task_shared_store_barrier,
                |value| {
                    window.write_u32(
                        core::mem::offset_of!(DriverRuntimeDpcEventRing, producer),
                        value,
                    )
                },
            ) {
                return DpcRingPublishResult::BadEpoch;
            }
        }
        DpcRingPublishResult::Full => {
            if !window.write_u32(
                core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
                snapshot.flags,
            ) || !window.write_u32(
                core::mem::offset_of!(DriverRuntimeDpcEventRing, overruns),
                snapshot.overruns,
            ) {
                return DpcRingPublishResult::BadEpoch;
            }
        }
        DpcRingPublishResult::BadEpoch => {}
    }
    driver_task_shared_clean_range(base, core::mem::size_of::<DriverRuntimeDpcEventRing>());
    result
}

#[cfg(target_os = "none")]
fn dpc_event_ring_peek_at(base: usize, epoch: u32) -> DpcRingConsumeResult {
    let ring = dpc_event_ring_read_at(base);
    dpc_event_ring_peek(&ring, epoch)
}

#[cfg(target_os = "none")]
fn dpc_event_ring_advance_at(base: usize, epoch: u32, sequence: u32) -> bool {
    let mut ring = dpc_event_ring_read_at(base);
    if !dpc_event_ring_advance(&mut ring, epoch, sequence) {
        return false;
    }
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return false;
    };
    if !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        sequence,
    ) {
        return false;
    }
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, consumer),
        core::mem::size_of::<u32>(),
    );
    true
}

#[cfg(target_os = "none")]
fn dpc_event_ring_set_owner_health_at(
    base: usize,
    card_irq_masked: bool,
    ack_pending: bool,
    poisoned: bool,
    ack_failed: bool,
) -> bool {
    let mut snapshot = dpc_event_ring_read_at(base);
    if !snapshot.valid() {
        return false;
    }
    dpc_event_ring_set_owner_health(
        &mut snapshot,
        card_irq_masked,
        ack_pending,
        poisoned,
        ack_failed,
    );
    let Some(window) = RuntimeRingWindow::dpc_at(base) else {
        return false;
    };
    if !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        snapshot.flags,
    ) || !window.write_u32(
        core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        snapshot.ack_failures,
    ) {
        return false;
    }
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, flags),
        core::mem::size_of::<u32>(),
    );
    driver_task_shared_clean_range(
        base + core::mem::offset_of!(DriverRuntimeDpcEventRing, ack_failures),
        core::mem::size_of::<u32>(),
    );
    true
}

fn descriptor_notification_dpc_link(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeBusLinkDescriptor> {
    if descriptor.bus_link_count != 1
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS == 0
        || !descriptor_valid_bus_links(descriptor)
    {
        return None;
    }
    let link = descriptor.bus_links[0];
    if !link.notification_dpc_valid()
        || !link.sealed_for_client(descriptor.task_key, descriptor.hot_path)
    {
        return None;
    }
    let role =
        link.flags & (DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER);
    let topology_matches = match descriptor.hot_path {
        HOT_PATH_CYW43_WIFI => {
            role == DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT
                && link.peer_hot_path == HOT_PATH_SDIO_HOST
                && link.local_notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
                && link.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT
        }
        HOT_PATH_SDIO_HOST => {
            role == DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER
                && link.peer_hot_path == HOT_PATH_CYW43_WIFI
                && link.local_notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
                && link.peer_notification_slot == DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT
        }
        _ => false,
    };
    topology_matches.then_some(link)
}

fn descriptor_sdio_irq(
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<DriverRuntimeIrqDescriptor> {
    if descriptor.hot_path != HOT_PATH_SDIO_HOST
        || descriptor.irq_count != 1
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0
        || descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY != 0
    {
        return None;
    }
    let irq = descriptor.irqs[0];
    (irq.valid()
        && irq.irq == DRIVER_RUNTIME_SDIO_IRQ
        && irq.badge == DRIVER_RUNTIME_SDIO_IRQ_BADGE
        && irq.handler_slot == DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT
        && irq.notification_slot == DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT
        && irq.trigger == DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL)
        .then_some(irq)
}

fn runtime_notification_route(
    descriptor: &DriverRuntimeInitDescriptor,
) -> RuntimeNotificationRoute {
    let Some(_link) = descriptor_notification_dpc_link(descriptor) else {
        return RuntimeNotificationRoute::Unavailable;
    };
    match descriptor.hot_path {
        HOT_PATH_SDIO_HOST if descriptor_sdio_irq(descriptor).is_some() => {
            RuntimeNotificationRoute::SdioOwner
        }
        HOT_PATH_CYW43_WIFI => RuntimeNotificationRoute::Cyw43Client,
        _ => RuntimeNotificationRoute::Unavailable,
    }
}

fn descriptor_resource_pages_by_kind(descriptor: &DriverRuntimeInitDescriptor, kind: u16) -> u16 {
    let mut total = 0u16;
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind {
            total = total.saturating_add(range.page_count);
        }
        index += 1;
    }
    total
}

fn descriptor_resource_pages_or_count(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    fallback: u16,
) -> u16 {
    let pages = descriptor_resource_pages_by_kind(descriptor, kind);
    if pages == 0 {
        fallback
    } else {
        pages
    }
}

fn descriptor_has_resource_range_at(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
    expected_vaddr: u64,
    min_pages: u16,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind
            && range.tag == tag
            && range.vaddr == expected_vaddr
            && range.page_count >= min_pages
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag && range.page_count != 0 {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_pointer_free_bus_link(
    descriptor: &DriverRuntimeInitDescriptor,
    owner_hot_path: u32,
    channel_id: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        let link = descriptor.bus_links[index];
        if link.owner_hot_path == owner_hot_path
            && link.channel_id == channel_id
            && link.sealed_for_client(descriptor.task_key, descriptor.hot_path)
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_hdmi_ready(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    descriptor_valid_ref(descriptor)
        && descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER != 0
        && descriptor.framebuffer.valid()
}

fn publish_resource_check_progress(progress: Option<(u32, u32)>, phase: u32) {
    if let Some((sequence, aux0)) = progress {
        publish_runtime_progress(sequence, phase, aux0);
    }
}

fn descriptor_resources_ready_with_progress(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    sequence: u32,
    aux0: u32,
) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, Some((sequence, aux0)))
}

fn descriptor_resources_ready(descriptor: &DriverRuntimeInitDescriptor, hot_path: u32) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, None)
}

fn descriptor_resources_ready_checked(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    progress: Option<(u32, u32)>,
) -> bool {
    if !descriptor_valid_ref(descriptor) {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_INVALID,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_VALID,
    );
    if descriptor.hot_path != hot_path {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_READY,
    );
    let mmio_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        descriptor.mmio_page_count,
    );
    let dma_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        descriptor.dma_page_count,
    );
    let shared_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
        descriptor.shared_page_count,
    );
    publish_resource_check_progress(progress, DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_TOTALS_READY);
    match hot_path {
        HOT_PATH_USB_KEYBOARD => {
            if mmio_pages < USB_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_USB_XHCI,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    USB_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < USB_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    USB_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < USB_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_has_pointer_free_bus_link(
                descriptor,
                HOT_PATH_PCIE_ROOT,
                DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_HDMI_TEXT => {
            if mmio_pages < HDMI_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < HDMI_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < HDMI_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_hdmi_ready(descriptor)
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_FRAMEBUFFER,
                    DRIVER_RUNTIME_RESOURCE_TAG_HDMI_FRAMEBUFFER,
                    DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_GENET_NIC => {
            if mmio_pages < GENET_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_GENET_REGS,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    GENET_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < GENET_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    GENET_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < GENET_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_CYW43_WIFI => {
            if mmio_pages < CYW43_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < CYW43_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < CYW43_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    CYW43_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if descriptor_has_resource_range(
                descriptor,
                DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FORBIDDEN_PRESENT,
                );
                return false;
            }
            if descriptor_notification_dpc_link(descriptor).is_none() {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_SDIO_HOST => {
            let pwrseq_vaddr =
                DRIVER_TASK_DEVICE_MMIO_VADDR.saturating_add(DRIVER_TASK_RING_PAGE_BYTES);
            if mmio_pages < SDIO_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    1,
                )
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
                    pwrseq_vaddr as u64,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < SDIO_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < SDIO_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if descriptor_notification_dpc_link(descriptor).is_none() {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_PCIE_ROOT => {
            if mmio_pages < PCIE_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_PCIE_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    PCIE_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if shared_pages < PCIE_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    PCIE_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        _ => {
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
            );
            false
        }
    }
}

fn engine_initialized(flags: &AtomicU32) -> bool {
    flags.load(Ordering::Acquire) & ENGINE_STATE_INITIALIZED != 0
}

fn runtime_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> Option<DriverRuntimeResourceRangeDescriptor> {
    let mut index = 0usize;
    while index < descriptor.resource_range_count as usize {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag {
            return Some(range);
        }
        index += 1;
    }
    None
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_read(base: usize, offset: usize) -> u32 {
    // SAFETY: descriptor admission proves `base` is the single uncached Pi 4
    // firmware-mailbox page whose active call authority was handed to the SDIO
    // owner; root retains only a dormant, software-guarded mapping. Every caller
    // supplies a 32-bit register offset within that page.
    unsafe { core::ptr::read_volatile((base + offset) as *const u32) }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_write(base: usize, offset: usize, value: u32) {
    // SAFETY: descriptor admission proves `base` is the single uncached Pi 4
    // firmware-mailbox page whose active call authority was handed to the SDIO
    // owner; root retains only a dormant, software-guarded mapping. Every caller
    // supplies a writable 32-bit register offset within that page.
    unsafe { core::ptr::write_volatile((base + offset) as *mut u32, value) };
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_request(vaddr: usize, level: u32) {
    for index in 0..8usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 8 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_SET_GPIO_STATE);
    write_dma_u32(vaddr + 12, 8);
    // Linux's Raspberry Pi firmware transport always submits property tags
    // with a zero request/response-size word. The firmware replaces this word
    // with its response flag and returned-byte count.
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    write_dma_u32(vaddr + 24, level);
    dma_store_barrier();
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_get_config_request(vaddr: usize) {
    for index in 0..11usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 11 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_GET_GPIO_CONFIG);
    write_dma_u32(vaddr + 12, 20);
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    dma_store_barrier();
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_config_request(vaddr: usize, polarity: u32) {
    for index in 0..12usize {
        write_dma_u32(vaddr + index * core::mem::size_of::<u32>(), 0);
    }
    write_dma_u32(vaddr, 12 * core::mem::size_of::<u32>() as u32);
    write_dma_u32(vaddr + 8, PI4_WIFI_PWRSEQ_TAG_SET_GPIO_CONFIG);
    write_dma_u32(vaddr + 12, 24);
    write_dma_u32(vaddr + 16, PI4_WIFI_PWRSEQ_MAILBOX_REQUEST_SIZE);
    write_dma_u32(vaddr + 20, PI4_WIFI_PWRSEQ_GPIO_WL_ON);
    write_dma_u32(vaddr + 24, PI4_WIFI_PWRSEQ_GPIO_DIRECTION_OUT);
    write_dma_u32(vaddr + 28, polarity);
    write_dma_u32(vaddr + 32, 0);
    write_dma_u32(vaddr + 36, 0);
    write_dma_u32(vaddr + 40, 0);
    dma_store_barrier();
}

fn sdio_wifi_pwrseq_linux_response_fault(status: u32, returned_gpio: u32) -> u32 {
    let mut reason = 0;
    if status != PI4_WIFI_PWRSEQ_MAILBOX_RESPONSE_SUCCESS {
        reason |= DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GLOBAL_STATUS;
    }
    if returned_gpio != 0 {
        reason |= DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GPIO_TOKEN;
    }
    reason
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_response_complete(vaddr: usize) -> Result<(), u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0).then_some(()).ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_config_response_complete(vaddr: usize) -> Result<(), u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0).then_some(()).ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_get_config_response(vaddr: usize) -> Result<u32, u32> {
    dma_load_barrier();
    let reason =
        sdio_wifi_pwrseq_linux_response_fault(read_dma_u32(vaddr + 4), read_dma_u32(vaddr + 20));
    (reason == 0)
        .then(|| read_dma_u32(vaddr + 28))
        .ok_or(reason)
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_resources() -> Option<(usize, usize, u32)> {
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let mailbox = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
    )?;
    let request = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST,
    )?;
    if mailbox.page_count != 1
        || request.page_count < 1
        || request.paddr > 0x3fff_ffff
        || request.paddr & 0xf != 0
    {
        return None;
    }
    Some((
        mailbox.vaddr as usize,
        request.vaddr as usize,
        request.paddr as u32 & 0x3fff_fff0,
    ))
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_encode_mailbox_op(request_vaddr: usize, op: SdioWifiPwrseqMailboxOp) {
    match op {
        SdioWifiPwrseqMailboxOp::GetConfig => {
            sdio_wifi_pwrseq_encode_get_config_request(request_vaddr);
        }
        SdioWifiPwrseqMailboxOp::SetConfig { polarity } => {
            sdio_wifi_pwrseq_encode_config_request(request_vaddr, polarity);
        }
        SdioWifiPwrseqMailboxOp::SetState { level } => {
            sdio_wifi_pwrseq_encode_request(request_vaddr, level);
        }
    }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_response(
    request_vaddr: usize,
    op: SdioWifiPwrseqMailboxOp,
) -> Result<u32, u32> {
    match op {
        SdioWifiPwrseqMailboxOp::GetConfig => sdio_wifi_pwrseq_get_config_response(request_vaddr),
        SdioWifiPwrseqMailboxOp::SetConfig { .. } => {
            sdio_wifi_pwrseq_config_response_complete(request_vaddr).map(|()| 0)
        }
        SdioWifiPwrseqMailboxOp::SetState { .. } => {
            sdio_wifi_pwrseq_response_complete(request_vaddr).map(|()| 0)
        }
    }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn sdio_wifi_pwrseq_mailbox_turn(
    cursor: &mut SdioPwrseqMailboxCursor,
    op: SdioWifiPwrseqMailboxOp,
) -> SdioPwrseqMailboxTurn {
    let Some((mailbox_vaddr, request_vaddr, request_addr)) = sdio_wifi_pwrseq_mailbox_resources()
    else {
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Resource);
    };
    if !cursor.active() {
        let deadline = runtime_deadline_from_millis_or_iterations(
            PI4_WIFI_PWRSEQ_MAILBOX_TIMEOUT_MS,
            PI4_WIFI_PWRSEQ_MAILBOX_FALLBACK_TURNS,
        );
        if !matches!(deadline, RuntimeDeadline::Counter { .. }) {
            return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Timer);
        }
        sdio_wifi_pwrseq_encode_mailbox_op(request_vaddr, op);
        for _ in 0..PI4_WIFI_PWRSEQ_DRAIN_LIMIT {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS0)
                & PI4_WIFI_PWRSEQ_MAILBOX_EMPTY
                != 0
            {
                break;
            }
            let _ = sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_READ);
        }
        *cursor = SdioPwrseqMailboxCursor {
            phase: SdioPwrseqMailboxPhase::WaitSend,
            op,
            request_addr,
            overall_deadline: deadline,
        };
    } else if cursor.op != op || cursor.request_addr != request_addr {
        *cursor = SdioPwrseqMailboxCursor::idle();
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
            reason: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_CURSOR,
        });
    }

    if runtime_deadline_expired(&mut cursor.overall_deadline) {
        *cursor = SdioPwrseqMailboxCursor::idle();
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Timeout);
    }
    match cursor.phase {
        SdioPwrseqMailboxPhase::Idle => {
            SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
                reason: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_PHASE,
            })
        }
        SdioPwrseqMailboxPhase::WaitSend => {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS1)
                & PI4_WIFI_PWRSEQ_MAILBOX_FULL
                != 0
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            // The primary 0xc000_0000 VC alias is the hardware-proven Pi 4
            // property-channel address. Post this request exactly once. After
            // publication the request page is firmware-owned until a matching
            // reply or terminal timeout, so no alias retry may re-encode it.
            let token =
                cursor.request_addr | 0xc000_0000 | PI4_WIFI_PWRSEQ_MAILBOX_CHANNEL_PROPERTY;
            sdio_wifi_pwrseq_mailbox_write(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_WRITE, token);
            dma_store_barrier();
            cursor.phase = SdioPwrseqMailboxPhase::WaitReply;
            SdioPwrseqMailboxTurn::Pending
        }
        SdioPwrseqMailboxPhase::WaitReply => {
            if sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_STATUS0)
                & PI4_WIFI_PWRSEQ_MAILBOX_EMPTY
                != 0
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            let reply = sdio_wifi_pwrseq_mailbox_read(mailbox_vaddr, PI4_WIFI_PWRSEQ_MAILBOX_READ);
            if reply & 0xf != PI4_WIFI_PWRSEQ_MAILBOX_CHANNEL_PROPERTY
                || reply & 0x3fff_fff0 != cursor.request_addr
            {
                return SdioPwrseqMailboxTurn::Pending;
            }
            let value = match sdio_wifi_pwrseq_mailbox_response(request_vaddr, op) {
                Ok(value) => value,
                Err(reason) => {
                    *cursor = SdioPwrseqMailboxCursor::idle();
                    return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
                        reason,
                    });
                }
            };
            *cursor = SdioPwrseqMailboxCursor::idle();
            SdioPwrseqMailboxTurn::Complete(value)
        }
    }
}

#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
static TEST_SDIO_WIFI_PWRSEQ_CALLS: AtomicU32 = AtomicU32::new(0);
#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
static TEST_SDIO_WIFI_PWRSEQ_LEVELS: AtomicU32 = AtomicU32::new(0);

#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
static TEST_SDIO_WIFI_PWRSEQ_CONFIGS: AtomicU32 = AtomicU32::new(0);
#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
static TEST_SDIO_WIFI_PWRSEQ_POSTS: AtomicU32 = AtomicU32::new(0);

#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
fn sdio_wifi_pwrseq_mailbox_turn(
    cursor: &mut SdioPwrseqMailboxCursor,
    op: SdioWifiPwrseqMailboxOp,
) -> SdioPwrseqMailboxTurn {
    if !cursor.active() {
        cursor.phase = SdioPwrseqMailboxPhase::WaitReply;
        cursor.op = op;
        TEST_SDIO_WIFI_PWRSEQ_POSTS.fetch_add(1, Ordering::AcqRel);
        return SdioPwrseqMailboxTurn::Pending;
    }
    if cursor.op != op {
        *cursor = SdioPwrseqMailboxCursor::idle();
        return SdioPwrseqMailboxTurn::Fault(SdioPwrseqMailboxFault::Protocol {
            reason: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_CURSOR,
        });
    }
    *cursor = SdioPwrseqMailboxCursor::idle();
    match op {
        SdioWifiPwrseqMailboxOp::GetConfig => SdioPwrseqMailboxTurn::Complete(0),
        SdioWifiPwrseqMailboxOp::SetConfig { .. } => {
            TEST_SDIO_WIFI_PWRSEQ_CONFIGS.fetch_add(1, Ordering::AcqRel);
            SdioPwrseqMailboxTurn::Complete(0)
        }
        SdioWifiPwrseqMailboxOp::SetState { level } => {
            TEST_SDIO_WIFI_PWRSEQ_CALLS.fetch_add(1, Ordering::AcqRel);
            let _ = TEST_SDIO_WIFI_PWRSEQ_LEVELS.fetch_update(
                Ordering::AcqRel,
                Ordering::Acquire,
                |seen| Some((seen << 1) | (level & 1)),
            );
            SdioPwrseqMailboxTurn::Complete(0)
        }
    }
}

fn runtime_shared_buffer_bytes(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    let mut index = 0usize;
    while index < descriptor.resource_range_count as usize {
        let range = descriptor.resource_ranges[index];
        if range.kind == DRIVER_RUNTIME_RESOURCE_KIND_SHARED
            && range.vaddr == DRIVER_TASK_SHARED_BUFFER_VADDR as u64
        {
            return range.bytes.min(usize::MAX as u64) as usize;
        }
        index += 1;
    }
    0
}

fn runtime_bus_addr(descriptor: &DriverRuntimeInitDescriptor, paddr: u64) -> u64 {
    (paddr & descriptor.bus_alias_and) | descriptor.bus_alias_or
}

fn runtime_resource_paddr_at(
    descriptor: &DriverRuntimeInitDescriptor,
    range: DriverRuntimeResourceRangeDescriptor,
    offset: usize,
) -> Option<u64> {
    let page = offset / DRIVER_TASK_RING_PAGE_BYTES;
    if page >= usize::from(range.page_count) {
        return None;
    }
    let page_offset = offset % DRIVER_TASK_RING_PAGE_BYTES;
    if range.flags & DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS != 0 {
        return range.paddr.checked_add(offset as u64);
    }
    let index = usize::from(range.first_page_index).checked_add(page)?;
    let paddr = match range.kind {
        DRIVER_RUNTIME_RESOURCE_KIND_DMA => descriptor.dma_pages.get(index)?.paddr,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED => descriptor.shared_pages.get(index)?.paddr,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO => descriptor.mmio_pages.get(index)?.paddr,
        _ => 0,
    };
    if paddr == 0 {
        return None;
    }
    paddr.checked_add(page_offset as u64)
}

fn runtime_resource_bus_addr_at(
    descriptor: &DriverRuntimeInitDescriptor,
    range: DriverRuntimeResourceRangeDescriptor,
    offset: usize,
) -> Option<u64> {
    runtime_resource_paddr_at(descriptor, range, offset)
        .map(|paddr| runtime_bus_addr(descriptor, paddr))
}

fn ring_slot(index: u16, slots: usize) -> usize {
    if slots == 0 {
        0
    } else {
        usize::from(index) % slots
    }
}

fn ring_distance(newer: u16, older: u16) -> u16 {
    newer.wrapping_sub(older)
}

const fn genet_rx_owned_len_status() -> u32 {
    ((GENET_RX_BUF_LENGTH as u32) << GENET_DMA_BUFLENGTH_SHIFT) | GENET_DMA_OWN
}

const fn genet_tx_len_status(len: usize) -> u32 {
    ((len as u32) << GENET_DMA_BUFLENGTH_SHIFT)
        | (GENET_DMA_DEFAULT_QTAG << GENET_DMA_TX_QTAG_SHIFT)
        | GENET_DMA_TX_APPEND_CRC
        | GENET_DMA_SOP
        | GENET_DMA_EOP
}

const fn genet_decode_rx_len(len_status: u32) -> usize {
    ((len_status >> GENET_DMA_BUFLENGTH_SHIFT) & GENET_DMA_BUFLENGTH_MASK) as usize
}

const fn genet_rx_payload_len(len_status: u32) -> Option<usize> {
    let length = genet_decode_rx_len(len_status);
    if length <= GENET_RX_BUF_OFFSET || length > GENET_RX_BUF_OFFSET + GENET_MAX_FRAME_LEN {
        None
    } else {
        Some(length - GENET_RX_BUF_OFFSET)
    }
}

const fn genet_tx_dma_len(frame_len: usize) -> Option<usize> {
    let Some(total) = frame_len.checked_add(GENET_TX_BUF_OFFSET) else {
        return None;
    };
    if frame_len == 0 || frame_len > GENET_MAX_FRAME_LEN || total > DRIVER_TASK_RING_PAGE_BYTES {
        None
    } else {
        Some(total)
    }
}

const fn genet_ring_end_addr(ring_descs: usize) -> u32 {
    let words = ring_descs.saturating_mul(GENET_DMA_DESC_SIZE) / 4;
    words.saturating_sub(1) as u32
}

const fn genet_ring_buffer_size(ring_descs: usize) -> u32 {
    ((ring_descs as u32) << GENET_DMA_RING_SIZE_SHIFT) | GENET_RX_BUF_LENGTH as u32
}

const fn genet_dma_fc_thresh_value(ring_descs: usize) -> u32 {
    (GENET_DMA_FC_THRESH_LO << 16) | ((ring_descs as u32) >> 4)
}

const fn genet_rx_desc_offset(slot: usize) -> Option<usize> {
    match slot.checked_mul(GENET_DMA_DESC_SIZE) {
        Some(offset) => GENET_RX_OFF.checked_add(offset),
        None => None,
    }
}

const fn genet_tx_desc_offset(slot: usize) -> Option<usize> {
    match slot.checked_mul(GENET_DMA_DESC_SIZE) {
        Some(offset) => GENET_TX_OFF.checked_add(offset),
        None => None,
    }
}

#[inline(never)]
fn service_engine_init(command: DriverTaskCommandRecord) -> Option<DriverTaskCompletionRecord> {
    let init_aux = command_is_engine_init_aux(command.aux0);
    if !init_aux {
        return None;
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
        command.aux0,
    );
    if command.opcode != OPCODE_SERVICE {
        return Some(DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_REJECTED_COMMAND,
        ));
    }
    if command.frame.len != 0 {
        return Some(DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_REJECTED_COMMAND,
        ));
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
        command.aux0,
    );
    match mark_engine_initialized(command) {
        Ok(detail) => {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
                command.aux0,
            );
            Some(DriverTaskCompletionRecord::progress_with_detail(
                command.sequence,
                detail,
                1,
            ))
        }
        Err(detail) => Some(DriverTaskCompletionRecord::fault(command.sequence, detail)),
    }
}

fn service_serial(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if command.aux0 == SERIAL_RUNTIME_AUX_INIT {
        SERIAL_RUNTIME_RX_QUEUE.with_mut(SerialRuntimeRxQueue::reset);
        serial_init_mini_uart();
        return DriverTaskCompletionRecord::progress(command.sequence, 1);
    }
    if command.aux0 == DRIVER_RUNTIME_SERIAL_TX_IDLE_AUX && command.frame.len == 0 {
        return serial_tx_idle_completion(command.sequence, serial_mini_uart_tx_idle());
    }
    if command.frame.len == 0 {
        let limit = command
            .budget
            .max_bytes
            .min(MAX_DRIVER_TASK_FRAME_BYTES as u32)
            .min(MINI_UART_RX_DRAIN_LIMIT as u32) as usize;
        let read = serial_read_frame(limit);
        return if read == 0 {
            DriverTaskCompletionRecord::idle(command.sequence)
        } else {
            DriverTaskCompletionRecord::frame_ready(command.sequence, read as u16)
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    serial_preserve_rx_into_runtime_queue(MINI_UART_RX_DRAIN_LIMIT);
    let limit = serial_frame_budget_limit(command.budget, command.frame.len);
    let written = serial_write_frame(command.frame, limit);
    serial_preserve_rx_into_runtime_queue(MINI_UART_RX_DRAIN_LIMIT);
    if written == 0 {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        DriverTaskCompletionRecord::progress(command.sequence, written as u32)
    }
}

const fn serial_tx_idle_completion(
    sequence: u32,
    transmitter_idle: bool,
) -> DriverTaskCompletionRecord {
    if transmitter_idle {
        DriverTaskCompletionRecord::progress(sequence, 1)
    } else {
        DriverTaskCompletionRecord::idle(sequence)
    }
}

#[cfg(target_os = "none")]
fn serial_mini_uart_tx_idle() -> bool {
    // SAFETY: The linked serial runtime owns the admitted mini-UART MMIO page;
    // MU_LSR is read-only and bit 6 proves both FIFO and shifter are empty.
    let lsr = unsafe {
        core::ptr::read_volatile(
            (DRIVER_TASK_DEVICE_MMIO_VADDR + MINI_UART_LSR_OFFSET) as *const u32,
        )
    };
    lsr & MINI_UART_LSR_TX_IDLE != 0
}

#[cfg(not(target_os = "none"))]
fn serial_mini_uart_tx_idle() -> bool {
    true
}

fn serial_frame_budget_limit(budget: DriverTaskBudgetGrant, frame_len: u16) -> usize {
    if budget.max_ops == 0 || budget.max_frames == 0 || budget.max_bytes == 0 {
        return 0;
    }
    (budget.max_ops as usize)
        .min(budget.max_bytes as usize)
        .min(frame_len as usize)
        .min(MAX_DRIVER_TASK_FRAME_BYTES)
}

#[inline(never)]
fn usb_runtime_init(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<u16> {
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_INIT_ENTRY, aux0);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_ACCESS_BEGIN,
        aux0,
    );
    let detail = USB_RUNTIME_STATE.with_mut(|state| {
        if state.initialized {
            if usb_keyboard_poll_ready_state(state) {
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY;
                return Some(DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY);
            }
            return usb_runtime_enumeration_detail(state).or(Some(state.init_detail));
        }
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_RESET_BEGIN,
            aux0,
        );
        state.reset();
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_RESET_DONE,
            aux0,
        );
        publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_HW_ENTRY, aux0);
        let detail = usb_runtime_init_hw(sequence, aux0, descriptor, state)?;
        state.initialized = true;
        Some(detail)
    });
    if detail.is_some() {
        USB_RUNTIME_FLAGS.fetch_or(
            ENGINE_STATE_INITIALIZED | ENGINE_STATE_HW_READY,
            Ordering::AcqRel,
        );
    }
    detail
}

fn genet_runtime_init(state: &mut GenetRuntimeState) -> bool {
    state.reset();
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        let Some(dma_range) = runtime_resource_range(
            descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        ) else {
            return false;
        };
        if dma_range.page_count < GENET_REQUIRED_DMA_PAGES {
            return false;
        }
        let initialized = genet_runtime_init_hw(descriptor, state);
        state.initialized = initialized;
        initialized
    })
}

fn genet_completion_result(state: &GenetRuntimeState, tx_free: u16, tx_in_flight: u16) -> u32 {
    driver_runtime_genet_completion_result(DriverRuntimeGenetCompletionResultParts {
        tx_free,
        tx_in_flight,
        rx_queue_count: state.rx_queue_count,
        rx_queue_high_water: state.rx_queue_high_water,
        rx_max_drained_per_turn: state.rx_max_drained_per_turn,
        rx_drain_budget_hit: state.rx_drain_budget_hits != 0,
        rx_byte_budget_hit: state.rx_byte_budget_hits != 0,
        rx_overflow_seen: state.rx_queue_overflows != 0,
    })
}

fn service_genet_runtime(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&GENET_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len == 0 {
        let (poll, completed, tx_free, in_flight, result) = GENET_RUNTIME_STATE.with_mut(|state| {
            let poll = genet_runtime_poll_rx(state, command.budget);
            let result =
                genet_completion_result(state, state.tx_last_free, state.tx_last_in_flight);
            (
                poll,
                state.tx_last_reclaim,
                state.tx_last_free,
                state.tx_last_in_flight,
                result,
            )
        });
        return match poll {
            GenetRxPoll::Idle => {
                genet_tx_idle_completion(command.sequence, completed, tx_free, in_flight, result)
            }
            GenetRxPoll::Frame { len, flags } => {
                GENET_RX_COUNT.fetch_add(1, Ordering::AcqRel);
                GENET_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
                genet_rx_frame_ready_completion(
                    command.sequence,
                    len as u16,
                    flags,
                    completed,
                    result,
                )
            }
            GenetRxPoll::BudgetExhausted(detail) => {
                DriverTaskCompletionRecord::budget_exhausted(command.sequence, detail)
            }
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if let Err(detail) = genet_tx_budget_allows_frame(command.budget, command.frame.len) {
        return DriverTaskCompletionRecord::budget_exhausted(command.sequence, detail);
    }
    let (written, completed, tx_free, in_flight, result) = GENET_RUNTIME_STATE.with_mut(|state| {
        let written = genet_runtime_submit_tx(state, command.frame);
        let result = genet_completion_result(state, state.tx_last_free, state.tx_last_in_flight);
        (
            written,
            state.tx_last_reclaim,
            state.tx_last_free,
            state.tx_last_in_flight,
            result,
        )
    });
    if written == 0 {
        genet_tx_idle_completion(command.sequence, completed, tx_free, in_flight, result)
    } else {
        GENET_TX_COUNT.fetch_add(1, Ordering::AcqRel);
        GENET_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        genet_tx_progress_completion(
            command.sequence,
            written as u32,
            completed,
            tx_free,
            in_flight,
        )
    }
}

fn cyw43_runtime_init(
    sequence: u32,
    aux0: u32,
    state: &mut Cyw43RuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_STATE_RESET_BEGIN,
        aux0,
    );
    if !cyw43_engine_init_can_reset(CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire)) {
        // Main-loop engine init can observe ACTIVE only after an issued-unknown
        // child timeout: ordinary child calls are synchronous. Do not clear
        // that quarantine until the main-loop reaper observes the old owner's
        // stable sequence-matching terminal completion.
        cyw43_record_last_fault_with_result(FAULT_CYW43_TRANSPORT_BUS_LINK, 0);
        return false;
    }
    // Engine-init is the only command admitted while a DPC generation is
    // quarantined. Preserve that reason and the active epoch across the local
    // state reset so the SDIO owner receives one exact generation-reset turn
    // before any firmware bytes or SDPCM sequence can be reused.
    let recovery_required = state.recovery_required;
    let previous_generation = state.dpc_shared_epoch;
    if recovery_required
        && state.firmware_execution_started
        && (!state.sdio_transport_enumerated
            || cyw43_hold_armcr4_for_firmware_upload(state).is_err())
    {
        // Do not expose E+1 while the old dongle execution can still mutate
        // Function 2 or assert a new device source. The existing enumerated
        // SDIO transport is the only authority used to halt ARMCR4 here.
        state.recovery_required = true;
        return false;
    }
    state.reset();
    state.recovery_required = recovery_required;
    state.dpc_shared_epoch = previous_generation;
    CYW43_SDIO_BUS_LINK_SEQ.store(0, Ordering::Release);
    CYW43_DPC_DEFERRED.store(false, Ordering::Release);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_STATE_RESET_DONE,
        aux0,
    );
    let has_direct_sdio_mmio = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
    )
    .is_some();
    if has_direct_sdio_mmio {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_FORBIDDEN_SDIO_MMIO,
            aux0,
        );
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_BUS_LINK_CHECK_BEGIN,
        aux0,
    );
    let Some(link) = descriptor_notification_dpc_link(descriptor) else {
        return false;
    };
    let current_generation = cyw43_engine_generation(link.shared_epoch, previous_generation);
    if current_generation == 0 {
        return false;
    }
    state.bus_link_ready = true;
    state.dpc_link_ready = true;
    state.dpc_shared_epoch = current_generation;
    CYW43_SDIO_BUS_LINK_SEQ.store(
        cyw43_sdio_bus_link_sequence_seed(current_generation),
        Ordering::Release,
    );
    #[cfg(target_os = "none")]
    {
        let ring = dpc_event_ring_read_at(
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(link.event_offset),
        );
        if !ring.valid() || ring.epoch != current_generation {
            state.bus_link_ready = false;
            state.dpc_link_ready = false;
            return false;
        }
    }
    if state.recovery_required {
        let requested = dpc_generation_next(current_generation);
        let Some((reset_sequence, completion)) =
            cyw43_reset_sdio_generation_via_bus_link(requested)
        else {
            return false;
        };
        if !cyw43_generation_reset_completion_exact(completion, reset_sequence, requested) {
            return false;
        }
        #[cfg(target_os = "none")]
        {
            let ring = dpc_event_ring_read_at(
                DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(link.event_offset),
            );
            if !ring.valid()
                || ring.epoch != current_generation
                || ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED == 0
            {
                return false;
            }
        }
        if !cyw43_complete_generation_reset(state, completion, reset_sequence, requested) {
            return false;
        }
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_BUS_LINK_READY,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_CHECK_BEGIN,
        aux0,
    );
    state.initialized = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
        DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL,
    )
    .is_some();
    publish_runtime_progress(
        sequence,
        if state.initialized {
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_READY
        } else {
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_MISSING
        },
        aux0,
    );
    #[cfg(all(not(target_os = "none"), not(test)))]
    {
        if state.initialized {
            state.transport_ready = cyw43_transport_init(state).is_ok();
        }
    }
    state.initialized
}

const fn cyw43_engine_init_can_reset(child_active: bool) -> bool {
    !child_active
}

#[cfg(target_os = "none")]
fn cyw43_dpc_prepare_backplane_io(
    state: &Cyw43RuntimeState,
    cursor: &mut Cyw43DpcCursor,
    action: Cyw43DpcAction,
    kind: Cyw43DpcIoKind,
    addr: u32,
    value: u32,
) {
    cursor.action = action;
    cursor.io_kind = kind;
    cursor.io_addr = addr;
    cursor.io_value = value;
    cursor.io_function = 1;
    cursor.io_byte_index = 0;
    cursor.io_frame = DriverFrameDescriptor::empty();
    cursor.io_block_size = 0;
    cursor.io_block_count = 0;
    let window = addr & BACKPLANE_WINDOW_MASK;
    cursor.io_phase = if state.backplane_window_valid && state.backplane_window == window {
        if kind == Cyw43DpcIoKind::WindowOnly {
            Cyw43DpcIoPhase::Idle
        } else {
            Cyw43DpcIoPhase::Transfer
        }
    } else {
        Cyw43DpcIoPhase::WindowLow
    };
}

#[cfg(target_os = "none")]
fn cyw43_dpc_prepare_cmd52_read(cursor: &mut Cyw43DpcCursor, action: Cyw43DpcAction, addr: u32) {
    cursor.action = action;
    cursor.io_kind = Cyw43DpcIoKind::Cmd52Read;
    cursor.io_phase = Cyw43DpcIoPhase::Transfer;
    cursor.io_addr = addr;
    cursor.io_value = 0;
    cursor.io_function = 1;
    cursor.io_byte_index = 0;
    cursor.io_frame = DriverFrameDescriptor {
        offset: CYW43_BACKPLANE_WORD_SCRATCH_OFFSET as u32,
        len: 1,
        flags: 0,
    };
    cursor.io_block_size = 0;
    cursor.io_block_count = 0;
}

#[cfg(target_os = "none")]
fn cyw43_dpc_prepare_cmd52_write(
    cursor: &mut Cyw43DpcCursor,
    action: Cyw43DpcAction,
    function: u8,
    addr: u32,
    value: u8,
) {
    cursor.action = action;
    cursor.io_kind = Cyw43DpcIoKind::Cmd52Write;
    cursor.io_phase = Cyw43DpcIoPhase::Transfer;
    cursor.io_addr = addr;
    cursor.io_value = u32::from(value);
    cursor.io_function = function;
    cursor.io_byte_index = 0;
    cursor.io_frame = DriverFrameDescriptor::empty();
    cursor.io_block_size = 0;
    cursor.io_block_count = 0;
}

#[cfg(target_os = "none")]
fn cyw43_dpc_prepare_function2_read(
    cursor: &mut Cyw43DpcCursor,
    action: Cyw43DpcAction,
    frame: DriverFrameDescriptor,
) {
    let (block_size, block_count) = cyw43_function2_cmd53_shape(usize::from(frame.len));
    cursor.action = action;
    cursor.io_kind = Cyw43DpcIoKind::Function2Read;
    cursor.io_phase = Cyw43DpcIoPhase::Transfer;
    cursor.io_addr = BACKPLANE_32BIT_FLAG;
    cursor.io_value = 0;
    cursor.io_function = 2;
    cursor.io_byte_index = 0;
    cursor.io_frame = frame;
    cursor.io_block_size = block_size;
    cursor.io_block_count = block_count;
}

#[cfg(target_os = "none")]
fn cyw43_dpc_start_capture(state: &Cyw43RuntimeState, cursor: &mut Cyw43DpcCursor) {
    cyw43_dpc_prepare_backplane_io(
        state,
        cursor,
        Cyw43DpcAction::CaptureStatus,
        Cyw43DpcIoKind::BackplaneRead32,
        CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
        0,
    );
}

#[cfg(target_os = "none")]
fn cyw43_dpc_start_rejected_firstread_recovery(cursor: &mut Cyw43DpcCursor) {
    cyw43_dpc_prepare_cmd52_write(
        cursor,
        Cyw43DpcAction::AbortFunction2,
        0,
        SDIO_CCCR_ABORT,
        SDIO_FUNCTION_NUMBER_2,
    );
}

#[cfg(target_os = "none")]
fn cyw43_dpc_start_rframe_or_post(state: &mut Cyw43RuntimeState, cursor: &mut Cyw43DpcCursor) {
    let route = cyw43_dpc_rx_start_route(
        state.rxskip,
        state.pending_intstatus,
        state.sdpcm_next_frame_len,
        state.sdpcm_next_frame_from_rframe,
    );
    if cyw43_dpc_post_route_marks_quiescent(route) {
        state.rx_service_quiescent = true;
        state.rxpending = false;
    }
    match route {
        Cyw43DpcRxStartRoute::PostStatus => {
            // No FRAME_IND and no retained next-length means this RX episode is
            // quiescent after any flow-control/mailbox work. A fresh cause in
            // the post sample reopens work; otherwise the event must terminate
            // and rearm instead of looping while CARD_INT remains masked.
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::PostStatus,
                Cyw43DpcIoKind::BackplaneRead32,
                CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                0,
            );
        }
        Cyw43DpcRxStartRoute::Firstread => {
            if state.sdpcm_next_frame_len != 0 {
                let _ = cyw43_take_sdpcm_next_frame_len(state);
            }
            cursor.actual_frame_len = 0;
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::FifoWindow,
                Cyw43DpcIoKind::WindowOnly,
                CYW43_CHIPCOMMON_BASE,
                0,
            );
        }
        Cyw43DpcRxStartRoute::NextFrame(frame_len) => {
            let _ = cyw43_take_sdpcm_next_frame_len(state);
            cursor.actual_frame_len = frame_len as u16;
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::FifoWindow,
                Cyw43DpcIoKind::WindowOnly,
                CYW43_CHIPCOMMON_BASE,
                0,
            );
        }
    }
}

#[cfg(target_os = "none")]
fn cyw43_dpc_start_hostmail_or_rx(state: &mut Cyw43RuntimeState, cursor: &mut Cyw43DpcCursor) {
    if state.pending_intstatus & I_HMB_HOST_INT != 0 {
        cyw43_dpc_prepare_backplane_io(
            state,
            cursor,
            Cyw43DpcAction::HostmailRead,
            Cyw43DpcIoKind::BackplaneRead32,
            CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOHOSTMAILBOXDATA,
            0,
        );
    } else {
        cyw43_dpc_start_rframe_or_post(state, cursor);
    }
}

#[cfg(target_os = "none")]
fn cyw43_dpc_start_flow_or_hostmail(state: &mut Cyw43RuntimeState, cursor: &mut Cyw43DpcCursor) {
    if state.pending_intstatus & I_HMB_FC_CHANGE != 0 {
        state.pending_intstatus &= !I_HMB_FC_CHANGE;
        state.flowcontrol_all = true;
        cyw43_dpc_prepare_backplane_io(
            state,
            cursor,
            Cyw43DpcAction::FlowAck,
            Cyw43DpcIoKind::BackplaneWrite32,
            CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
            I_HMB_FC_CHANGE,
        );
    } else {
        state.pending_intstatus &= !I_HMB_FC_STATE;
        cyw43_dpc_start_hostmail_or_rx(state, cursor);
    }
}

#[cfg(target_os = "none")]
fn cyw43_dpc_submit_current_io(cursor: &mut Cyw43DpcCursor) -> bool {
    if cyw43_dpc_turn_route(cursor) != Cyw43DpcTurnRoute::SubmitChild {
        return false;
    }
    let sequence = cyw43_sdio_bus_link_next_sequence();
    let command = match cursor.io_phase {
        Cyw43DpcIoPhase::WindowLow | Cyw43DpcIoPhase::WindowMid | Cyw43DpcIoPhase::WindowHigh => {
            let (low, mid, high) = cyw43_backplane_window_register_bytes(cursor.io_addr);
            let (addr, value) = match cursor.io_phase {
                Cyw43DpcIoPhase::WindowLow => (SBSDIO_FUNC1_SBADDRLOW, low),
                Cyw43DpcIoPhase::WindowMid => (SBSDIO_FUNC1_SBADDRMID, mid),
                Cyw43DpcIoPhase::WindowHigh => (SBSDIO_FUNC1_SBADDRHIGH, high),
                Cyw43DpcIoPhase::Idle | Cyw43DpcIoPhase::Transfer => return false,
            };
            if !write_sdio_bus_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET, value) {
                return false;
            }
            driver_task_shared_store_barrier();
            driver_task_shared_clean_range(
                DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DATA_OFFSET,
                1,
            );
            sdio_bus_link_cmd52_descriptor_command(sequence, true, 1, addr)
        }
        Cyw43DpcIoPhase::Transfer => match cursor.io_kind {
            Cyw43DpcIoKind::BackplaneRead32 => {
                let frame = DriverFrameDescriptor {
                    offset: CYW43_BACKPLANE_WORD_SCRATCH_OFFSET as u32,
                    len: 4,
                    flags: 0,
                };
                let arg = sdio_cmd53_arg(
                    false,
                    1,
                    cyw43_backplane_function_addr(cursor.io_addr),
                    true,
                    0,
                    4,
                );
                sdio_bus_link_descriptor_command(
                    sequence,
                    SDIO_CMD53,
                    arg,
                    DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                    frame,
                    4,
                    0,
                    0,
                )
            }
            Cyw43DpcIoKind::BackplaneWrite32 => {
                let index = usize::from(cursor.io_byte_index);
                let Some(addr) = (cursor.io_addr & BACKPLANE_ADDRESS_MASK)
                    .checked_add(cursor.io_byte_index as u32)
                else {
                    return false;
                };
                let value = cursor.io_value.to_le_bytes()[index];
                if !write_sdio_bus_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET, value) {
                    return false;
                }
                driver_task_shared_store_barrier();
                driver_task_shared_clean_range(
                    DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DATA_OFFSET,
                    1,
                );
                sdio_bus_link_cmd52_descriptor_command(sequence, true, 1, addr)
            }
            Cyw43DpcIoKind::Cmd52Read => sdio_bus_link_cmd52_descriptor_command(
                sequence,
                false,
                cursor.io_function,
                cursor.io_addr,
            ),
            Cyw43DpcIoKind::Cmd52Write => {
                if !write_sdio_bus_payload_byte(
                    CYW43_SDIO_BUS_LINK_DATA_OFFSET,
                    cursor.io_value as u8,
                ) {
                    return false;
                }
                driver_task_shared_store_barrier();
                driver_task_shared_clean_range(
                    DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DATA_OFFSET,
                    1,
                );
                sdio_bus_link_cmd52_descriptor_command(
                    sequence,
                    true,
                    cursor.io_function,
                    cursor.io_addr,
                )
            }
            Cyw43DpcIoKind::Function2Read => {
                let arg = sdio_cmd53_arg(
                    false,
                    2,
                    cursor.io_addr,
                    false,
                    cursor.io_block_count,
                    cursor.io_frame.len,
                );
                sdio_bus_link_descriptor_command(
                    sequence,
                    SDIO_CMD53,
                    arg,
                    DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                    cursor.io_frame,
                    cursor.io_block_size,
                    cursor.io_block_count,
                    0,
                )
            }
            Cyw43DpcIoKind::None | Cyw43DpcIoKind::WindowOnly => return false,
        },
        Cyw43DpcIoPhase::Idle => return false,
    };
    let Some(command) = command else {
        return false;
    };
    let read_frame = match (cursor.io_phase, cursor.io_kind) {
        (Cyw43DpcIoPhase::Transfer, Cyw43DpcIoKind::BackplaneRead32) => DriverFrameDescriptor {
            offset: CYW43_BACKPLANE_WORD_SCRATCH_OFFSET as u32,
            len: 4,
            flags: 0,
        },
        (Cyw43DpcIoPhase::Transfer, Cyw43DpcIoKind::Cmd52Read) => cursor.io_frame,
        (Cyw43DpcIoPhase::Transfer, Cyw43DpcIoKind::Function2Read) => cursor.io_frame,
        _ => DriverFrameDescriptor::empty(),
    };
    cyw43_dpc_child_submit_once(cursor, command, read_frame)
}

#[cfg(target_os = "none")]
fn cyw43_dpc_complete_frame(state: &mut Cyw43RuntimeState, cursor: &mut Cyw43DpcCursor) -> bool {
    let actual_frame_len = usize::from(cursor.actual_frame_len);
    if cyw43_runtime_reject_nested_control_payload(
        state,
        match cyw43_rx_sdpcm_header_prefix_at(
            CYW43_RUNTIME_RX_BUFFER_OFFSET,
            actual_frame_len,
            CYW43_RUNTIME_RX_BUFFER_BYTES,
        ) {
            Some(header) => header,
            None => {
                state.recovery_required = true;
                return false;
            }
        },
    )
    .is_some()
    {
        state.recovery_required = true;
        return false;
    }
    cyw43_runtime_clear_rx_irq_source_after_frame_drain(state);
    let decoded = cyw43_runtime_decode_rx_frame_detailed_for(
        state,
        CYW43_RUNTIME_RX_BUFFER_OFFSET,
        actual_frame_len,
        0,
    );
    if cyw43_dpc_decode_requires_recovery(decoded) {
        state.recovery_required = true;
        return false;
    }
    match decoded {
        Cyw43RxDecodeResult::QueuedOrConsumed | Cyw43RxDecodeResult::ValidNotAdmitted => {
            state.rx_retransmit_pending = false;
            cyw43_record_rx_drain_turn(state, 1);
        }
        Cyw43RxDecodeResult::Frame(_) | Cyw43RxDecodeResult::DecodeMiss => return false,
    }
    cyw43_dpc_start_rframe_or_post(state, cursor);
    true
}

#[cfg(target_os = "none")]
fn cyw43_dpc_finish_post_capture(
    state: &mut Cyw43RuntimeState,
    cursor: &mut Cyw43DpcCursor,
) -> bool {
    if state.rx_service_quiescent
        && state.sdpcm_next_frame_len == 0
        && cursor.captured_status & I_HMB_FRAME_IND == 0
    {
        state.pending_intstatus &= !I_HMB_FRAME_IND;
        state.rxpending = false;
        cyw43_runtime_reset_rx_irq_source_asserted_empty_episode(state);
    }
    if cyw43_dpc_post_capture_has_work(
        state.rxskip,
        state.rx_service_quiescent,
        state.sdpcm_next_frame_len,
        state.pending_intstatus,
    ) {
        // A post-drain status sample can expose mailbox and flow-control work
        // that was not present in the initial capture. Service every retained
        // cause before declaring this event terminal.
        cyw43_dpc_start_flow_or_hostmail(state, cursor);
        return false;
    }
    if state.rxskip {
        // FC_CHANGE and HOST_INT (including NAKHANDLED) were serviced first.
        // The remaining frame cause is terminal for this turn while rxskip
        // stays retained for a future real mailbox acknowledgement.
        state.pending_intstatus &= !I_HMB_FRAME_IND;
        state.rxpending = false;
    }
    cursor.action = Cyw43DpcAction::None;
    cursor.io_kind = Cyw43DpcIoKind::None;
    cursor.io_phase = Cyw43DpcIoPhase::Idle;
    true
}

#[cfg(target_os = "none")]
fn cyw43_dpc_finish_action(
    state: &mut Cyw43RuntimeState,
    cursor: &mut Cyw43DpcCursor,
    value: u32,
) -> bool {
    match cursor.action {
        Cyw43DpcAction::None => true,
        Cyw43DpcAction::CaptureStatus => {
            let sampled = cyw43_dpc_w1c_status(value);
            let captured = cyw43_dpc_latched_causes(sampled);
            cursor.captured_status = captured;
            state.flowcontrol_all = sampled & I_HMB_FC_STATE != 0;
            state.pending_intstatus |= captured;
            if !cyw43_dpc_status_requires_ack(sampled) {
                cyw43_dpc_start_flow_or_hostmail(state, cursor);
            } else {
                cyw43_dpc_prepare_backplane_io(
                    state,
                    cursor,
                    Cyw43DpcAction::AckStatus,
                    Cyw43DpcIoKind::BackplaneWrite32,
                    CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                    sampled,
                );
            }
            false
        }
        Cyw43DpcAction::AckStatus => {
            cyw43_dpc_start_flow_or_hostmail(state, cursor);
            false
        }
        Cyw43DpcAction::FlowAck => {
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::FlowRead,
                Cyw43DpcIoKind::BackplaneRead32,
                CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                0,
            );
            false
        }
        Cyw43DpcAction::FlowRead => {
            let sampled = cyw43_dpc_w1c_status(value);
            state.flowcontrol_all = sampled & (I_HMB_FC_STATE | I_HMB_FC_CHANGE) != 0;
            state.pending_intstatus |= cyw43_dpc_latched_causes(sampled);
            cyw43_dpc_start_hostmail_or_rx(state, cursor);
            false
        }
        Cyw43DpcAction::HostmailRead => {
            cursor.mailbox_data = value;
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::HostmailAck,
                Cyw43DpcIoKind::BackplaneWrite32,
                CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOSBMAILBOX,
                SMB_INT_ACK,
            );
            false
        }
        Cyw43DpcAction::HostmailAck => {
            state.pending_intstatus &= !I_HMB_HOST_INT;
            if cursor.mailbox_data & HMB_DATA_FC != 0 {
                state.flowcontrol =
                    ((cursor.mailbox_data & HMB_DATA_FCDATA_MASK) >> HMB_DATA_FCDATA_SHIFT) as u8;
            }
            if cursor.mailbox_data & HMB_DATA_NAKHANDLED != 0 {
                state.rxskip = false;
                state.rx_retransmit_pending = false;
                state.pending_intstatus |= I_HMB_FRAME_IND;
                state.rxpending = true;
                state.rx_trace_flags |= CYW43_RX_IDLE_TRACE_FLAG_RETRANSMIT_ACKED;
            }
            cyw43_dpc_start_rframe_or_post(state, cursor);
            false
        }
        Cyw43DpcAction::FifoWindow => {
            if cursor.actual_frame_len == 0 {
                let frame = DriverFrameDescriptor {
                    offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
                    len: CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
                    flags: 0,
                };
                cyw43_dpc_prepare_function2_read(cursor, Cyw43DpcAction::Firstread, frame);
            } else {
                let frame = DriverFrameDescriptor {
                    offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
                    len: cursor.actual_frame_len,
                    flags: 0,
                };
                cyw43_dpc_prepare_function2_read(cursor, Cyw43DpcAction::Remainder, frame);
            }
            false
        }
        Cyw43DpcAction::Firstread => {
            cyw43_rx_trace_record_firstread(
                state,
                CYW43_CONTROL_RX_FIRSTREAD_BYTES,
                cursor.io_block_size,
                cursor.io_block_count,
            );
            let Some(header) = cyw43_rx_sdpcm_header_prefix_at(
                CYW43_RUNTIME_RX_BUFFER_OFFSET,
                CYW43_CONTROL_RX_FIRSTREAD_BYTES,
                CYW43_RUNTIME_RX_BUFFER_BYTES,
            ) else {
                if cyw43_dpc_invalid_firstread_route(cyw43_sdpcm_firstread_prefix_empty(
                    CYW43_RUNTIME_RX_BUFFER_OFFSET,
                )) == Cyw43DpcInvalidFirstreadRoute::Quiescent
                {
                    // Linux treats an all-zero confirming first-read as source
                    // quiescence. It is not malformed framing and must not
                    // trigger RF_TERM/NAK recovery after every valid packet.
                    state.rx_service_quiescent = true;
                    state.pending_intstatus &= !I_HMB_FRAME_IND;
                    state.rxpending = false;
                    cyw43_dpc_prepare_backplane_io(
                        state,
                        cursor,
                        Cyw43DpcAction::PostStatus,
                        Cyw43DpcIoKind::BackplaneRead32,
                        CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                        0,
                    );
                    return false;
                }
                cyw43_dpc_start_rejected_firstread_recovery(cursor);
                return false;
            };
            if header.packet_len > CYW43_CONTROL_RX_FIRSTREAD_CAPACITY {
                cyw43_dpc_start_rejected_firstread_recovery(cursor);
                return false;
            }
            cursor.actual_frame_len = header.packet_len as u16;
            if let Some(remainder_len) = cyw43_control_rx_remainder_request_len(
                CYW43_CONTROL_RX_FIRSTREAD_BYTES,
                header.packet_len,
            ) {
                let frame = DriverFrameDescriptor {
                    offset: (CYW43_RUNTIME_RX_BUFFER_OFFSET + CYW43_CONTROL_RX_FIRSTREAD_BYTES)
                        as u32,
                    len: remainder_len as u16,
                    flags: 0,
                };
                cyw43_dpc_prepare_function2_read(cursor, Cyw43DpcAction::Remainder, frame);
                false
            } else {
                !cyw43_dpc_complete_frame(state, cursor)
            }
        }
        Cyw43DpcAction::Remainder => !cyw43_dpc_complete_frame(state, cursor),
        Cyw43DpcAction::AbortFunction2 => {
            cyw43_dpc_prepare_cmd52_write(
                cursor,
                Cyw43DpcAction::TerminateReadFrame,
                1,
                SBSDIO_FUNC1_FRAMECTRL,
                SFC_RF_TERM,
            );
            false
        }
        Cyw43DpcAction::TerminateReadFrame => {
            cursor.recovery_drain_polls = 0;
            cursor.recovery_deadline = runtime_deadline_from_legacy_spins(
                CYW43_RX_SOURCE_RECOVERY_DRAIN_POLLS
                    .saturating_mul(CYW43_RX_SOURCE_RECOVERY_SETTLE_SPINS),
            );
            cyw43_dpc_prepare_cmd52_read(
                cursor,
                Cyw43DpcAction::RecoveryRframeLow,
                SBSDIO_FUNC1_RFRAMEBCLO,
            );
            false
        }
        Cyw43DpcAction::RecoveryRframeLow => {
            cursor.rframe_low = value as u8;
            cyw43_dpc_prepare_cmd52_read(
                cursor,
                Cyw43DpcAction::RecoveryRframeHigh,
                SBSDIO_FUNC1_RFRAMEBCHI,
            );
            false
        }
        Cyw43DpcAction::RecoveryRframeHigh => {
            let frame_count = u16::from(cursor.rframe_low) | ((value as u16) << 8);
            cursor.recovery_drain_polls = cursor.recovery_drain_polls.saturating_add(1);
            let deadline_expired =
                frame_count != 0 && runtime_deadline_expired(&mut cursor.recovery_deadline);
            match cyw43_dpc_recovery_drain_route(
                frame_count,
                cursor.recovery_drain_polls,
                deadline_expired,
            ) {
                Cyw43DpcRecoveryDrainRoute::PostNak => {
                    cyw43_dpc_prepare_backplane_io(
                        state,
                        cursor,
                        Cyw43DpcAction::RetransmitNak,
                        Cyw43DpcIoKind::BackplaneWrite32,
                        CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOSBMAILBOX,
                        SMB_NAK,
                    );
                }
                Cyw43DpcRecoveryDrainRoute::Retry => {
                    cursor.action = Cyw43DpcAction::RecoverySettle;
                    cursor.io_kind = Cyw43DpcIoKind::None;
                    cursor.io_phase = Cyw43DpcIoPhase::Idle;
                    cursor.recovery_settle_start_ticks = runtime_timer_counter_ticks();
                    cursor.recovery_settle_cycles =
                        runtime_legacy_spins_to_cycles(CYW43_RX_SOURCE_RECOVERY_SETTLE_SPINS);
                    cursor.recovery_settle_fallback_turns = 1;
                }
                Cyw43DpcRecoveryDrainRoute::Quarantine => {
                    state.recovery_required = true;
                }
            }
            false
        }
        Cyw43DpcAction::RecoverySettle => {
            if runtime_deadline_expired(&mut cursor.recovery_deadline) {
                state.recovery_required = true;
                return false;
            }
            let ready = cyw43_dpc_recovery_settle_ready(
                cursor.recovery_settle_start_ticks,
                cursor.recovery_settle_cycles,
                runtime_timer_counter_ticks(),
                cursor.recovery_settle_fallback_turns,
            );
            if !ready {
                cursor.recovery_settle_fallback_turns =
                    cursor.recovery_settle_fallback_turns.saturating_sub(1);
                return false;
            }
            cyw43_dpc_prepare_cmd52_read(
                cursor,
                Cyw43DpcAction::RecoveryRframeLow,
                SBSDIO_FUNC1_RFRAMEBCLO,
            );
            false
        }
        Cyw43DpcAction::RetransmitNak => {
            state.rx_retransmit_pending = true;
            state.rxskip = true;
            state.pending_intstatus &= !I_HMB_FRAME_IND;
            state.rxpending = false;
            state.rx_service_quiescent = true;
            cyw43_dpc_prepare_backplane_io(
                state,
                cursor,
                Cyw43DpcAction::PostStatus,
                Cyw43DpcIoKind::BackplaneRead32,
                CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                0,
            );
            false
        }
        Cyw43DpcAction::PostStatus => {
            let sampled = cyw43_dpc_w1c_status(value);
            let captured = cyw43_dpc_latched_causes(sampled);
            cursor.captured_status = captured;
            state.flowcontrol_all = sampled & I_HMB_FC_STATE != 0;
            state.pending_intstatus |= captured;
            if !cyw43_dpc_status_requires_ack(sampled) {
                cyw43_dpc_finish_post_capture(state, cursor)
            } else {
                cyw43_dpc_prepare_backplane_io(
                    state,
                    cursor,
                    Cyw43DpcAction::PostAck,
                    Cyw43DpcIoKind::BackplaneWrite32,
                    CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS,
                    sampled,
                );
                false
            }
        }
        Cyw43DpcAction::PostAck => cyw43_dpc_finish_post_capture(state, cursor),
    }
}

#[cfg(target_os = "none")]
fn cyw43_dpc_apply_exact_completion(
    state: &mut Cyw43RuntimeState,
    cursor: &mut Cyw43DpcCursor,
    completion: DriverTaskCompletionRecord,
) -> bool {
    if completion.code == COMPLETION_FAULT {
        state.recovery_required = true;
        return false;
    }
    match cursor.io_phase {
        Cyw43DpcIoPhase::WindowLow => cursor.io_phase = Cyw43DpcIoPhase::WindowMid,
        Cyw43DpcIoPhase::WindowMid => cursor.io_phase = Cyw43DpcIoPhase::WindowHigh,
        Cyw43DpcIoPhase::WindowHigh => {
            state.backplane_window = cursor.io_addr & BACKPLANE_WINDOW_MASK;
            state.backplane_window_valid = true;
            if cursor.io_kind == Cyw43DpcIoKind::WindowOnly {
                cursor.io_phase = Cyw43DpcIoPhase::Idle;
                return cyw43_dpc_finish_action(state, cursor, 0);
            }
            cursor.io_phase = Cyw43DpcIoPhase::Transfer;
        }
        Cyw43DpcIoPhase::Transfer => {
            if cursor.io_kind == Cyw43DpcIoKind::BackplaneWrite32 && cursor.io_byte_index < 3 {
                cursor.io_byte_index = cursor.io_byte_index.saturating_add(1);
                return false;
            }
            let value = match cursor.io_kind {
                Cyw43DpcIoKind::BackplaneRead32 => {
                    read_ring_u32(CYW43_BACKPLANE_WORD_SCRATCH_OFFSET)
                }
                Cyw43DpcIoKind::Cmd52Read => {
                    u32::from(read_ring_byte(CYW43_BACKPLANE_WORD_SCRATCH_OFFSET))
                }
                Cyw43DpcIoKind::BackplaneWrite32
                | Cyw43DpcIoKind::Cmd52Write
                | Cyw43DpcIoKind::Function2Read
                | Cyw43DpcIoKind::WindowOnly
                | Cyw43DpcIoKind::None => completion.result,
            };
            cursor.io_phase = Cyw43DpcIoPhase::Idle;
            return cyw43_dpc_finish_action(state, cursor, value);
        }
        Cyw43DpcIoPhase::Idle => return cyw43_dpc_finish_action(state, cursor, 0),
    }
    false
}

#[cfg(target_os = "none")]
fn cyw43_runtime_dpc_event_peek() -> DpcRingConsumeResult {
    CYW43_RUNTIME_STATE.with_ref(|state| {
        if !state.dpc_link_ready || state.dpc_shared_epoch == 0 {
            return DpcRingConsumeResult::Empty;
        }
        let base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        dpc_event_ring_peek_at(base, state.dpc_shared_epoch)
    })
}

#[cfg(target_os = "none")]
fn cyw43_capture_foreground_dpc_watermark(command_sequence: u32) -> Cyw43ForegroundDpcWatermark {
    CYW43_RUNTIME_STATE.with_ref(|state| {
        if !state.dpc_link_ready || state.dpc_shared_epoch == 0 {
            return Cyw43ForegroundDpcWatermark::capture(command_sequence, 0, 0);
        }
        let base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let ring = dpc_event_ring_read_at(base);
        if !ring.valid() || ring.epoch != state.dpc_shared_epoch {
            return Cyw43ForegroundDpcWatermark::empty();
        }
        Cyw43ForegroundDpcWatermark::capture(command_sequence, ring.consumer, ring.producer)
    })
}

#[cfg(target_os = "none")]
fn cyw43_runtime_service_dpc_event() -> bool {
    let mut should_defer_local = false;
    let mut should_rearm_owner = false;
    let serviced = CYW43_RUNTIME_STATE.with_mut(|state| {
        if !state.dpc_link_ready || state.dpc_shared_epoch == 0 {
            return false;
        }
        let base =
            DRIVER_TASK_SDIO_BUS_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET);
        let event = match dpc_event_ring_peek_at(base, state.dpc_shared_epoch) {
            DpcRingConsumeResult::Event(event) => event,
            DpcRingConsumeResult::Empty => return true,
            DpcRingConsumeResult::BadEpoch => {
                state.dpc_epoch_errors = state.dpc_epoch_errors.saturating_add(1);
                return false;
            }
            DpcRingConsumeResult::BadSequence => {
                state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
                return false;
            }
        };
        if !cyw43_dpc_event_has_source(event.flags) {
            state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
            return false;
        }
        if cyw43_dpc_generation_quarantined(
            state.recovery_required,
            state.dpc_cursor.child.issued_unknown,
        ) {
            // Recovery and issued-unknown are terminal for this generation.
            // Retain the event and CARD_INT mask; only coordinated generation
            // recovery or a fresh runtime boot may release SDIO ownership.
            if state.dpc_cursor.child.issued_unknown {
                cyw43_mark_issued_unknown(state);
            }
            return false;
        }
        state.dpc_active_sequence = event.sequence;
        state.rxpending = true;
        match cyw43_dpc_event_frame_hint(event.flags, event.signal_status) {
            Cyw43DpcEventFrameHint::Invalid => {
                state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
                state.recovery_required = true;
                return false;
            }
            Cyw43DpcEventFrameHint::Frame(frame_len) => {
                state.sdpcm_next_frame_len = frame_len as u16;
                state.sdpcm_next_frame_from_rframe = true;
                state.pending_intstatus |= I_HMB_FRAME_IND;
            }
            Cyw43DpcEventFrameHint::None => {}
        }

        if cyw43_dpc_readiness_action(
            state.initialized,
            state.transport_ready,
            state.firmware_execution_started,
            state.firmware_released,
        ) == Cyw43DpcReadinessAction::Drain
        {
            let mut cursor = state.dpc_cursor;
            if cursor.event_sequence == 0 {
                cursor.reset();
                cursor.event_sequence = event.sequence;
                state.reset_rx_idle_trace();
                state.rx_service_active = true;
                state.rx_service_quiescent = false;
                cyw43_dpc_start_capture(state, &mut cursor);
            } else if cursor.event_sequence != event.sequence {
                state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
                return false;
            }

            if cursor.child.issued_unknown {
                state.dpc_cursor = cursor;
                cyw43_mark_issued_unknown(state);
                return false;
            }

            if cursor.child.active {
                match cyw43_dpc_child_poll_once(&mut cursor) {
                    Cyw43DpcChildPoll::Pending => {
                        state.dpc_cursor = cursor;
                        return true;
                    }
                    Cyw43DpcChildPoll::TerminalMalformed => {
                        // The owner replied, so this is not issued-unknown and
                        // must not retain child-active ownership. Quarantine the
                        // event generation without resubmitting or advancing it.
                        state.dpc_cursor = cursor;
                        state.recovery_required = true;
                        return false;
                    }
                    Cyw43DpcChildPoll::IssuedUnknown => {
                        state.dpc_cursor = cursor;
                        cyw43_mark_issued_unknown(state);
                        return false;
                    }
                    Cyw43DpcChildPoll::Exact(completion) => {
                        let terminal =
                            cyw43_dpc_apply_exact_completion(state, &mut cursor, completion);
                        if state.recovery_required {
                            state.dpc_cursor = cursor;
                            return false;
                        }
                        if !terminal {
                            state.dpc_cursor = cursor;
                            should_defer_local = true;
                            return true;
                        }
                    }
                }
            } else if cursor.io_phase == Cyw43DpcIoPhase::Idle {
                let terminal = cyw43_dpc_finish_action(state, &mut cursor, 0);
                if state.recovery_required {
                    state.dpc_cursor = cursor;
                    return false;
                }
                if !terminal {
                    state.dpc_cursor = cursor;
                    should_defer_local = true;
                    return true;
                }
            } else if cyw43_dpc_submit_current_io(&mut cursor) {
                state.dpc_cursor = cursor;
                return true;
            } else {
                state.dpc_cursor = cursor;
                state.recovery_required = true;
                return false;
            }

            state.dpc_cursor = cursor;
        }

        // `rxskip` deliberately completes this event so CARD_INT can be
        // rearmed and a future real NAKHANDLED mailbox interrupt can arrive.
        if dpc_event_ring_advance_at(base, state.dpc_shared_epoch, event.sequence) {
            state.dpc_active_sequence = 0;
            state.dpc_events_consumed = state.dpc_events_consumed.saturating_add(1);
            state.dpc_cursor.reset();
            state.rx_service_active = false;
            let ring = dpc_event_ring_read_at(base);
            match dpc_consumer_wake_route(&ring, state.dpc_shared_epoch) {
                DpcConsumerWakeRoute::SelfSignal => should_defer_local = true,
                DpcConsumerWakeRoute::OwnerRearm => should_rearm_owner = true,
                DpcConsumerWakeRoute::Fault => {
                    state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
                    return false;
                }
            }
            true
        } else {
            state.dpc_sequence_errors = state.dpc_sequence_errors.saturating_add(1);
            false
        }
    });
    if should_defer_local {
        CYW43_DPC_DEFERRED.store(true, Ordering::Release);
    }
    if should_rearm_owner {
        runtime_signal_notification(DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT);
    }
    serviced
}

#[cfg(any(target_os = "none", test))]
const fn runtime_notification_service_badge(
    route: RuntimeNotificationRoute,
    badge: u32,
) -> Option<u32> {
    let service_badge = badge & !DRIVER_RUNTIME_RESERVED_ROOT_BADGE;
    match route {
        RuntimeNotificationRoute::SdioOwner
            if service_badge == DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE
                || service_badge == DRIVER_RUNTIME_SDIO_IRQ_BADGE =>
        {
            Some(service_badge)
        }
        RuntimeNotificationRoute::Cyw43Client
            if service_badge == DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE =>
        {
            Some(service_badge)
        }
        RuntimeNotificationRoute::SdioOwner
        | RuntimeNotificationRoute::Cyw43Client
        | RuntimeNotificationRoute::Unavailable => None,
    }
}

#[cfg(target_os = "none")]
fn service_runtime_persistent_source_once(route: RuntimeNotificationRoute, badge: u32) -> bool {
    match route {
        RuntimeNotificationRoute::SdioOwner => sdio_runtime_service_notification(badge),
        RuntimeNotificationRoute::Cyw43Client => {
            if cyw43_foreground_transaction_active() {
                CYW43_DPC_DEFERRED.store(true, Ordering::Release);
                return true;
            }
            let dpc_child_active =
                CYW43_RUNTIME_STATE.with_ref(|state| state.dpc_cursor.child.active);
            if cyw43_sdio_dpc_service_deferred(
                CYW43_SDIO_CHILD_ACTIVE.load(Ordering::Acquire) && !dpc_child_active,
            ) {
                CYW43_DPC_DEFERRED.store(true, Ordering::Release);
                true
            } else {
                cyw43_runtime_service_dpc_event()
            }
        }
        RuntimeNotificationRoute::Unavailable => false,
    }
}

#[cfg(target_os = "none")]
fn service_runtime_notification(badge: u32) -> bool {
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let route = runtime_notification_route(&descriptor);
    let Some(service_badge) = runtime_notification_service_badge(route, badge) else {
        // Badge zero is the unbadged bind/restart wake and the reserved high bit
        // is never authority. Neither is device work.
        return false;
    };
    service_runtime_persistent_source_once(route, service_badge)
}

fn service_cyw43_runtime(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&CYW43_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    #[cfg(target_os = "none")]
    if CYW43_RUNTIME_STATE.with_ref(|state| {
        cyw43_post_release_dpc_missing(state.firmware_released, state.dpc_link_ready)
    }) {
        // The Pi linked-runtime profile has exactly one post-release CYW43
        // service model. Never fall back to the old synchronous physical RX
        // path if the generated DPC link is absent or lost.
        return DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            command.aux0,
        );
    }
    if command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX {
        return service_cyw43_descriptor_command(command);
    }
    if command.frame.len == 0 {
        let mut progress_frame = DriverFrameDescriptor::empty();
        let mut idle_reason = None;
        let result = CYW43_RUNTIME_STATE.with_mut(|state| {
            let before = Cyw43RuntimeServiceSnapshot::from_state(state);
            let poll = cyw43_runtime_poll_queued_wire_head(state);
            match poll {
                Cyw43RxPollResult::Frame(frame) => {
                    progress_frame = frame;
                    cyw43_service_trace_record(
                        state,
                        0,
                        CYW43_SERVICE_REASON_BACKGROUND_RX,
                        u32::from(frame.len),
                        Some(frame.flags),
                    );
                    u32::from(frame.len)
                }
                Cyw43RxPollResult::Idle(reason) => {
                    idle_reason = Some(reason);
                    if state.sdpcm_credit_observations != before.sdpcm_credit_observations {
                        progress_frame = cyw43_sdpcm_credit_snapshot_frame(state);
                    }
                    let progress = cyw43_runtime_service_progress_result(before, state);
                    cyw43_service_trace_record(
                        state,
                        0,
                        CYW43_SERVICE_REASON_BACKGROUND_RX,
                        progress,
                        None,
                    );
                    progress
                }
            }
        });
        return if progress_frame.len != 0 && idle_reason.is_none() {
            CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::frame_ready_with_descriptor(
                command.sequence,
                progress_frame,
            )
        } else if result != 0 {
            CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            let mut completion = DriverTaskCompletionRecord::progress(command.sequence, result);
            completion.frame = progress_frame;
            completion
        } else {
            DriverTaskCompletionRecord::idle(command.sequence)
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let encoded = CYW43_RUNTIME_STATE.with_mut(|state| cyw43_stage_sdpcm_tx(state, command.frame));
    if encoded == 0 {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        CYW43_TX_COUNT.fetch_add(1, Ordering::AcqRel);
        CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        DriverTaskCompletionRecord::progress(command.sequence, encoded as u32)
    }
}

fn service_usb_keyboard(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&USB_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX {
        let status = USB_RUNTIME_STATE.with_mut(|state| {
            state.enumeration_retry_cooldown = 0;
            let detail =
                usb_runtime_retry_keyboard_enumeration(command.sequence, command.aux0, state)
                    .or(Some(state.init_detail));
            detail.map(|detail| (detail, usb_runtime_enumeration_result(state)))
        });
        return match status {
            Some((detail, result)) => USB_RUNTIME_STATE.with_ref(|state| {
                usb_runtime_enumeration_completion(command.sequence, detail, result, state)
            }),
            None => DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        };
    }
    if command.frame.len == 0 {
        let produced = USB_RUNTIME_STATE
            .with_mut(|state| usb_runtime_poll_keyboard(state, command.sequence, command.aux0));
        return if produced == 0 {
            if USB_RUNTIME_STATE.with_mut(usb_keyboard_endpoint_ready) {
                let (detail, result, frame) = USB_RUNTIME_STATE.with_mut(|state| {
                    let result = usb_keyboard_pending_result(state);
                    let detail = if usb_keyboard_has_first_valid_report(state) {
                        DRIVER_RUNTIME_USB_SERVICE_DETAIL_FIRST_REPORT_READY
                    } else {
                        DRIVER_RUNTIME_USB_SERVICE_DETAIL_FIRST_REPORT_PENDING
                    };
                    let frame = usb_keyboard_diagnostic_frame(state);
                    (detail, result, frame)
                });
                let mut completion = DriverTaskCompletionRecord::progress_with_detail(
                    command.sequence,
                    detail,
                    result,
                );
                completion.frame = frame;
                completion
            } else if let Some((detail, result)) =
                USB_RUNTIME_STATE.with_mut(usb_runtime_enumeration_status)
            {
                USB_RUNTIME_STATE.with_ref(|state| {
                    usb_runtime_enumeration_completion(command.sequence, detail, result, state)
                })
            } else {
                DriverTaskCompletionRecord::idle(command.sequence)
            }
        } else {
            USB_RUNTIME_STATE.with_mut(|state| {
                state.reports = state.reports.saturating_add(1);
            });
            USB_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::keyboard_input_ready(command.sequence, produced as u16)
        };
    }
    #[cfg(not(test))]
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    #[cfg(test)]
    {
        if !command.frame.in_ring_payload() || command.frame.len as usize != USB_BOOT_REPORT_BYTES {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        let report = read_frame_prefix::<USB_BOOT_REPORT_BYTES>(command.frame);
        let produced =
            USB_RUNTIME_STATE.with_mut(|state| usb_keyboard_report_bytes_to_frame(state, report));
        if produced == 0 {
            DriverTaskCompletionRecord::idle(command.sequence)
        } else {
            USB_RUNTIME_STATE.with_mut(|state| {
                state.reports = state.reports.saturating_add(1);
            });
            USB_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::keyboard_input_ready(command.sequence, produced as u16)
        }
    }
}

fn service_hdmi_text(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if command_is_engine_init_aux(command.aux0) {
        if let Some(completion) = service_engine_init(command) {
            return completion;
        }
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_BEGIN,
        command.aux0,
    );
    if !engine_initialized(&HDMI_RUNTIME_FLAGS) {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len == 0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::idle(command.sequence);
    }
    if !command.frame.in_ring_payload() {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != HOT_PATH_HDMI_TEXT {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if !RUNTIME_DESCRIPTOR.with_ref(|descriptor| descriptor.hdmi_ready()) {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    let rendered = hdmi_render_frame(command.frame);
    if rendered == 0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_DONE,
            command.aux0,
        );
        HDMI_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        DriverTaskCompletionRecord::progress(command.sequence, rendered as u32)
    }
}

#[cfg(target_os = "none")]
fn runtime_signal_notification(slot: u32) {
    // SAFETY: Generated topology admission proves that `slot` is a send-only
    // notification cap for the reciprocal CYW43/SDIO peer.
    unsafe {
        sel4_sys::seL4_Signal(slot as sel4_sys::seL4_CPtr);
    }
}

#[cfg(not(target_os = "none"))]
fn runtime_signal_notification(_slot: u32) {}

fn sdio_record_dpc_health(ack_failed: bool) {
    let (card_irq_masked, ack_pending, poisoned) = SDIO_RUNTIME_STATE.with_ref(|state| {
        (
            state.card_irq_masked,
            state.irq_ack_pending,
            state.dpc_poisoned,
        )
    });
    #[cfg(target_os = "none")]
    let _ = dpc_event_ring_set_owner_health_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
        card_irq_masked,
        ack_pending,
        poisoned,
        ack_failed,
    );
    #[cfg(not(target_os = "none"))]
    let _ = (card_irq_masked, ack_pending, poisoned, ack_failed);
}

fn sdio_record_irq_ack_result(acked: bool) {
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.irq_ack_pending = !acked;
    });
    sdio_record_dpc_health(!acked);
}

fn sdio_publish_card_interrupt_event(_host_int_status: u32, _badge: u32) -> bool {
    let (_epoch, handler_slot, peer_slot) = SDIO_RUNTIME_STATE.with_ref(|state| {
        (
            state.shared_epoch,
            state.irq_handler_slot,
            state.peer_notification_slot,
        )
    });
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.card_irq_captures = state.card_irq_captures.saturating_add(1);
    });
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();
    // `mmc-bcm2835` does not host-W1C CARD_INT. It disables CARD_INT in both
    // enable registers, acknowledges the CPU IRQ, and leaves the level source
    // retained until the function driver clears the dongle-side interrupt.

    #[cfg(target_os = "none")]
    let published = dpc_event_ring_publish_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
        _epoch,
        _host_int_status,
        _badge,
        DPC_REASON_SDIO_CARD_INTERRUPT,
        DRIVER_RUNTIME_DPC_EVENT_FLAG_CARD_INTERRUPT,
    );
    #[cfg(not(target_os = "none"))]
    let published = DpcRingPublishResult::Published(1);

    SDIO_RUNTIME_STATE.with_mut(|state| match published {
        DpcRingPublishResult::Published(_) => {
            state.dpc_events_published = state.dpc_events_published.saturating_add(1);
        }
        DpcRingPublishResult::Full => {
            state.dpc_ring_overruns = state.dpc_ring_overruns.saturating_add(1);
        }
        DpcRingPublishResult::BadEpoch => {
            state.dpc_poisoned = true;
        }
    });

    // The device-side source is masked before re-enabling the kernel IRQ cap.
    // A full ring is still acknowledged and the consumer is signalled; the
    // dongle source remains level-asserted and will be recaptured on rearm.
    let acked = runtime_irq_handler_ack(handler_slot);
    sdio_record_irq_ack_result(acked);
    if !matches!(published, DpcRingPublishResult::BadEpoch) {
        runtime_signal_notification(peer_slot);
    }
    acked && !matches!(published, DpcRingPublishResult::BadEpoch)
}

fn sdio_publish_pending_source_event(frame_len: u16) -> bool {
    let (epoch, peer_slot) =
        SDIO_RUNTIME_STATE.with_ref(|state| (state.shared_epoch, state.peer_notification_slot));
    #[cfg(not(target_os = "none"))]
    let _ = (frame_len, epoch);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.card_irq_captures = state.card_irq_captures.saturating_add(1);
    });
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();

    #[cfg(target_os = "none")]
    let published = dpc_event_ring_publish_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
        epoch,
        0,
        u32::from(frame_len),
        DPC_REASON_SDIO_SOURCE_PENDING,
        DRIVER_RUNTIME_DPC_EVENT_FLAG_SOURCE_PENDING,
    );
    #[cfg(not(target_os = "none"))]
    let published = DpcRingPublishResult::Published(1);

    SDIO_RUNTIME_STATE.with_mut(|state| match published {
        DpcRingPublishResult::Published(_) => {
            state.dpc_events_published = state.dpc_events_published.saturating_add(1);
        }
        DpcRingPublishResult::Full => {
            state.dpc_ring_overruns = state.dpc_ring_overruns.saturating_add(1);
        }
        DpcRingPublishResult::BadEpoch => {
            state.dpc_poisoned = true;
        }
    });
    if !matches!(published, DpcRingPublishResult::BadEpoch) {
        runtime_signal_notification(peer_slot);
    }
    !matches!(published, DpcRingPublishResult::BadEpoch)
}

fn sdio_sample_card_rframe_len() -> Option<u16> {
    let lo = sdio_execute_transfer(
        SDIO_CMD52,
        sdio_cmd52_arg(false, 1, SBSDIO_FUNC1_RFRAMEBCLO, 0),
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DriverFrameDescriptor::empty(),
        1,
        0,
    )? as u8;
    let hi = sdio_execute_transfer(
        SDIO_CMD52,
        sdio_cmd52_arg(false, 1, SBSDIO_FUNC1_RFRAMEBCHI, 0),
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DriverFrameDescriptor::empty(),
        1,
        0,
    )? as u8;
    Some(u16::from(lo) | (u16::from(hi) << 8))
}

fn sdio_runtime_service_notification(badge: u32) -> bool {
    if !sdio_notification_dpc_ready() {
        return false;
    }
    let (ack_pending, poisoned, handler_slot) = SDIO_RUNTIME_STATE.with_ref(|state| {
        (
            state.irq_ack_pending,
            state.dpc_poisoned,
            state.irq_handler_slot,
        )
    });
    if poisoned {
        sdio_record_dpc_health(false);
        return false;
    }
    if ack_pending {
        let acked = runtime_irq_handler_ack(handler_slot);
        sdio_record_irq_ack_result(acked);
        if !acked {
            return false;
        }
    }
    if !SDIO_RUNTIME_STATE.with_ref(|state| state.dpc_activation_allowed) {
        // Initial attach, recovery reload, ordinary child doorbells, and idle
        // notification polls cannot authorize CARD_INT service. Only the exact
        // generation-bound DPC_ACTIVATE owner command opens this lifetime.
        SDIO_RUNTIME_STATE.with_mut(|state| state.card_irq_masked = true);
        sdio_program_interrupt_policy();
        sdio_record_dpc_health(false);
        return true;
    }

    #[cfg(target_os = "none")]
    let ring = dpc_event_ring_read_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
    );
    #[cfg(not(target_os = "none"))]
    let ring =
        DriverRuntimeDpcEventRing::empty(SDIO_RUNTIME_STATE.with_ref(|state| state.shared_epoch));
    let epoch = SDIO_RUNTIME_STATE.with_ref(|state| state.shared_epoch);
    match sdio_dpc_capture_disposition(&ring, epoch) {
        SdioDpcCaptureDisposition::HoldPending => {
            // Linux keeps the level source masked until the current DPC has
            // consumed the retained event. Runtime idle polls and coalesced
            // child doorbells must not publish the same CARD_INT again.
            SDIO_RUNTIME_STATE.with_mut(|state| state.card_irq_masked = true);
            sdio_program_interrupt_policy();
            sdio_record_dpc_health(false);
            return true;
        }
        SdioDpcCaptureDisposition::InspectSource => {}
        SdioDpcCaptureDisposition::Fault => {
            SDIO_RUNTIME_STATE.with_mut(|state| state.dpc_poisoned = true);
            sdio_record_dpc_health(false);
            return false;
        }
    }

    if SDIO_RUNTIME_STATE.with_ref(|state| state.card_irq_masked) {
        // The consumer has advanced the retained event and signalled the
        // owner after clearing the dongle-side source. Match Linux's
        // `ack_sdio_irq`: re-enable CARD_INT in both host registers without
        // reading or W1C-clearing the still-level host status first. If the
        // function source remains asserted, the controller will deliver a
        // fresh IRQ after this rearm.
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.card_irq_masked = false;
            state.card_irq_rearms = state.card_irq_rearms.saturating_add(1);
        });
        sdio_publish_unmasked_rearm();
        return true;
    }

    let host_int_status = sdio_read32(SDHCI_INT_STATUS);
    if host_int_status & SDHCI_INT_CARD_INT != 0 {
        return sdio_publish_card_interrupt_event(host_int_status, badge);
    }
    let (irq_badge, handler_slot) =
        SDIO_RUNTIME_STATE.with_ref(|state| (state.irq_badge, state.irq_handler_slot));
    if badge == irq_badge && irq_badge != 0 {
        SDIO_RUNTIME_STATE.with_mut(|state| state.card_irq_masked = true);
        sdio_program_interrupt_policy();
        sdio_record_dpc_health(false);
        let acked = runtime_irq_handler_ack(handler_slot);
        sdio_record_irq_ack_result(acked);
        if !acked {
            return false;
        }
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.card_irq_masked = false;
            state.card_irq_rearms = state.card_irq_rearms.saturating_add(1);
        });
        sdio_publish_unmasked_rearm();
    }

    true
}

fn service_sdio_host(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&SDIO_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len != 0 && !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if command.frame.len as usize == core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() {
        return service_sdio_descriptor_command(command);
    }
    let command_index = (command.aux0 >> 16) & 0x3f;
    let flags = (command.aux0 & 0xffff) as u16;
    let data_len = command.frame.len as u32;
    if command_index > 63 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if data_len != 0 && flags & DRIVER_RUNTIME_SDIO_FLAG_DATA == 0 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0 && data_len == 0 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if sdio_response_flag_count(flags) != 1 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let Some(response0) =
        sdio_execute_command(command_index as u16, command.aux1, flags, command.frame)
    else {
        let result = sdio_last_transfer_failure();
        let transfer_mode = sdio_transfer_mode_from_flags(
            flags,
            if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
                1
            } else {
                0
            },
        );
        let frame = sdio_write_fault_telemetry_frame(
            command_index as u16,
            command.aux1,
            flags,
            command.frame.len,
            command.frame.len.max(1),
            if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
                1
            } else {
                0
            },
            transfer_mode,
            result,
            command.frame,
        );
        sdio_recover_command_path();
        return DriverTaskCompletionRecord::fault_with_result_and_frame(
            command.sequence,
            FAULT_SDIO_COMMAND_UNAVAILABLE,
            result,
            frame,
        );
    };
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.commands = state.commands.saturating_add(1);
        state.last_response = response0;
    });
    if data_len != 0 && flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0 {
        DriverTaskCompletionRecord::frame_ready(command.sequence, command.frame.len)
    } else if data_len != 0 {
        DriverTaskCompletionRecord::progress(command.sequence, data_len)
    } else {
        DriverTaskCompletionRecord::progress(command.sequence, response0)
    }
}

trait SdioDescriptorOwner {
    fn apply_host_config(&mut self, target_hz: u32, flags: u16) -> bool;

    fn execute_transfer_until(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        frame: DriverFrameDescriptor,
        block_size: u16,
        block_count: u16,
        owner_timeout_us: u32,
        owner_deadline: &mut RuntimeDeadline,
    ) -> Option<u32>;

    fn contain_failure(&mut self, owner_timeout_us: u32) -> bool;

    fn path_quiescent(&mut self) -> bool;

    fn present_state(&mut self) -> u32;

    fn poison_path(&mut self);

    fn write_fault_telemetry_frame(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        len: u16,
        block_size: u16,
        block_count: u16,
        transfer_mode: u16,
        failure_result: u32,
        payload_frame: DriverFrameDescriptor,
    ) -> DriverFrameDescriptor;
}

struct RuntimeSdioDescriptorOwner;

impl SdioDescriptorOwner for RuntimeSdioDescriptorOwner {
    fn apply_host_config(&mut self, target_hz: u32, flags: u16) -> bool {
        sdio_apply_host_config(target_hz, flags)
    }

    fn execute_transfer_until(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        frame: DriverFrameDescriptor,
        block_size: u16,
        block_count: u16,
        owner_timeout_us: u32,
        owner_deadline: &mut RuntimeDeadline,
    ) -> Option<u32> {
        sdio_execute_descriptor_transfer_until(
            cmd,
            arg,
            flags,
            frame,
            block_size,
            block_count,
            owner_timeout_us,
            owner_deadline,
        )
    }

    fn contain_failure(&mut self, owner_timeout_us: u32) -> bool {
        sdio_contain_descriptor_failure(owner_timeout_us)
    }

    fn path_quiescent(&mut self) -> bool {
        sdio_owner_path_quiescent()
    }

    fn present_state(&mut self) -> u32 {
        sdio_read32(SDHCI_PRESENT_STATE)
    }

    fn poison_path(&mut self) {
        sdio_poison_owner_path();
    }

    fn write_fault_telemetry_frame(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        len: u16,
        block_size: u16,
        block_count: u16,
        transfer_mode: u16,
        failure_result: u32,
        payload_frame: DriverFrameDescriptor,
    ) -> DriverFrameDescriptor {
        sdio_write_fault_telemetry_frame(
            cmd,
            arg,
            flags,
            len,
            block_size,
            block_count,
            transfer_mode,
            failure_result,
            payload_frame,
        )
    }
}

#[cfg(test)]
struct InjectedSdioDescriptorOwner<'a, I: SdioTransferIo> {
    io: &'a mut I,
}

#[cfg(test)]
impl<I: SdioTransferIo> SdioDescriptorOwner for InjectedSdioDescriptorOwner<'_, I> {
    fn apply_host_config(&mut self, target_hz: u32, flags: u16) -> bool {
        sdio_apply_host_config_with(self.io, target_hz, flags)
    }

    fn execute_transfer_until(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        frame: DriverFrameDescriptor,
        block_size: u16,
        block_count: u16,
        _owner_timeout_us: u32,
        owner_deadline: &mut RuntimeDeadline,
    ) -> Option<u32> {
        sdio_execute_transfer_until_with(
            self.io,
            cmd,
            arg,
            flags,
            frame,
            block_size,
            block_count,
            owner_deadline,
        )
    }

    fn contain_failure(&mut self, owner_timeout_us: u32) -> bool {
        sdio_contain_descriptor_failure_with(self.io, owner_timeout_us)
    }

    fn path_quiescent(&mut self) -> bool {
        sdio_owner_path_quiescent_with(self.io)
    }

    fn present_state(&mut self) -> u32 {
        self.io.read32(SDHCI_PRESENT_STATE)
    }

    fn poison_path(&mut self) {
        sdio_poison_owner_path_with(self.io);
    }

    fn write_fault_telemetry_frame(
        &mut self,
        cmd: u16,
        arg: u32,
        flags: u16,
        len: u16,
        block_size: u16,
        block_count: u16,
        transfer_mode: u16,
        failure_result: u32,
        payload_frame: DriverFrameDescriptor,
    ) -> DriverFrameDescriptor {
        sdio_write_fault_telemetry_frame_with(
            self.io,
            cmd,
            arg,
            flags,
            len,
            block_size,
            block_count,
            transfer_mode,
            failure_result,
            payload_frame,
        )
    }
}

fn service_sdio_descriptor_command(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    let mut owner = RuntimeSdioDescriptorOwner;
    service_sdio_descriptor_command_with_owner(command, &mut owner)
}

#[cfg(test)]
fn service_sdio_descriptor_command_with_io<I: SdioTransferIo>(
    command: DriverTaskCommandRecord,
    io: &mut I,
) -> DriverTaskCompletionRecord {
    let mut owner = InjectedSdioDescriptorOwner { io };
    service_sdio_descriptor_command_with_owner(command, &mut owner)
}

fn service_sdio_descriptor_command_with_owner<O: SdioDescriptorOwner>(
    command: DriverTaskCommandRecord,
    owner: &mut O,
) -> DriverTaskCompletionRecord {
    let Some(desc) = read_sdio_command_descriptor(command.frame) else {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    };
    if !desc.valid() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_GENERATION_RESET {
        #[cfg(test)]
        return service_sdio_generation_reset(command.sequence, desc.addr);
        #[cfg(not(test))]
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_GENERATION_COMMIT {
        return service_sdio_generation_commit(command.sequence, desc.addr);
    }
    // A failed containment means the host command/data path is no longer a
    // trustworthy bus owner. Only an explicit generation reset may re-admit
    // service; accepting another descriptor here could compound a stale
    // DATA_INHIBIT into an unrelated CYW43 protocol failure.
    if SDIO_RUNTIME_STATE.with_ref(|state| state.dpc_poisoned)
        && !sdio_generation_reprobe_op_allowed(desc)
    {
        return DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
            sdio_last_transfer_failure(),
        );
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_DPC_ACTIVATE {
        return service_sdio_dpc_activate(command.sequence, desc.addr);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_HOST_CONFIG {
        let owner_timeout_us = sdio_owner_descriptor_timeout_us(desc.timeout_us);
        if owner.apply_host_config(desc.addr, desc.flags) && owner.path_quiescent() {
            return DriverTaskCompletionRecord::progress(command.sequence, 1);
        }
        if !owner.contain_failure(owner_timeout_us) {
            owner.poison_path();
        }
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_SDIO_HOST_CONFIG_FAILED);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND {
        let cmd = desc.len;
        let flags = sdio_descriptor_response_flags(desc.response_kind);
        let frame = DriverFrameDescriptor::empty();
        sdio_clear_last_transfer_failure();
        let owner_timeout_us = sdio_owner_descriptor_timeout_us(desc.timeout_us);
        let mut owner_deadline = sdio_fresh_owner_deadline(owner_timeout_us);
        let Some(response0) = owner.execute_transfer_until(
            cmd,
            desc.addr,
            flags,
            frame,
            1,
            0,
            owner_timeout_us,
            &mut owner_deadline,
        ) else {
            let result = sdio_last_transfer_failure();
            let telemetry =
                owner.write_fault_telemetry_frame(cmd, desc.addr, flags, 0, 1, 0, 0, result, frame);
            let contained = owner.contain_failure(owner_timeout_us);
            if !contained {
                owner.poison_path();
            }
            sdio_record_transfer_failure_result(result);
            return DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                FAULT_SDIO_COMMAND_UNAVAILABLE,
                result,
                telemetry,
            );
        };
        if !owner.path_quiescent() {
            let result = sdio_transfer_failure_result(
                SDIO_TRANSFER_FAILURE_STAGE_POST_ISSUE_QUIESCE,
                owner.present_state(),
            );
            let telemetry =
                owner.write_fault_telemetry_frame(cmd, desc.addr, flags, 0, 1, 0, 0, result, frame);
            let contained = owner.contain_failure(owner_timeout_us);
            if !contained {
                owner.poison_path();
            }
            sdio_record_transfer_failure_result(result);
            return DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                FAULT_SDIO_COMMAND_UNAVAILABLE,
                result,
                telemetry,
            );
        }
        SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.commands = state.commands.saturating_add(1);
            state.last_response = response0;
        });
        return DriverTaskCompletionRecord::progress(command.sequence, response0);
    }
    let mut frame = DriverFrameDescriptor {
        offset: u32::from(desc.data_offset),
        len: desc.len,
        flags: 0,
    };
    if desc.block_count != 0 {
        let bytes = u32::from(desc.block_count).saturating_mul(u32::from(desc.block_size));
        if bytes > u32::from(u16::MAX) {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        frame.len = bytes as u16;
    }
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    if frame.len != 0 && !frame.in_runtime_payload(shared_payload_bytes) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let flags = sdio_descriptor_response_flags(desc.response_kind)
        | match desc.op {
            DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => {
                DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE
            }
            DRIVER_RUNTIME_SDIO_OP_CMD53_READ => DRIVER_RUNTIME_SDIO_FLAG_DATA,
            _ => 0,
        };
    let (cmd, arg) = match desc.op {
        DRIVER_RUNTIME_SDIO_OP_CMD52_READ => {
            (52, sdio_cmd52_arg(false, desc.function, desc.addr, 0))
        }
        DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE => {
            let value = if desc.len == 0 {
                0
            } else {
                read_runtime_payload_byte(usize::from(desc.data_offset))
            };
            (52, sdio_cmd52_arg(true, desc.function, desc.addr, value))
        }
        DRIVER_RUNTIME_SDIO_OP_CMD53_READ | DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => (
            53,
            sdio_cmd53_arg(
                desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
                desc.function,
                desc.addr,
                desc.flags & DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT != 0,
                desc.block_count,
                desc.len,
            ),
        ),
        DRIVER_RUNTIME_SDIO_OP_POLL_IRQ => (52, sdio_cmd52_arg(false, 0, 0x05, 0)),
        _ => return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    };
    let block_size = if desc.block_count == 0 {
        frame.len.max(1)
    } else {
        desc.block_size
    };
    let block_count = sdio_descriptor_host_block_count(desc.block_count, flags);
    sdio_clear_last_transfer_failure();
    let owner_timeout_us = sdio_owner_descriptor_timeout_us(desc.timeout_us);
    let mut owner_deadline = sdio_fresh_owner_deadline(owner_timeout_us);
    let mut response0 = owner.execute_transfer_until(
        cmd,
        arg,
        flags,
        frame,
        block_size,
        block_count,
        owner_timeout_us,
        &mut owner_deadline,
    );
    let mut result = 0;
    let mut contained = true;
    if response0.is_none() {
        result = sdio_last_transfer_failure();
        // Descriptor service owns containment. The transfer deadline is
        // normally exhausted when a failure is reported, so recovery must
        // receive a fresh bounded deadline rather than reusing that expired
        // budget. This is the linked-runtime equivalent of Linux resetting
        // the command/data path before returning the bus to its caller.
        contained = owner.contain_failure(owner_timeout_us);
        if contained && sdio_descriptor_retry_after_containment(desc, cmd, flags, result) {
            sdio_clear_last_transfer_failure();
            let mut retry_deadline = sdio_fresh_owner_deadline(owner_timeout_us);
            response0 = owner.execute_transfer_until(
                cmd,
                arg,
                flags,
                frame,
                block_size,
                block_count,
                owner_timeout_us,
                &mut retry_deadline,
            );
            if response0.is_none() {
                let retry_result = sdio_last_transfer_failure();
                if retry_result != 0 {
                    result = retry_result;
                }
                contained = owner.contain_failure(owner_timeout_us);
            }
        }
    }
    if response0.is_some() && !owner.path_quiescent() {
        result = sdio_transfer_failure_result(
            SDIO_TRANSFER_FAILURE_STAGE_POST_ISSUE_QUIESCE,
            owner.present_state(),
        );
        sdio_record_transfer_failure_result(result);
        response0 = None;
        contained = owner.contain_failure(owner_timeout_us);
    }
    let Some(response0) = response0 else {
        if result == 0 {
            result = sdio_last_transfer_failure();
        }
        if !contained {
            owner.poison_path();
        }
        sdio_record_transfer_failure_result(result);
        let transfer_mode = sdio_transfer_mode_from_flags(flags, block_count);
        let telemetry = owner.write_fault_telemetry_frame(
            cmd,
            arg,
            flags,
            frame.len,
            block_size,
            block_count,
            transfer_mode,
            result,
            frame,
        );
        return DriverTaskCompletionRecord::fault_with_result_and_frame(
            command.sequence,
            FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
            result,
            telemetry,
        );
    };
    sdio_clear_last_transfer_failure();
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.commands = state.commands.saturating_add(1);
        state.last_response = response0;
    });
    match desc.op {
        DRIVER_RUNTIME_SDIO_OP_CMD52_READ | DRIVER_RUNTIME_SDIO_OP_POLL_IRQ => {
            write_runtime_payload_byte(usize::from(desc.data_offset), (response0 & 0xff) as u8);
            DriverTaskCompletionRecord::frame_ready_at(
                command.sequence,
                u32::from(desc.data_offset),
                1,
            )
        }
        DRIVER_RUNTIME_SDIO_OP_CMD53_READ => {
            DriverTaskCompletionRecord::frame_ready_at(command.sequence, frame.offset, frame.len)
        }
        DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE | DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => {
            DriverTaskCompletionRecord::progress(command.sequence, u32::from(frame.len))
        }
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

fn sdio_generation_reset_ring_admitted(current: u32, requested: u32) -> bool {
    if !dpc_generation_reset_request_valid(current, requested) {
        return false;
    }
    #[cfg(target_os = "none")]
    let mut ring = dpc_event_ring_read_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
    );
    #[cfg(not(target_os = "none"))]
    let mut ring = DriverRuntimeDpcEventRing::empty(current);
    dpc_event_ring_reset_generation(&mut ring, current, requested)
}

fn sdio_generation_reprobe_op_allowed(desc: DriverRuntimeSdioCommandDescriptor) -> bool {
    if !SDIO_RUNTIME_STATE.with_ref(|state| {
        state.pending_epoch != 0
            && state.card_irq_masked
            && !state.dpc_activation_allowed
            && state.dpc_poisoned
    }) {
        return false;
    }
    match desc.op {
        DRIVER_RUNTIME_SDIO_OP_HOST_CONFIG => sdio_generation_reprobe_host_config_allowed(desc),
        DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND => sdio_generation_reprobe_card_command_allowed(desc),
        DRIVER_RUNTIME_SDIO_OP_CMD52_READ | DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE => {
            sdio_generation_reprobe_cmd52_allowed(desc)
        }
        DRIVER_RUNTIME_SDIO_OP_CMD53_READ => {
            desc.function == 1
                && desc.addr == cyw43_backplane_function_addr(CYW43_CHIPCOMMON_BASE)
                && desc.len == 4
                && desc.block_size == 0
                && desc.block_count == 0
                && desc.flags == DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT
        }
        _ => false,
    }
}

const fn sdio_generation_reprobe_host_config_allowed(
    desc: DriverRuntimeSdioCommandDescriptor,
) -> bool {
    let width = DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT;
    let high_speed = DriverRuntimeSdioCommandDescriptor::FLAG_HOST_HIGH_SPEED;
    (desc.addr == SDHCI_STARTUP_CLOCK_HZ && desc.flags == 0)
        || (desc.addr == CYW43_SDIO_FAST_CLOCK_HZ && desc.flags == width | high_speed)
        || (desc.addr == CYW43_SDIO_DEFAULT_SPEED_CLOCK_HZ && desc.flags == width)
}

fn sdio_generation_reprobe_card_command_allowed(desc: DriverRuntimeSdioCommandDescriptor) -> bool {
    match desc.len {
        0 => desc.addr == 0 && desc.response_kind == DRIVER_RUNTIME_SDIO_RESP_NONE,
        SDIO_CMD5 => desc.response_kind == DRIVER_RUNTIME_SDIO_RESP_OCR,
        SDIO_CMD3 => desc.addr == 0 && desc.response_kind == DRIVER_RUNTIME_SDIO_RESP_SHORT,
        SDIO_CMD7 => desc.addr != 0 && desc.response_kind == DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY,
        _ => false,
    }
}

fn sdio_generation_reprobe_cmd52_allowed(desc: DriverRuntimeSdioCommandDescriptor) -> bool {
    let write = desc.op == DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE;
    let value = write.then(|| read_runtime_payload_byte(usize::from(desc.data_offset)));
    let f1_base = SDIO_CCCR_FBR_BASE;
    let f2_base = SDIO_CCCR_FBR_BASE.saturating_mul(2);
    if desc.function == 0 {
        return match desc.addr {
            SDIO_CCCR_IOEX => !write || value == Some(SDIO_FUNC_ENABLE_1),
            SDIO_CCCR_IORX => !write,
            SDIO_CCCR_IF => !write || value == Some(SDIO_BUS_WIDTH_4BIT),
            SDIO_CCCR_SPEED => !write || value == Some(SDIO_CCCR_SPEED_SHS | SDIO_CCCR_SPEED_EHS),
            addr if addr == f1_base + SDIO_FBR_BLKSIZE => {
                !write || value == Some((SDIO_FUNCTION1_BLOCK_SIZE & 0xff) as u8)
            }
            addr if addr == f1_base + SDIO_FBR_BLKSIZE + 1 => {
                !write || value == Some((SDIO_FUNCTION1_BLOCK_SIZE >> 8) as u8)
            }
            addr if addr == f2_base + SDIO_FBR_BLKSIZE => {
                !write || value == Some((SDIO_FUNCTION2_BLOCK_SIZE & 0xff) as u8)
            }
            addr if addr == f2_base + SDIO_FBR_BLKSIZE + 1 => {
                !write || value == Some((SDIO_FUNCTION2_BLOCK_SIZE >> 8) as u8)
            }
            _ => false,
        };
    }
    if desc.function != 1 {
        return false;
    }
    let (window_low, window_mid, window_high) =
        cyw43_backplane_window_register_bytes(CYW43_CHIPCOMMON_BASE);
    match desc.addr {
        SBSDIO_FUNC1_CHIPCLKCSR => {
            !write
                || matches!(
                    value,
                    Some(v)
                        if v == (SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_ALP_AVAIL_REQ)
                            || v == (SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_FORCE_ALP)
                )
        }
        // Linux disables the CYW43's extra SDIO pull-ups during buscore attach.
        // Admit only that exact write while a poisoned generation is being
        // reprobed; no other value or access to this register gains authority.
        SBSDIO_FUNC1_SDIOPULLUP => write && value == Some(0),
        SBSDIO_FUNC1_SBADDRLOW => !write || value == Some(window_low),
        SBSDIO_FUNC1_SBADDRMID => !write || value == Some(window_mid),
        SBSDIO_FUNC1_SBADDRHIGH => !write || value == Some(window_high),
        _ => false,
    }
}

fn sdio_generation_reset_quiesce() {
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.dpc_activation_allowed = false;
        state.dpc_poisoned = true;
    });
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();
    // Host masking and the poisoned generation prevent further DPC service.
    // Do not issue card commands here: the old firmware may be wedged, and a
    // failed CCCR transaction must never prevent the authoritative WL_ON
    // power sequence from stopping that generation.
}

fn sdio_generation_reset_ack_while_masked() -> bool {
    let handler_slot = SDIO_RUNTIME_STATE.with_ref(|state| state.irq_handler_slot);
    let acked = runtime_irq_handler_ack(handler_slot);
    sdio_record_irq_ack_result(acked);
    acked
}

fn sdio_generation_reset_commit(requested: u32) -> bool {
    let Some(current) = SDIO_RUNTIME_STATE.with_ref(|state| {
        (state.pending_epoch == requested
            && requested != 0
            && state.card_irq_masked
            && !state.dpc_activation_allowed
            && state.dpc_poisoned)
            .then_some(state.shared_epoch)
    }) else {
        return false;
    };
    #[cfg(target_os = "none")]
    if !dpc_event_ring_reset_generation_at(
        DRIVER_TASK_RING_VADDR + usize::from(DRIVER_RUNTIME_DPC_EVENT_RING_OFFSET),
        current,
        requested,
    ) {
        return false;
    }
    #[cfg(not(target_os = "none"))]
    if !dpc_generation_reset_request_valid(current, requested) {
        return false;
    }
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.shared_epoch = requested;
        state.pending_epoch = 0;
        state.card_irq_masked = true;
        state.dpc_activation_allowed = false;
        state.irq_ack_pending = false;
        state.dpc_poisoned = false;
        state.commands = state.commands.saturating_add(1);
        state.last_response = requested;
    });
    // Keep CARD_INT masked across the entire firmware reload. The old dongle
    // execution must not publish into the new epoch, and the new execution is
    // not DPC-serviceable until RELEASE completes. CYW43 explicitly signals
    // the SDIO owner after successful attach, which then samples any latched
    // source and rearms in the normal empty-ring order.
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    true
}

fn sdio_engine_init_command_candidate(command: DriverTaskCommandRecord) -> bool {
    command.sequence != 0
        && command.opcode == OPCODE_SERVICE
        && command.arg0 == HOT_PATH_SDIO_HOST
        && command.arg1 == ROLE_SDIO
        && command_is_engine_init_aux(command.aux0)
        && command.frame.len == 0
}

fn sdio_generation_reset_command_candidate(
    command: DriverTaskCommandRecord,
) -> Option<DriverRuntimeSdioCommandDescriptor> {
    if command.sequence == 0
        || command.opcode != OPCODE_SERVICE
        || command.arg0 != HOT_PATH_SDIO_HOST
        || command.arg1 != ROLE_SDIO
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return None;
    }
    let desc = read_sdio_command_descriptor(command.frame)?;
    (desc.valid() && desc.op == DRIVER_RUNTIME_SDIO_OP_GENERATION_RESET).then_some(desc)
}

fn begin_sdio_engine_init(command: DriverTaskCommandRecord) -> Result<(), u16> {
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_COMMAND_VALIDATED,
        command.aux0,
    );
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != HOT_PATH_SDIO_HOST {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_MISMATCH,
            command.aux0,
        );
        return Err(FAULT_DEVICE_UNAVAILABLE);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
        command.aux0,
    );
    publish_service_dispatch_progress(command);
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DISPATCH,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_LOADED,
        command.aux0,
    );
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        if descriptor.hot_path != HOT_PATH_SDIO_HOST {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_BEGIN,
            command.aux0,
        );
        if !descriptor_resources_ready_with_progress(
            descriptor,
            HOT_PATH_SDIO_HOST,
            command.sequence,
            command.aux0,
        ) {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCES_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_BEGIN,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_SDIO_ENGINE_INIT_BRANCH,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_BEGIN,
            command.aux0,
        );
        reset_sdio_register_shadows();
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_DONE,
            command.aux0,
        );
        sdio_runtime_prepare(command.sequence, command.aux0, descriptor)
    })?;
    SDIO_RUNTIME_FLAGS.fetch_and(
        !(ENGINE_STATE_INITIALIZED | ENGINE_STATE_HW_READY),
        Ordering::AcqRel,
    );
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.pwrseq = SdioPwrseqCursor::begin(
            SdioPwrseqPurpose::EngineInit,
            command.sequence,
            command.aux0,
        );
    });
    Ok(())
}

fn begin_sdio_generation_reset(sequence: u32, requested: u32) -> Result<(), u16> {
    let current = SDIO_RUNTIME_STATE.with_ref(|state| state.shared_epoch);
    if !SDIO_RUNTIME_STATE.with_ref(|state| state.initialized)
        || !sdio_notification_dpc_ready()
        || !sdio_generation_reset_ring_admitted(current, requested)
    {
        return Err(FAULT_REJECTED_COMMAND);
    }
    sdio_generation_reset_quiesce();
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.pending_epoch = 0;
        state.pwrseq = SdioPwrseqCursor::begin(
            SdioPwrseqPurpose::GenerationReset {
                requested_epoch: requested,
            },
            sequence,
            DRIVER_RUNTIME_NET_INIT_AUX,
        );
    });
    Ok(())
}

fn finish_sdio_engine_init(sequence: u32, aux0: u32) -> DriverTaskCompletionRecord {
    if !sdio_arm_card_interrupt_after_init() {
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.pwrseq = SdioPwrseqCursor::idle();
            state.initialized = false;
        });
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
            aux0,
        );
        return DriverTaskCompletionRecord::fault(
            sequence,
            DRIVER_RUNTIME_SDIO_INIT_DETAIL_INVALID_DESCRIPTOR,
        );
    }
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.pwrseq = SdioPwrseqCursor::idle();
        state.initialized = true;
    });
    SDIO_RUNTIME_FLAGS.fetch_or(
        ENGINE_STATE_INITIALIZED
            | ENGINE_STATE_DESCRIPTOR_READY
            | ENGINE_STATE_RESOURCE_READY
            | ENGINE_STATE_HW_READY,
        Ordering::AcqRel,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_DONE,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
        aux0,
    );
    DriverTaskCompletionRecord::progress_with_detail(
        sequence,
        DRIVER_RUNTIME_SDIO_INIT_DETAIL_READY,
        1,
    )
}

fn finish_sdio_generation_reset(sequence: u32, requested: u32) -> DriverTaskCompletionRecord {
    if !sdio_generation_reset_ack_while_masked() {
        SDIO_RUNTIME_STATE.with_mut(|state| state.pwrseq = SdioPwrseqCursor::idle());
        return DriverTaskCompletionRecord::fault_with_result(
            sequence,
            FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
            sdio_last_transfer_failure(),
        );
    }
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.pwrseq = SdioPwrseqCursor::idle();
        state.pending_epoch = requested;
        state.card_irq_masked = true;
        state.dpc_activation_allowed = false;
        state.dpc_poisoned = true;
        state.commands = state.commands.saturating_add(1);
        state.last_response = requested;
    });
    sdio_record_dpc_health(false);
    sdio_program_interrupt_policy();
    DriverTaskCompletionRecord::progress(sequence, requested)
}

fn service_sdio_pwrseq_command_turn(
    command: DriverTaskCommandRecord,
) -> Option<RuntimeCommandTurn> {
    let active = SDIO_RUNTIME_STATE.with_ref(|state| state.pwrseq);
    if !active.active() {
        if sdio_engine_init_command_candidate(command) {
            if let Err(detail) = begin_sdio_engine_init(command) {
                publish_runtime_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
                    command.aux0,
                );
                return Some(RuntimeCommandTurn::Complete(
                    DriverTaskCompletionRecord::fault(command.sequence, detail),
                ));
            }
        } else if let Some(desc) = sdio_generation_reset_command_candidate(command) {
            if let Err(detail) = begin_sdio_generation_reset(command.sequence, desc.addr) {
                return Some(RuntimeCommandTurn::Complete(
                    DriverTaskCompletionRecord::fault(command.sequence, detail),
                ));
            }
        } else {
            return None;
        }
    } else if active.sequence != command.sequence {
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
        ));
    }

    let cursor = SDIO_RUNTIME_STATE.with_ref(|state| state.pwrseq);
    let purpose = cursor.purpose;
    let aux0 = cursor.aux0;
    Some(match sdio_linux_wifi_power_cycle_turn() {
        SdioPwrseqTurn::Pending => RuntimeCommandTurn::Pending,
        SdioPwrseqTurn::Ready => RuntimeCommandTurn::Complete(match purpose {
            SdioPwrseqPurpose::EngineInit => finish_sdio_engine_init(command.sequence, aux0),
            SdioPwrseqPurpose::GenerationReset { requested_epoch } => {
                finish_sdio_generation_reset(command.sequence, requested_epoch)
            }
            SdioPwrseqPurpose::Idle => {
                DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND)
            }
        }),
        SdioPwrseqTurn::Fault { detail, result } => {
            if matches!(purpose, SdioPwrseqPurpose::EngineInit) {
                SDIO_RUNTIME_STATE.with_mut(|state| state.initialized = false);
                publish_runtime_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
                    aux0,
                );
                RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                    command.sequence,
                    detail,
                    result,
                ))
            } else {
                RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                    command.sequence,
                    FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
                    (u32::from(detail) << 16) | (result & 0xffff),
                ))
            }
        }
    })
}

#[cfg(test)]
fn service_sdio_generation_reset(sequence: u32, requested: u32) -> DriverTaskCompletionRecord {
    if let Err(detail) = begin_sdio_generation_reset(sequence, requested) {
        return DriverTaskCompletionRecord::fault(sequence, detail);
    }
    loop {
        match sdio_linux_wifi_power_cycle_turn() {
            SdioPwrseqTurn::Pending => {}
            SdioPwrseqTurn::Ready => return finish_sdio_generation_reset(sequence, requested),
            SdioPwrseqTurn::Fault { detail, result } => {
                return DriverTaskCompletionRecord::fault_with_result(
                    sequence,
                    FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
                    (u32::from(detail) << 16) | (result & 0xffff),
                );
            }
        }
    }
}

fn service_sdio_generation_commit(sequence: u32, requested: u32) -> DriverTaskCompletionRecord {
    if !sdio_notification_dpc_ready() || !sdio_generation_reset_commit(requested) {
        return DriverTaskCompletionRecord::fault(sequence, FAULT_REJECTED_COMMAND);
    }
    DriverTaskCompletionRecord::progress(sequence, requested)
}

fn service_sdio_dpc_activate(sequence: u32, requested: u32) -> DriverTaskCompletionRecord {
    let admitted = SDIO_RUNTIME_STATE.with_ref(|state| {
        state.dpc_link_ready
            && state.shared_epoch == requested
            && requested != 0
            && !state.dpc_poisoned
    });
    if !admitted || !sdio_notification_dpc_ready() {
        return DriverTaskCompletionRecord::fault(sequence, FAULT_REJECTED_COMMAND);
    }

    // Activation is the only operation that opens the post-release CARD_INT
    // lifetime. Inspect the retained ring and hardware source while still
    // masked, then either publish the latched source or perform the normal
    // empty-ring rearm before acknowledging the command.
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.dpc_activation_allowed = true;
        state.card_irq_masked = true;
    });
    sdio_program_interrupt_policy();
    sdio_record_dpc_health(false);
    let host_int_status = sdio_read32(SDHCI_INT_STATUS);
    let activation_serviced = if host_int_status & SDHCI_INT_CARD_INT != 0 {
        sdio_publish_card_interrupt_event(host_int_status, 0)
    } else {
        match sdio_sample_card_rframe_len() {
            Some(frame_len) if frame_len != 0 => sdio_publish_pending_source_event(frame_len),
            Some(_) => sdio_runtime_service_notification(0),
            None => false,
        }
    };
    if !activation_serviced {
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.dpc_activation_allowed = false;
            state.card_irq_masked = true;
        });
        sdio_program_interrupt_policy();
        sdio_record_dpc_health(false);
        return DriverTaskCompletionRecord::fault(sequence, FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED);
    }

    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.commands = state.commands.saturating_add(1);
        state.last_response = requested;
    });
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    DriverTaskCompletionRecord::progress(sequence, requested)
}

const fn sdio_descriptor_transfer_retryable(
    desc: DriverRuntimeSdioCommandDescriptor,
    cmd: u16,
    flags: u16,
) -> bool {
    if cmd != SDIO_CMD53
        || desc.op != DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE
        || flags & (DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE)
            != (DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE)
    {
        return false;
    }
    // This classifies explicitly addressed Function 1 writes only. It does
    // not by itself authorize replay: some Function 1 registers are action
    // strobes. The caller must first prove the command was not issued.
    // Function 2 is the SDPCM FIFO and is never replayable.
    desc.function == 1
}

const fn sdio_descriptor_retry_after_containment(
    desc: DriverRuntimeSdioCommandDescriptor,
    cmd: u16,
    flags: u16,
    failure_result: u32,
) -> bool {
    if sdio_transfer_failure_stage(failure_result) != SDIO_TRANSFER_FAILURE_STAGE_INHIBIT
        || cmd != SDIO_CMD53
        || desc.function != 1
    {
        return false;
    }
    // Entry inhibit is the only stage that proves SDHCI never issued the
    // command. After fresh containment, an identical Function 1 read or write
    // is therefore safe even for an action register. Every later stage is
    // issued or issued-unknown and must surface without replay.
    desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_READ
        || sdio_descriptor_transfer_retryable(desc, cmd, flags)
}

fn sdio_fresh_owner_deadline(owner_timeout_us: u32) -> RuntimeDeadline {
    runtime_deadline_from_micros_or_legacy_spins(owner_timeout_us, SDHCI_CMD_WAIT_LOOPS)
}

fn sdio_fresh_containment_deadline(owner_timeout_us: u32) -> RuntimeDeadline {
    let recovery_timeout_us =
        u32::try_from(BCM2835_SDIO_RECOVERY_TIMEOUT_MS.saturating_mul(RUNTIME_MILLIS_PER_SECOND))
            .unwrap_or(u32::MAX);
    let timeout_us = owner_timeout_us.max(recovery_timeout_us);
    let fallback_iterations = usize::try_from(timeout_us)
        .unwrap_or(usize::MAX)
        .saturating_mul(
            usize::try_from(RUNTIME_LEGACY_SPINS_PER_SECOND / RUNTIME_MICROS_PER_SECOND)
                .unwrap_or(1),
        )
        .max(BCM2835_SDIO_RECOVERY_FALLBACK_POLLS);
    runtime_deadline_from_micros_or_legacy_spins(timeout_us, fallback_iterations)
}

fn sdio_owner_path_quiescent() -> bool {
    let mut io = SdioMmioTransferIo;
    sdio_owner_path_quiescent_with(&mut io)
}

fn sdio_owner_path_quiescent_with<I: SdioTransferIo>(io: &mut I) -> bool {
    io.read32(SDHCI_PRESENT_STATE) & (SDHCI_CMD_INHIBIT | SDHCI_DATA_INHIBIT) == 0
}

fn sdio_contain_descriptor_failure(owner_timeout_us: u32) -> bool {
    let mut io = SdioMmioTransferIo;
    sdio_contain_descriptor_failure_with(&mut io, owner_timeout_us)
}

fn sdio_contain_descriptor_failure_with<I: SdioTransferIo>(
    io: &mut I,
    owner_timeout_us: u32,
) -> bool {
    let mut containment_deadline = sdio_fresh_containment_deadline(owner_timeout_us);
    sdio_recover_command_path_until_with(io, &mut containment_deadline)
        && sdio_owner_path_quiescent_with(io)
}

fn sdio_poison_owner_path() {
    let mut io = SdioMmioTransferIo;
    sdio_poison_owner_path_with(&mut io);
}

fn sdio_poison_owner_path_with<I: SdioTransferIo>(io: &mut I) {
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.card_irq_masked = true;
        state.dpc_activation_allowed = false;
        state.dpc_poisoned = true;
    });
    sdio_program_interrupt_policy_with(io);
    sdio_record_dpc_health(false);
}

fn read_sdio_command_descriptor(
    frame: DriverFrameDescriptor,
) -> Option<DriverRuntimeSdioCommandDescriptor> {
    if !frame.in_ring_payload()
        || frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return None;
    }
    let offset = frame.offset as usize;
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR + offset,
        core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>(),
    );
    driver_task_shared_load_barrier();
    Some(DriverRuntimeSdioCommandDescriptor {
        op: read_ring_u16(offset),
        function: read_ring_byte(offset + 2),
        response_kind: read_ring_byte(offset + 3),
        addr: read_ring_u32(offset + 4),
        data_offset: read_ring_u16(offset + 8),
        len: read_ring_u16(offset + 10),
        block_size: read_ring_u16(offset + 12),
        block_count: read_ring_u16(offset + 14),
        flags: read_ring_u16(offset + 16),
        reserved: read_ring_u16(offset + 18),
        timeout_us: read_ring_u32(offset + 20),
    })
}

fn read_cyw43_command_descriptor(
    frame: DriverFrameDescriptor,
) -> Option<DriverRuntimeCyw43CommandDescriptor> {
    #[cfg(target_os = "none")]
    if cyw43_foreground_transaction_executing() {
        return CYW43_FOREGROUND_TRANSACTION.with_mut(|transaction| {
            if frame != transaction.parent.frame || !transaction.parent_descriptor_valid {
                transaction.poisoned = true;
                return None;
            }
            Some(transaction.parent_descriptor)
        });
    }
    read_cyw43_command_descriptor_physical(frame)
}

fn read_cyw43_command_descriptor_physical(
    frame: DriverFrameDescriptor,
) -> Option<DriverRuntimeCyw43CommandDescriptor> {
    if !frame.in_ring_payload()
        || frame.len as usize != core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>()
    {
        return None;
    }
    let offset = frame.offset as usize;
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR + offset,
        core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>(),
    );
    driver_task_shared_load_barrier();
    Some(DriverRuntimeCyw43CommandDescriptor {
        op: read_ring_u16(offset),
        flags: read_ring_u16(offset + 2),
        target_addr: read_ring_u32(offset + 4),
        payload_offset: read_ring_u16(offset + 8),
        payload_len: read_ring_u16(offset + 10),
        total_len: read_ring_u32(offset + 12),
        arg0: read_ring_u32(offset + 16),
        arg1: read_ring_u32(offset + 20),
        reserved: read_ring_u32(offset + 24),
    })
}

#[cfg(target_os = "none")]
fn write_cyw43_command_descriptor_physical(
    frame: DriverFrameDescriptor,
    descriptor: DriverRuntimeCyw43CommandDescriptor,
) {
    if !frame.in_ring_payload()
        || frame.len as usize != core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>()
    {
        return;
    }
    let offset = frame.offset as usize;
    write_ring_u16(offset, descriptor.op);
    write_ring_u16(offset + 2, descriptor.flags);
    write_ring_u32(offset + 4, descriptor.target_addr);
    write_ring_u16(offset + 8, descriptor.payload_offset);
    write_ring_u16(offset + 10, descriptor.payload_len);
    write_ring_u32(offset + 12, descriptor.total_len);
    write_ring_u32(offset + 16, descriptor.arg0);
    write_ring_u32(offset + 20, descriptor.arg1);
    write_ring_u32(offset + 24, descriptor.reserved);
}

fn cyw43_descriptor_invalid_result(desc: DriverRuntimeCyw43CommandDescriptor) -> u32 {
    let known_op = desc.op == DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RELEASE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        || desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE;
    let known_flags = match desc.op {
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => desc.flags == 0,
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME | DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE => {
            desc.flags
                & !(DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER
                    | DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN)
                == 0
        }
        DRIVER_RUNTIME_CYW43_OP_RX_POLL => {
            desc.flags
                & !(DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD
                    | DRIVER_RUNTIME_CYW43_FLAG_RX_STEADY_TAIL_DRAIN)
                == 0
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL => {
            desc.flags & !DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD == 0
        }
        _ => desc.flags == 0,
    };
    let bulk_stream_payload = desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK;
    let carries_payload = bulk_stream_payload
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX;
    let zero_payload = desc.op == DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RELEASE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL;
    let payload_end = u32::from(desc.payload_offset).saturating_add(u32::from(desc.payload_len));
    let ring_payload = usize::from(desc.payload_offset) >= DRIVER_TASK_RING_FRAME_OFFSET
        && payload_end <= DRIVER_TASK_RING_PAGE_BYTES as u32;
    let bulk_shared_payload = desc.payload_offset == DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE
        && payload_end
            <= u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE)
                + u32::from(DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES);
    let post_release_shared_payload = desc.payload_offset
        == DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE
        && payload_end
            <= u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE)
                + u32::from(DRIVER_RUNTIME_CYW43_COMMAND_TX_SHARED_PAYLOAD_BYTES);
    let shared_payload = (bulk_stream_payload && bulk_shared_payload)
        || ((desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
            || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE
            || desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX)
            && post_release_shared_payload);
    let payload_ok = (carries_payload && desc.payload_len != 0 && (ring_payload || shared_payload))
        || (zero_payload && desc.payload_len == 0);
    let total_len_ok = desc.total_len == 0 || desc.total_len >= u32::from(desc.payload_len);
    let mut result = 0u32;
    if !known_op {
        result |= CYW43_DESCRIPTOR_INVALID_OP;
    }
    if !known_flags {
        result |= CYW43_DESCRIPTOR_INVALID_FLAGS;
    }
    if !payload_ok {
        result |= CYW43_DESCRIPTOR_INVALID_PAYLOAD;
    }
    if !total_len_ok {
        result |= CYW43_DESCRIPTOR_INVALID_TOTAL_LEN;
    }
    result
}

fn cyw43_stream_next_bytes(
    current_bytes: u32,
    current_total_len: u32,
    expected_total_len: u32,
    payload_len: u16,
    logical_payload_len: u16,
    allow_padded_tail: bool,
) -> Option<u32> {
    if expected_total_len == 0 {
        return None;
    }
    if current_total_len != 0 && current_total_len != expected_total_len {
        return None;
    }
    let payload_bytes = u32::from(payload_len);
    let logical_bytes = u32::from(logical_payload_len);
    if logical_bytes == 0 || logical_bytes > payload_bytes {
        return None;
    }
    let next_bytes = current_bytes.checked_add(logical_bytes)?;
    if payload_bytes == logical_bytes && next_bytes <= expected_total_len {
        return Some(next_bytes);
    }
    if !allow_padded_tail || next_bytes != expected_total_len {
        return None;
    }
    if usize::from(payload_len) > CYW43_FIRMWARE_TAIL_PAD_MAX_BYTES {
        return None;
    }
    let pad_align = CYW43_FIRMWARE_TRANSPORT_ALIGNMENT;
    let padded_remaining = logical_bytes.checked_add(pad_align - 1)? / pad_align * pad_align;
    (payload_bytes == padded_remaining).then_some(expected_total_len)
}

fn cyw43_stream_logical_payload_len(payload_len: u16, descriptor_logical_len: u32) -> Option<u16> {
    if descriptor_logical_len == 0 {
        Some(payload_len)
    } else {
        u16::try_from(descriptor_logical_len)
            .ok()
            .filter(|len| *len != 0 && *len <= payload_len)
    }
}

fn cyw43_runtime_payload_tail_zero(
    payload_offset: usize,
    logical_payload_len: u16,
    payload_len: u16,
) -> bool {
    for index in usize::from(logical_payload_len)..usize::from(payload_len) {
        if read_runtime_payload_byte(payload_offset + index) != 0 {
            return false;
        }
    }
    true
}

const fn cyw43_transport_progress_result(detail: u16) -> u32 {
    if detail == DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY {
        1
    } else {
        0
    }
}

#[cfg(target_os = "none")]
fn cyw43_active_parent_sequence() -> u32 {
    CYW43_ACTIVE_PARENT_SEQUENCE.load(Ordering::Acquire)
}

#[cfg(any(target_os = "none", test))]
const fn cyw43_sdio_owner_progress_sequence(parent_sequence: u32, owner_sequence: u32) -> u32 {
    if parent_sequence != 0 {
        parent_sequence
    } else {
        owner_sequence
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43ControlTxTurn {
    NotAttempted,
    Submitted { logical_len: usize, sdpcm_seq: u8 },
    Ambiguous { result: u32 },
}

fn service_cyw43_control_exchange_command_turn(
    command: DriverTaskCommandRecord,
) -> Option<RuntimeCommandTurn> {
    if command.sequence == 0
        || command.opcode != OPCODE_SERVICE
        || command.arg0 != HOT_PATH_CYW43_WIFI
        || command.arg1 != ROLE_NET
        || command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        return None;
    }
    let desc = read_cyw43_command_descriptor(command.frame)?;
    if desc.op != DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE {
        return None;
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_COMMAND_VALIDATED,
        command.aux0,
    );
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != HOT_PATH_CYW43_WIFI
        || !engine_initialized(&CYW43_RUNTIME_FLAGS)
    {
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        ));
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
        command.aux0,
    );
    publish_service_dispatch_progress(command);
    if !desc.valid() || !cyw43_control_exchange_descriptor_strict(desc) {
        return Some(RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault_with_result(
                command.sequence,
                FAULT_CYW43_DESCRIPTOR_INVALID,
                cyw43_descriptor_invalid_result(desc) | CYW43_DESCRIPTOR_INVALID_PAYLOAD,
            ),
        ));
    }
    let previous_parent_sequence =
        CYW43_ACTIVE_PARENT_SEQUENCE.swap(command.sequence, Ordering::AcqRel);
    let turn = CYW43_RUNTIME_STATE
        .with_mut(|state| cyw43_control_exchange_command_turn(state, desc, command.sequence));
    CYW43_ACTIVE_PARENT_SEQUENCE.store(previous_parent_sequence, Ordering::Release);
    Some(turn)
}

fn cyw43_control_exchange_descriptor_strict(desc: DriverRuntimeCyw43CommandDescriptor) -> bool {
    if desc.target_addr != 0
        || desc.reserved != 0
        || desc.total_len != u32::from(desc.payload_len)
        || desc.payload_len < CYW43_CDC_HEADER_BYTES as u16
        || desc.arg1 == 0
        || desc.arg1 > u32::from(u16::MAX)
    {
        return false;
    }
    let offset = usize::from(desc.payload_offset);
    let payload_len = usize::from(desc.payload_len);
    let Some(body_len) =
        cyw43_runtime_payload_u32(offset + 4).and_then(|len| usize::try_from(len).ok())
    else {
        return false;
    };
    cyw43_runtime_payload_u32(offset) == Some(desc.arg0)
        && cyw43_runtime_payload_u16(offset + 10) == Some(desc.arg1 as u16)
        && cyw43_runtime_payload_u32(offset + 12) == Some(CYW43_CDC_STATUS_SUCCESS)
        && body_len == payload_len.saturating_sub(CYW43_CDC_HEADER_BYTES)
}

fn cyw43_runtime_payload_u16(offset: usize) -> Option<u16> {
    let end = offset.checked_add(core::mem::size_of::<u16>())?;
    if end
        > DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize
            + usize::from(DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES)
        && end > DRIVER_TASK_RING_PAGE_BYTES
    {
        return None;
    }
    Some(
        u16::from(read_runtime_payload_byte(offset))
            | (u16::from(read_runtime_payload_byte(offset + 1)) << 8),
    )
}

fn cyw43_runtime_payload_u32(offset: usize) -> Option<u32> {
    let end = offset.checked_add(core::mem::size_of::<u32>())?;
    if end
        > DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize
            + usize::from(DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES)
        && end > DRIVER_TASK_RING_PAGE_BYTES
    {
        return None;
    }
    Some(
        u32::from(read_runtime_payload_byte(offset))
            | (u32::from(read_runtime_payload_byte(offset + 1)) << 8)
            | (u32::from(read_runtime_payload_byte(offset + 2)) << 16)
            | (u32::from(read_runtime_payload_byte(offset + 3)) << 24),
    )
}

fn cyw43_control_exchange_payload_digest(desc: DriverRuntimeCyw43CommandDescriptor) -> u32 {
    // FNV-1a covers every immutable request byte. The command/id/length/flags
    // are also compared independently so an endpoint sequence change can never
    // become authority to publish a second SDPCM request.
    let mut hash = 0x811c_9dc5u32;
    let mut index = 0usize;
    while index < usize::from(desc.payload_len) {
        hash ^= u32::from(read_runtime_payload_byte(
            usize::from(desc.payload_offset) + index,
        ));
        hash = hash.wrapping_mul(0x0100_0193);
        index = index.saturating_add(1);
    }
    hash
}

fn cyw43_control_exchange_identity_matches(
    cursor: Cyw43ControlExchangeCursor,
    desc: DriverRuntimeCyw43CommandDescriptor,
) -> bool {
    cursor.expected_cmd == desc.arg0
        && cursor.expected_id == desc.arg1 as u16
        && cursor.descriptor_flags == desc.flags
        && cursor.payload_offset == desc.payload_offset
        && cursor.payload_len == desc.payload_len
        && cursor.payload_digest == cyw43_control_exchange_payload_digest(desc)
        && CYW43_CONTROL_REQUEST.matches(desc)
}

fn cyw43_control_exchange_begin(
    state: &mut Cyw43RuntimeState,
    desc: DriverRuntimeCyw43CommandDescriptor,
) -> bool {
    // A retained exchange owns its fault/result telemetry until terminal.
    // Clear any prior operation's frame before a possible issued-unknown TX
    // so containment can publish only this request's exact failure record.
    cyw43_clear_last_fault();
    if !CYW43_CONTROL_REQUEST.store(desc) {
        return false;
    }
    state.control_exchange = Cyw43ControlExchangeCursor {
        phase: if desc.flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN != 0 {
            Cyw43ControlExchangePhase::PreTxDrain
        } else {
            Cyw43ControlExchangePhase::WaitCredit
        },
        generation: state.dpc_shared_epoch,
        expected_cmd: desc.arg0,
        expected_id: desc.arg1 as u16,
        descriptor_flags: desc.flags,
        payload_offset: desc.payload_offset,
        payload_len: desc.payload_len,
        payload_digest: cyw43_control_exchange_payload_digest(desc),
        tx_sdpcm_seq: 0,
        pre_tx_frames: 0,
        phase_turns: 0,
        nonmatching: 0,
        malformed: 0,
        last_idle_reason: Cyw43RxIdleReason::NoRframe,
        tx_deadline: runtime_deadline_from_millis_or_iterations(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_MS,
            CYW43_CONTROL_EXCHANGE_POLL_ATTEMPTS,
        ),
        reply_deadline: RuntimeDeadline::Iterations { remaining: 0 },
    };
    true
}

fn cyw43_control_exchange_generation_ready(
    state: &Cyw43RuntimeState,
    cursor: Cyw43ControlExchangeCursor,
) -> bool {
    state.initialized
        && state.transport_ready
        && state.firmware_released
        && state.bus_link_ready
        && state.dpc_link_ready
        && !state.recovery_required
        && cursor.generation != 0
        && cursor.generation == state.dpc_shared_epoch
}

fn cyw43_control_exchange_deadline_expired(
    deadline: &mut RuntimeDeadline,
    phase_turns: &mut u32,
) -> bool {
    *phase_turns = phase_turns.saturating_add(1);
    runtime_deadline_iteration_cap_reached(
        deadline,
        usize::try_from(*phase_turns).unwrap_or(usize::MAX),
        CYW43_CONTROL_EXCHANGE_POLL_ATTEMPTS,
    ) || runtime_deadline_expired(deadline)
}

fn cyw43_control_exchange_timeout_completion(
    state: &mut Cyw43RuntimeState,
    sequence: u32,
    waiting_for_reply: bool,
) -> RuntimeCommandTurn {
    let cursor = state.control_exchange;
    let result = if waiting_for_reply {
        cyw43_control_exchange_timeout_fault_result(
            cursor.last_idle_reason,
            cursor.nonmatching.saturating_add(cursor.malformed),
        )
    } else {
        CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_NOT_READY
    };
    state.reset_control_exchange();
    RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
        sequence,
        FAULT_CYW43_CONTROL_EXCHANGE,
        result,
    ))
}

fn cyw43_control_exchange_interleaved_completion(
    state: &mut Cyw43RuntimeState,
    sequence: u32,
    mut cursor: Cyw43ControlExchangeCursor,
) -> RuntimeCommandTurn {
    let Some(frame) = cyw43_rx_queue_pop_front(state) else {
        cursor.malformed = cursor.malformed.saturating_add(1);
        state.control_exchange = cursor;
        return RuntimeCommandTurn::Pending;
    };
    cursor.pre_tx_frames = cursor.pre_tx_frames.saturating_add(1);
    state.rx_frames = state.rx_frames.saturating_add(1);
    state.rx_retransmit_pending = false;
    state.control_exchange = cursor;
    RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::frame_ready_with_detail(
        sequence,
        DRIVER_RUNTIME_CYW43_CONTROL_DETAIL_INTERLEAVED_FRAME,
        frame,
    ))
}

fn cyw43_control_exchange_submit_once(
    state: &mut Cyw43RuntimeState,
    cursor: Cyw43ControlExchangeCursor,
) -> Cyw43ControlTxTurn {
    if !CYW43_CONTROL_REQUEST.restore(cursor.payload_offset, cursor.payload_len) {
        state.recovery_required = true;
        return Cyw43ControlTxTurn::Ambiguous {
            result: CYW43_DESCRIPTOR_INVALID_PAYLOAD,
        };
    }
    let frame = DriverFrameDescriptor {
        offset: u32::from(cursor.payload_offset),
        len: cursor.payload_len,
        flags: 0,
    };
    let sdpcm_seq = state.sdpcm_seq;
    let logical_len = cyw43_submit_sdpcm_frame_with_credit_policy(
        state,
        frame,
        false,
        cursor.descriptor_flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER != 0,
        false,
    );
    if logical_len != 0 {
        Cyw43ControlTxTurn::Submitted {
            logical_len,
            sdpcm_seq,
        }
    } else if state.sdpcm_tx_write_ambiguous || state.recovery_required {
        Cyw43ControlTxTurn::Ambiguous {
            result: cyw43_take_last_fault_result(),
        }
    } else {
        Cyw43ControlTxTurn::NotAttempted
    }
}

fn cyw43_control_exchange_command_turn(
    state: &mut Cyw43RuntimeState,
    desc: DriverRuntimeCyw43CommandDescriptor,
    sequence: u32,
) -> RuntimeCommandTurn {
    let mut cursor = state.control_exchange;
    if cursor.active() {
        if !cyw43_control_exchange_generation_ready(state, cursor) {
            state.reset_control_exchange();
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                sequence,
                FAULT_CYW43_TRANSPORT_BUS_LINK,
                cursor.generation,
            ));
        }
        if !cyw43_control_exchange_identity_matches(cursor, desc) {
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault(
                sequence,
                FAULT_REJECTED_COMMAND,
            ));
        }
    } else {
        if !state.initialized
            || !state.transport_ready
            || !state.firmware_released
            || !state.bus_link_ready
            || !state.dpc_link_ready
            || state.recovery_required
            || state.dpc_shared_epoch == 0
        {
            return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
                sequence,
                FAULT_CYW43_CONTROL_EXCHANGE,
                CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_NOT_READY,
            ));
        }
        if cyw43_control_exchange_begin(state, desc) {
            return RuntimeCommandTurn::Pending;
        }
        return RuntimeCommandTurn::Complete(DriverTaskCompletionRecord::fault_with_result(
            sequence,
            FAULT_CYW43_DESCRIPTOR_INVALID,
            CYW43_DESCRIPTOR_INVALID_PAYLOAD,
        ));
    }

    match cursor.phase {
        Cyw43ControlExchangePhase::Idle => RuntimeCommandTurn::Complete(
            DriverTaskCompletionRecord::fault(sequence, FAULT_CYW43_CONTROL_EXCHANGE),
        ),
        Cyw43ControlExchangePhase::PreTxDrain => {
            if cyw43_control_exchange_deadline_expired(
                &mut cursor.tx_deadline,
                &mut cursor.phase_turns,
            ) {
                state.control_exchange = cursor;
                return cyw43_control_exchange_timeout_completion(state, sequence, false);
            }
            if cursor.pre_tx_frames >= CYW43_CONTROL_EXCHANGE_PRE_TX_FRAME_LIMIT
                || state.rx_queue_count == 0
            {
                state.control_startup_status_drained = true;
                cursor.phase = Cyw43ControlExchangePhase::WaitCredit;
                state.control_exchange = cursor;
                return RuntimeCommandTurn::Pending;
            }
            let Some(flags) = cyw43_rx_queue_front_flags(state) else {
                cursor.malformed = cursor.malformed.saturating_add(1);
                state.control_exchange = cursor;
                return RuntimeCommandTurn::Pending;
            };
            match flags & DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK {
                DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT
                | DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA => {
                    cyw43_control_exchange_interleaved_completion(state, sequence, cursor)
                }
                DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL => {
                    cyw43_rx_queue_drop_front(state);
                    cursor.nonmatching = cursor.nonmatching.saturating_add(1);
                    cursor.pre_tx_frames = cursor.pre_tx_frames.saturating_add(1);
                    state.rx_frames = state.rx_frames.saturating_add(1);
                    state.control_exchange = cursor;
                    RuntimeCommandTurn::Pending
                }
                _ => {
                    cyw43_rx_queue_drop_front(state);
                    cursor.malformed = cursor.malformed.saturating_add(1);
                    cursor.pre_tx_frames = cursor.pre_tx_frames.saturating_add(1);
                    state.control_exchange = cursor;
                    RuntimeCommandTurn::Pending
                }
            }
        }
        Cyw43ControlExchangePhase::WaitCredit => {
            if cyw43_control_exchange_deadline_expired(
                &mut cursor.tx_deadline,
                &mut cursor.phase_turns,
            ) {
                state.control_exchange = cursor;
                return cyw43_control_exchange_timeout_completion(state, sequence, false);
            }
            if !has_sdpcm_credit_for_frame(state.sdpcm_seq, state.sdpcm_seq_max, false) {
                state.control_exchange = cursor;
                return RuntimeCommandTurn::Pending;
            }
            cyw43_publish_control_rx_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_BEGIN,
            );
            match cyw43_control_exchange_submit_once(state, cursor) {
                Cyw43ControlTxTurn::NotAttempted => {
                    state.control_exchange = cursor;
                    RuntimeCommandTurn::Pending
                }
                Cyw43ControlTxTurn::Submitted {
                    logical_len,
                    sdpcm_seq,
                } => {
                    cursor.phase = Cyw43ControlExchangePhase::WaitReply;
                    cursor.phase_turns = 0;
                    cursor.tx_sdpcm_seq = sdpcm_seq;
                    cursor.reply_deadline = runtime_deadline_from_millis_or_iterations(
                        CYW43_CONTROL_EXCHANGE_TIMEOUT_MS,
                        CYW43_CONTROL_EXCHANGE_POLL_ATTEMPTS,
                    );
                    state.control_exchange = cursor;
                    CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
                    cyw43_publish_control_rx_progress(
                        sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_DONE,
                    );
                    cyw43_publish_control_rx_progress(
                        sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_POLL_BEGIN,
                    );
                    cyw43_service_trace_record(
                        state,
                        DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
                        CYW43_SERVICE_REASON_CONTROL_EXCHANGE,
                        logical_len as u32,
                        None,
                    );
                    RuntimeCommandTurn::Pending
                }
                Cyw43ControlTxTurn::Ambiguous { result } => {
                    let frame = cyw43_take_last_fault_frame();
                    state.reset_control_exchange();
                    RuntimeCommandTurn::Complete(if frame.len == 0 {
                        DriverTaskCompletionRecord::fault_with_result(
                            sequence,
                            FAULT_CYW43_CONTROL_FRAME,
                            result,
                        )
                    } else {
                        DriverTaskCompletionRecord::fault_with_result_and_frame(
                            sequence,
                            FAULT_CYW43_CONTROL_FRAME,
                            result,
                            frame,
                        )
                    })
                }
            }
        }
        Cyw43ControlExchangePhase::WaitReply => {
            if cyw43_control_exchange_deadline_expired(
                &mut cursor.reply_deadline,
                &mut cursor.phase_turns,
            ) {
                state.control_exchange = cursor;
                return cyw43_control_exchange_timeout_completion(state, sequence, true);
            }
            let Some(flags) = cyw43_rx_queue_front_flags(state) else {
                cursor.last_idle_reason = Cyw43RxIdleReason::NoRframe;
                state.control_exchange = cursor;
                return RuntimeCommandTurn::Pending;
            };
            match flags & DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK {
                DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT
                | DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA => {
                    cyw43_control_exchange_interleaved_completion(state, sequence, cursor)
                }
                DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL => {
                    let Some(reply) = cyw43_control_reply_from_queue_front(state) else {
                        cyw43_rx_queue_drop_front(state);
                        cursor.malformed = cursor.malformed.saturating_add(1);
                        state.rx_frames = state.rx_frames.saturating_add(1);
                        state.control_exchange = cursor;
                        return RuntimeCommandTurn::Pending;
                    };
                    if cyw43_control_reply_is_commandless_reject(reply) {
                        cyw43_rx_queue_drop_front(state);
                        state.rx_frames = state.rx_frames.saturating_add(1);
                        state.reset_control_exchange();
                        return RuntimeCommandTurn::Complete(
                            DriverTaskCompletionRecord::fault_with_result(
                                sequence,
                                FAULT_CYW43_CONTROL_EXCHANGE,
                                reply.status,
                            ),
                        );
                    }
                    if reply.cmd != cursor.expected_cmd || reply.id != cursor.expected_id {
                        cyw43_rx_queue_drop_front(state);
                        cursor.nonmatching = cursor.nonmatching.saturating_add(1);
                        state.rx_frames = state.rx_frames.saturating_add(1);
                        state.control_exchange = cursor;
                        return RuntimeCommandTurn::Pending;
                    }
                    if reply.status != CYW43_CDC_STATUS_SUCCESS
                        || reply.response_len > reply.payload_available as u32
                        || reply.response_len > u32::from(u16::MAX)
                    {
                        cyw43_rx_queue_drop_front(state);
                        state.rx_frames = state.rx_frames.saturating_add(1);
                        state.reset_control_exchange();
                        return RuntimeCommandTurn::Complete(
                            DriverTaskCompletionRecord::fault_with_result(
                                sequence,
                                FAULT_CYW43_CONTROL_EXCHANGE,
                                if reply.status != CYW43_CDC_STATUS_SUCCESS {
                                    reply.status
                                } else {
                                    reply.response_len
                                },
                            ),
                        );
                    }
                    let Some(frame) = cyw43_rx_queue_pop_front(state) else {
                        cursor.malformed = cursor.malformed.saturating_add(1);
                        state.control_exchange = cursor;
                        return RuntimeCommandTurn::Pending;
                    };
                    let response = DriverFrameDescriptor {
                        offset: frame.offset.saturating_add(CYW43_CDC_HEADER_BYTES as u32),
                        len: reply.response_len as u16,
                        flags: frame.flags,
                    };
                    state.rx_frames = state.rx_frames.saturating_add(1);
                    state.rx_retransmit_pending = false;
                    state.reset_control_exchange();
                    RuntimeCommandTurn::Complete(
                        DriverTaskCompletionRecord::frame_ready_with_descriptor(sequence, response),
                    )
                }
                _ => {
                    cyw43_rx_queue_drop_front(state);
                    cursor.malformed = cursor.malformed.saturating_add(1);
                    state.control_exchange = cursor;
                    RuntimeCommandTurn::Pending
                }
            }
        }
    }
}

fn service_cyw43_descriptor_command(
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    let Some(desc) = read_cyw43_command_descriptor(command.frame) else {
        return DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_CYW43_DESCRIPTOR_UNAVAILABLE,
        );
    };
    if !desc.valid() {
        return DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_DESCRIPTOR_INVALID,
            cyw43_descriptor_invalid_result(desc),
        );
    }
    if desc.op == DRIVER_RUNTIME_CYW43_OP_RELEASE {
        CYW43_LAST_RELEASE_PHASE.store(0, Ordering::Release);
    }
    cyw43_clear_last_fault();
    let mut exact_fault = None;
    let mut frame_ready = None;
    let mut progress_detail = None;
    let mut progress_frame = DriverFrameDescriptor::empty();
    let mut rx_idle_reason = None;
    let mut queue_only_poll = false;
    let previous_parent_sequence =
        CYW43_ACTIVE_PARENT_SEQUENCE.swap(command.sequence, Ordering::AcqRel);
    let result = CYW43_RUNTIME_STATE.with_mut(|state| match desc.op {
        DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT => {
            cyw43_transport_init_command(command.sequence, command.aux0, state).map_or_else(
                |detail| {
                    exact_fault = Some(detail);
                    0
                },
                |detail| {
                    progress_detail = Some(detail);
                    cyw43_transport_progress_result(detail)
                },
            )
        }
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP => cyw43_prepare_firmware_upload_transport(state)
            .map_or_else(
                |detail| {
                    exact_fault = Some(detail);
                    0
                },
                |()| 1,
            ),
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => {
            let expected_total = desc.total_len.max(u32::from(desc.payload_len));
            let logical_payload_len =
                cyw43_stream_logical_payload_len(desc.payload_len, desc.arg0).unwrap_or(0);
            if let Some(next_bytes) = cyw43_stream_next_bytes(
                state.firmware_bytes,
                state.firmware_total_len,
                expected_total,
                desc.payload_len,
                logical_payload_len,
                true,
            ) {
                if !cyw43_ram_payload_bounds(desc.target_addr, desc.payload_len) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_RAM);
                    0
                } else if !cyw43_runtime_payload_tail_zero(
                    usize::from(desc.payload_offset),
                    logical_payload_len,
                    desc.payload_len,
                ) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_TAIL);
                    0
                } else if !state.firmware_upload_prepared {
                    cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                    0
                } else if cyw43_stage_firmware_chunk(
                    state,
                    desc.target_addr,
                    usize::from(desc.payload_offset),
                    usize::from(desc.payload_len),
                    next_bytes == expected_total,
                ) {
                    if state.firmware_total_len == 0 {
                        state.firmware_total_len = expected_total;
                    }
                    state.firmware_bytes = next_bytes;
                    state.firmware_uploaded = state.firmware_bytes == state.firmware_total_len;
                    u32::from(desc.payload_len)
                } else {
                    0
                }
            } else {
                cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STREAM);
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK => {
            let expected_total = desc.total_len.max(u32::from(desc.payload_len));
            if let Some(next_bytes) = cyw43_stream_next_bytes(
                state.nvram_bytes,
                state.nvram_total_len,
                expected_total,
                desc.payload_len,
                desc.payload_len,
                false,
            ) {
                if !cyw43_ram_payload_bounds(desc.target_addr, desc.payload_len) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_RAM);
                    0
                } else if !state.firmware_upload_prepared {
                    cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                    0
                } else if cyw43_stage_firmware_chunk(
                    state,
                    desc.target_addr,
                    usize::from(desc.payload_offset),
                    usize::from(desc.payload_len),
                    true,
                ) {
                    if state.nvram_total_len == 0 {
                        state.nvram_total_len = expected_total;
                    }
                    state.nvram_bytes = next_bytes;
                    state.nvram_uploaded = state.nvram_bytes == state.nvram_total_len;
                    u32::from(desc.payload_len)
                } else {
                    0
                }
            } else {
                cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STREAM);
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL => {
            if !state.firmware_upload_prepared {
                cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                0
            } else if cyw43_ram_payload_bounds(desc.target_addr, 4)
                && cyw43_backplane_write_u32(state, desc.target_addr, desc.arg0)
            {
                state.nvram_tail_uploaded = true;
                state.nvram_tail_magic = desc.arg0;
                4
            } else {
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_RELEASE => {
            if state.firmware_stage_len != 0 && !cyw43_flush_firmware_stage(state) {
                0
            } else if cyw43_release_firmware(state, desc.arg0, command.sequence) {
                let activation = cyw43_activate_sdio_dpc_via_bus_link(state.dpc_shared_epoch);
                let activated = activation.is_some_and(|(sequence, completion)| {
                    cyw43_dpc_activation_completion_exact(
                        completion,
                        sequence,
                        state.dpc_shared_epoch,
                    )
                });
                if activated {
                    state.firmware_released = true;
                    1
                } else {
                    let result = activation
                        .map(|(_, completion)| cyw43_dpc_activation_failure_result(completion))
                        .unwrap_or(0);
                    cyw43_record_last_fault_with_result(
                        FAULT_CYW43_POST_RELEASE_DPC_ACTIVATE,
                        result,
                    );
                    let _ = cyw43_release_fail_closed(state);
                    0
                }
            } else {
                cyw43_record_release_fault_if_missing();
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME => {
            let frame = DriverFrameDescriptor {
                offset: u32::from(desc.payload_offset),
                len: desc.payload_len,
                flags: 0,
            };
            let control_ext_header = desc.flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER != 0;
            let control_pre_tx_drain =
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN != 0;
            if let Some(frame) = cyw43_linked_control_pre_tx_pop(state, control_pre_tx_drain) {
                // The persistent DPC is the sole physical RX producer.  A
                // flagged split control request must return every preexisting
                // FIFO head to root, in wire order, before it may publish a
                // new SDPCM sequence.  Root resubmits the identical descriptor
                // and payload after routing this terminal FrameReady result.
                frame_ready = Some(frame);
                cyw43_service_trace_record(
                    state,
                    desc.op,
                    CYW43_SERVICE_REASON_CONTROL_FRAME,
                    u32::from(frame.len),
                    Some(frame.flags),
                );
                u32::from(frame.len)
            } else {
                if state.dpc_link_ready && control_pre_tx_drain {
                    state.control_startup_status_drained = true;
                } else {
                    cyw43_drain_startup_status_frames(
                        state,
                        command.sequence,
                        control_pre_tx_drain,
                    );
                    if control_pre_tx_drain {
                        state.rx_queue_protect_eapol = true;
                        cyw43_drain_rx_before_control_tx(state, command.sequence);
                    }
                }
                cyw43_publish_control_rx_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_BEGIN,
                );
                let written = cyw43_submit_sdpcm_frame(state, frame, false, control_ext_header);
                if written != 0 {
                    cyw43_publish_control_rx_progress(
                        command.sequence,
                        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_DONE,
                    );
                }
                cyw43_service_trace_record(
                    state,
                    desc.op,
                    CYW43_SERVICE_REASON_CONTROL_FRAME,
                    written as u32,
                    None,
                );
                written as u32
            }
        }
        DRIVER_RUNTIME_CYW43_OP_ETH_TX => {
            let frame = DriverFrameDescriptor {
                offset: u32::from(desc.payload_offset),
                len: desc.payload_len,
                flags: 0,
            };
            state.rx_queue_protect_eapol = cyw43_runtime_payload_ethertype(
                usize::from(desc.payload_offset),
                usize::from(desc.payload_len),
            ) == Some(CYW43_ETH_P_EAPOL);
            let submitted_seq = state.sdpcm_seq;
            let credit_observations_before = state.sdpcm_credit_observations;
            let expected_request_len = cyw43_data_tx_total_len(usize::from(frame.len))
                .map(|total_len| cyw43_data_tx_request_len_for_frame(frame, total_len).0);
            if state.eth_tx_phase == CYW43_ETH_TX_PHASE_IDLE {
                cyw43_eth_tx_begin_wait_credit(state, frame);
            } else if !cyw43_eth_tx_identity_matches(state, frame) {
                cyw43_eth_tx_clear_wait_credit(state);
                cyw43_record_last_fault(FAULT_CYW43_ETH_TX);
                return 0;
            }
            let priority = cyw43_bdc_priority_for_runtime_packet(
                frame.offset as usize,
                usize::from(frame.len),
            );
            let reserve_control_credit = !cyw43_data_tx_uses_control_credit_timeout(frame);
            if cyw43_data_tx_flowcontrol_blocked(state, priority)
                || !has_sdpcm_credit_for_frame(
                    state.sdpcm_seq,
                    state.sdpcm_seq_max,
                    reserve_control_credit,
                )
            {
                // One PromptSlice performs at most one physical RX/credit
                // action. The exact payload identity remains pinned in runtime
                // state, so a later outer turn resumes without assigning or
                // publishing another SDPCM sequence.
                cyw43_eth_tx_service_one_credit_action(state);
            }
            let ready = !cyw43_data_tx_flowcontrol_blocked(state, priority)
                && has_sdpcm_credit_for_frame(
                    state.sdpcm_seq,
                    state.sdpcm_seq_max,
                    reserve_control_credit,
                );
            let written = if ready {
                cyw43_submit_sdpcm_frame_with_credit_policy(state, frame, true, false, false)
            } else {
                0
            };
            if written != 0 {
                cyw43_eth_tx_clear_wait_credit(state);
                progress_detail = u16::try_from(
                    expected_request_len
                        .unwrap_or_else(|| cyw43_data_tx_request_len_default(written)),
                )
                .ok();
                progress_frame = cyw43_sdpcm_tx_credit_proof_frame(
                    submitted_seq,
                    state.sdpcm_seq_max,
                    state.sdpcm_credit_observations,
                );
            } else if state.sdpcm_credit_observations != credit_observations_before {
                progress_frame = cyw43_sdpcm_credit_snapshot_frame(state);
            }
            cyw43_service_trace_record(
                state,
                desc.op,
                CYW43_SERVICE_REASON_ETH_TX,
                written as u32,
                None,
            );
            written as u32
        }
        DRIVER_RUNTIME_CYW43_OP_RX_POLL => {
            state.rx_queue_protect_eapol =
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_STEADY_TAIL_DRAIN == 0;
            let before = Cyw43RuntimeServiceSnapshot::from_state(state);
            let credit_observations_before = state.sdpcm_credit_observations;
            queue_only_poll = true;
            let poll = cyw43_runtime_poll_queued_wire_head(state);
            match poll {
                Cyw43RxPollResult::Frame(frame) => {
                    frame_ready = Some(frame);
                    cyw43_service_trace_record(
                        state,
                        desc.op,
                        CYW43_SERVICE_REASON_RX_POLL,
                        u32::from(frame.len),
                        Some(frame.flags),
                    );
                    u32::from(frame.len)
                }
                Cyw43RxPollResult::Idle(reason) => {
                    rx_idle_reason = Some(reason);
                    if state.sdpcm_credit_observations != credit_observations_before {
                        progress_frame = cyw43_sdpcm_credit_snapshot_frame(state);
                    }
                    let progress = cyw43_runtime_service_progress_result(before, state);
                    cyw43_service_trace_record(
                        state,
                        desc.op,
                        CYW43_SERVICE_REASON_RX_POLL,
                        progress,
                        None,
                    );
                    progress
                }
            }
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL => {
            state.rx_queue_protect_eapol = true;
            let before = Cyw43RuntimeServiceSnapshot::from_state(state);
            let credit_observations_before = state.sdpcm_credit_observations;
            queue_only_poll = true;
            match cyw43_runtime_poll_control_rx_detailed(
                state,
                command.sequence,
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD != 0,
            ) {
                Cyw43RxPollResult::Frame(frame) => {
                    frame_ready = Some(frame);
                    cyw43_service_trace_record(
                        state,
                        desc.op,
                        CYW43_SERVICE_REASON_CONTROL_POLL,
                        u32::from(frame.len),
                        Some(frame.flags),
                    );
                    u32::from(frame.len)
                }
                Cyw43RxPollResult::Idle(reason) => {
                    rx_idle_reason = Some(reason);
                    if state.sdpcm_credit_observations != credit_observations_before {
                        progress_frame = cyw43_sdpcm_credit_snapshot_frame(state);
                    }
                    let progress = cyw43_runtime_service_progress_result(before, state);
                    cyw43_service_trace_record(
                        state,
                        desc.op,
                        CYW43_SERVICE_REASON_CONTROL_POLL,
                        progress,
                        None,
                    );
                    progress
                }
            }
        }
        _ => 0,
    });
    CYW43_ACTIVE_PARENT_SEQUENCE.store(previous_parent_sequence, Ordering::Release);
    if let Some(detail) = exact_fault {
        let fault_result = cyw43_take_last_fault_result();
        let frame = cyw43_take_last_fault_frame();
        if frame.len == 0 && fault_result == 0 {
            DriverTaskCompletionRecord::fault(command.sequence, detail)
        } else if frame.len == 0 {
            DriverTaskCompletionRecord::fault_with_result(command.sequence, detail, fault_result)
        } else {
            DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                detail,
                fault_result,
                frame,
            )
        }
    } else if let Some(detail) = progress_detail {
        let mut completion =
            DriverTaskCompletionRecord::progress_with_detail(command.sequence, detail, result);
        completion.frame = progress_frame;
        completion
    } else if result == 0
        && (desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
            || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL)
    {
        if queue_only_poll || desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD != 0 {
            let reason = rx_idle_reason.unwrap_or(Cyw43RxIdleReason::NoRframe);
            let detail = cyw43_rx_idle_detail(reason);
            let idle_result = cyw43_rx_idle_result(reason);
            let mut frame = CYW43_RUNTIME_STATE
                .with_mut(|state| cyw43_stage_rx_idle_trace(state, detail, idle_result));
            if progress_frame.flags != 0 {
                frame.flags = progress_frame.flags;
            }
            DriverTaskCompletionRecord::idle_with_detail_and_frame(
                command.sequence,
                detail,
                idle_result,
                frame,
            )
        } else if progress_frame.flags != 0 {
            DriverTaskCompletionRecord::idle_with_detail_and_frame(
                command.sequence,
                FAULT_NONE,
                0,
                progress_frame,
            )
        } else {
            DriverTaskCompletionRecord::idle(command.sequence)
        }
    } else if result == 0
        && ((desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX && cyw43_take_last_fault_detail().is_none())
            || (desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
                && cyw43_take_last_fault_detail().is_none()))
    {
        if progress_frame.flags != 0 {
            DriverTaskCompletionRecord::idle_with_detail_and_frame(
                command.sequence,
                FAULT_NONE,
                0,
                progress_frame,
            )
        } else {
            DriverTaskCompletionRecord::idle(command.sequence)
        }
    } else if result == 0 {
        let detail =
            cyw43_take_last_fault_detail().unwrap_or_else(|| cyw43_command_fault_detail(desc.op));
        let fault_result = cyw43_take_last_fault_result();
        let frame = cyw43_take_last_fault_frame();
        if frame.len == 0 {
            DriverTaskCompletionRecord::fault_with_result(command.sequence, detail, fault_result)
        } else {
            DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                detail,
                fault_result,
                frame,
            )
        }
    } else if let Some(frame) = frame_ready {
        DriverTaskCompletionRecord::frame_ready_with_descriptor(command.sequence, frame)
    } else {
        let mut completion = DriverTaskCompletionRecord::progress(command.sequence, result);
        if desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
            || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL
        {
            let mut frame = CYW43_RUNTIME_STATE
                .with_mut(|state| cyw43_stage_rx_idle_trace(state, FAULT_NONE, 0));
            if progress_frame.flags != 0 {
                frame.flags = progress_frame.flags;
            }
            completion.frame = frame;
        } else {
            completion.frame = progress_frame;
        }
        completion
    }
}

fn cyw43_clear_last_fault() {
    CYW43_LAST_FAULT_DETAIL.store(FAULT_NONE as u32, Ordering::Release);
    CYW43_LAST_FAULT_RESULT.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(0, Ordering::Release);
}

fn cyw43_record_last_fault(detail: u16) {
    cyw43_record_last_fault_with_result(detail, 0);
}

fn cyw43_record_last_fault_with_result(detail: u16, result: u32) {
    if detail != FAULT_NONE {
        CYW43_LAST_FAULT_DETAIL.store(u32::from(detail), Ordering::Release);
        CYW43_LAST_FAULT_RESULT.store(result, Ordering::Release);
    }
}

fn cyw43_record_firmware_range_fault(result: u32) {
    cyw43_record_last_fault_with_result(FAULT_CYW43_FIRMWARE_RANGE, result);
}

fn cyw43_record_last_fault_frame(frame: DriverFrameDescriptor) {
    if frame.len == 0 {
        return;
    }
    let meta = u32::from(frame.len) | (u32::from(frame.flags) << 16);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(frame.offset, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(meta, Ordering::Release);
}

fn cyw43_take_last_fault_detail() -> Option<u16> {
    let detail = CYW43_LAST_FAULT_DETAIL.load(Ordering::Acquire) as u16;
    (detail != FAULT_NONE).then_some(detail)
}

fn cyw43_take_last_fault_result() -> u32 {
    CYW43_LAST_FAULT_RESULT.load(Ordering::Acquire)
}

fn cyw43_take_last_fault_frame() -> DriverFrameDescriptor {
    let meta = CYW43_LAST_FAULT_FRAME_META.load(Ordering::Acquire);
    let len = (meta & 0xffff) as u16;
    if len == 0 {
        DriverFrameDescriptor::empty()
    } else {
        DriverFrameDescriptor {
            offset: CYW43_LAST_FAULT_FRAME_OFFSET.load(Ordering::Acquire),
            len,
            flags: (meta >> 16) as u16,
        }
    }
}

const fn cyw43_command_fault_detail(op: u16) -> u16 {
    match op {
        DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT => FAULT_CYW43_TRANSPORT_INIT,
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP => FAULT_CYW43_FIRMWARE_PREP,
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => FAULT_CYW43_FIRMWARE_CHUNK,
        DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK => FAULT_CYW43_NVRAM_CHUNK,
        DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL => FAULT_CYW43_NVRAM_TAIL,
        DRIVER_RUNTIME_CYW43_OP_RELEASE => FAULT_CYW43_RELEASE,
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME => FAULT_CYW43_CONTROL_FRAME,
        DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE => FAULT_CYW43_CONTROL_EXCHANGE,
        DRIVER_RUNTIME_CYW43_OP_ETH_TX => FAULT_CYW43_ETH_TX,
        _ => FAULT_CYW43_COMMAND,
    }
}

const fn sdio_descriptor_response_flags(response_kind: u8) -> u16 {
    match response_kind {
        DRIVER_RUNTIME_SDIO_RESP_NONE => DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE,
        DRIVER_RUNTIME_SDIO_RESP_OCR => DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
        DRIVER_RUNTIME_SDIO_RESP_SHORT => DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY => DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY,
        DRIVER_RUNTIME_SDIO_RESP_LONG => DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG,
        _ => 0,
    }
}

const fn sdio_cmd52_arg(write: bool, function: u8, addr: u32, value: u8) -> u32 {
    (if write { 1 << 31 } else { 0 })
        | ((function as u32 & 0x7) << 28)
        | ((addr & 0x1ffff) << 9)
        | value as u32
}

const fn sdio_cmd53_arg(
    write: bool,
    function: u8,
    addr: u32,
    increment: bool,
    block_count: u16,
    len: u16,
) -> u32 {
    let block_mode = block_count != 0;
    let count = if block_mode { block_count } else { len };
    (if write { 1 << 31 } else { 0 })
        | ((function as u32 & 0x7) << 28)
        | (if block_mode { 1 << 27 } else { 0 })
        | (if increment { 1 << 26 } else { 0 })
        | ((addr & 0x1ffff) << 9)
        | ((count as u32) & 0x1ff)
}

fn sdio_response_flag_count(flags: u16) -> u32 {
    let response_flags = flags
        & (DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG);
    response_flags.count_ones()
}

const fn sdio_response_kind_from_flags(flags: u16) -> Option<u8> {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_NONE)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_OCR)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_SHORT)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_LONG)
    } else {
        None
    }
}

const fn sdio_command_waits_for_data_inhibit(flags: u16, has_data: bool) -> bool {
    has_data || flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0
}

const SDIO_TRANSFER_FAILURE_STAGE_INHIBIT: u32 = 1;
const SDIO_TRANSFER_FAILURE_STAGE_COMMAND: u32 = 2;
const SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT: u32 = 3;
const SDIO_TRANSFER_FAILURE_STAGE_DATA_END: u32 = 4;
const SDIO_TRANSFER_FAILURE_STAGE_RESPONSE: u32 = 5;
const SDIO_TRANSFER_FAILURE_STAGE_POST_ISSUE_QUIESCE: u32 = 6;

const fn sdio_transfer_failure_result(stage: u32, status: u32) -> u32 {
    ((stage & 0xff) << 24) | (status & 0x00ff_ffff)
}

const fn sdio_transfer_interrupt_failure_result(stage: u32, status: u32) -> u32 {
    let retained_status = status & 0x00ff_ffff;
    let upper_error = status & SDHCI_INT_ALL_ERROR_MASK & !0x00ff_ffff != 0;
    sdio_transfer_failure_result(
        stage,
        retained_status
            | if upper_error {
                // The fixed completion result dedicates its high byte to the
                // stage. Preserve the full word in fault telemetry and fold
                // any upper controller error into the standard error-summary
                // bit so result-only consumers still see a terminal error.
                SDHCI_INT_ERROR
            } else {
                0
            },
    )
}

const fn sdio_transfer_failure_stage(result: u32) -> u32 {
    (result >> 24) & 0xff
}

fn sdio_clear_last_transfer_failure() {
    SDIO_LAST_TRANSFER_FAILURE.store(0, Ordering::Release);
    SDIO_LAST_TRANSFER_RAW_ERROR_STATUS.store(0, Ordering::Release);
}

fn sdio_record_transfer_failure(stage: u32, status: u32) {
    SDIO_LAST_TRANSFER_FAILURE.store(
        sdio_transfer_failure_result(stage, status),
        Ordering::Release,
    );
}

fn sdio_record_interrupt_transfer_failure(stage: u32, status: u32) {
    SDIO_LAST_TRANSFER_RAW_ERROR_STATUS.store(status, Ordering::Release);
    SDIO_LAST_TRANSFER_FAILURE.store(
        sdio_transfer_interrupt_failure_result(stage, status),
        Ordering::Release,
    );
}

fn sdio_record_transfer_failure_result(result: u32) {
    if result != 0 {
        SDIO_LAST_TRANSFER_FAILURE.store(result, Ordering::Release);
    }
}

fn sdio_last_transfer_failure() -> u32 {
    SDIO_LAST_TRANSFER_FAILURE.load(Ordering::Acquire)
}

fn sdio_last_transfer_raw_error_status() -> u32 {
    SDIO_LAST_TRANSFER_RAW_ERROR_STATUS.load(Ordering::Acquire)
}

const fn sdio_transfer_mode_from_flags(flags: u16, block_count: u16) -> u16 {
    let mut transfer = 0;
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
        transfer |= SDHCI_TRNS_BLK_CNT_EN;
        if flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0 {
            transfer |= SDHCI_TRNS_READ;
        }
        if block_count > 1 {
            transfer |= SDHCI_TRNS_MULTI;
        }
    }
    transfer
}

const fn sdio_descriptor_host_block_count(desc_block_count: u16, flags: u16) -> u16 {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 && desc_block_count == 0 {
        1
    } else {
        desc_block_count
    }
}

fn sdio_write_fault_telemetry_frame(
    cmd: u16,
    arg: u32,
    flags: u16,
    len: u16,
    block_size: u16,
    block_count: u16,
    transfer_mode: u16,
    failure_result: u32,
    payload_frame: DriverFrameDescriptor,
) -> DriverFrameDescriptor {
    let mut io = SdioMmioTransferIo;
    sdio_write_fault_telemetry_frame_with(
        &mut io,
        cmd,
        arg,
        flags,
        len,
        block_size,
        block_count,
        transfer_mode,
        failure_result,
        payload_frame,
    )
}

fn sdio_write_fault_telemetry_frame_with<I: SdioTransferIo>(
    io: &mut I,
    cmd: u16,
    arg: u32,
    flags: u16,
    len: u16,
    block_size: u16,
    block_count: u16,
    transfer_mode: u16,
    failure_result: u32,
    payload_frame: DriverFrameDescriptor,
) -> DriverFrameDescriptor {
    let offset = SDIO_FAULT_TELEMETRY_FRAME_OFFSET;
    let (payload_edge, payload_sum) = sdio_fault_payload_digest_with(io, flags, payload_frame);
    write_ring_u32(offset, SDIO_FAULT_TELEMETRY_MAGIC);
    write_ring_u32(offset + 4, SDIO_FAULT_TELEMETRY_VERSION);
    write_ring_u32(offset + SDIO_FAULT_TELEMETRY_ARG_OFFSET, arg);
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_CMD_FLAGS_OFFSET,
        u32::from(cmd) | (u32::from(flags) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_LEN_BLOCK_OFFSET,
        u32::from(len) | (u32::from(block_size) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_COUNT_MODE_OFFSET,
        u32::from(block_count) | (u32::from(transfer_mode) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PRESENT_OFFSET,
        io.read32(SDHCI_PRESENT_STATE),
    );
    let retained_error_status = sdio_last_transfer_raw_error_status();
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_INT_STATUS_OFFSET,
        if retained_error_status != 0 {
            retained_error_status
        } else {
            io.read32(SDHCI_INT_STATUS)
        },
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_RESPONSE0_OFFSET,
        io.read32(SDHCI_RESPONSE),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_HOST_CLOCK_OFFSET,
        u32::from(io.read8(SDHCI_HOST_CONTROL))
            | (u32::from(io.read8(SDHCI_POWER_CONTROL)) << 8)
            | (u32::from(io.read16(SDHCI_CLOCK_CONTROL)) << 16),
    );
    write_ring_u32(offset + SDIO_FAULT_TELEMETRY_FAILURE_OFFSET, failure_result);
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_BLOCK_REG_OFFSET,
        io.read32(SDHCI_BLOCK_SIZE),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PAYLOAD_EDGE_OFFSET,
        payload_edge,
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PAYLOAD_SUM_OFFSET,
        payload_sum,
    );
    DriverFrameDescriptor {
        offset: offset as u32,
        len: SDIO_FAULT_TELEMETRY_BYTES,
        flags: 0,
    }
}

fn sdio_fault_payload_digest(flags: u16, frame: DriverFrameDescriptor) -> (u32, u32) {
    let mut io = SdioMmioTransferIo;
    sdio_fault_payload_digest_with(&mut io, flags, frame)
}

fn sdio_fault_payload_digest_with<I: SdioTransferIo>(
    io: &mut I,
    flags: u16,
    frame: DriverFrameDescriptor,
) -> (u32, u32) {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA == 0
        || flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0
        || frame.len == 0
    {
        return (0, 0);
    }
    let len = usize::from(frame.len);
    let mut first = 0u8;
    let mut last = 0u8;
    let mut xor = 0u8;
    let mut sum = 0u32;
    let mut index = 0usize;
    while index < len {
        let byte = io.read_payload_byte(frame.offset as usize + index);
        if index == 0 {
            first = byte;
        }
        last = byte;
        xor ^= byte;
        sum = sum.wrapping_add(u32::from(byte));
        index = index.saturating_add(1);
    }
    (
        u32::from(first) | (u32::from(last) << 8) | (u32::from(xor) << 16),
        sum,
    )
}

const fn sdio_r5_status(response: u32) -> u32 {
    response & SDIO_R5_STATUS_MASK
}

const fn sdio_cmd53_arg_write(arg: u32) -> bool {
    arg & (1 << 31) != 0
}

const fn sdio_cmd53_arg_function(arg: u32) -> u8 {
    ((arg >> 28) & 0x7) as u8
}

const fn sdio_cmd53_arg_addr(arg: u32) -> u32 {
    (arg >> 9) & 0x1ffff
}

const fn sdio_r5_response_flags_valid(cmd: u16, flags: u16) -> bool {
    if cmd != SDIO_CMD52 && cmd != SDIO_CMD53 {
        return true;
    }
    flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT != 0
        && flags
            & (DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG)
            == 0
}

const fn sdio_r5_error(cmd: u16, response: u32) -> Option<u32> {
    if cmd != SDIO_CMD52 && cmd != SDIO_CMD53 {
        return None;
    }
    let status = sdio_r5_status(response);
    if status == 0 {
        None
    } else {
        Some(status)
    }
}

#[cfg(target_os = "none")]
fn sdio_execute_command(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
) -> Option<u32> {
    sdio_execute_transfer(cmd, arg, flags, frame, frame.len.max(1), 1)
}

#[cfg(target_os = "none")]
fn sdio_execute_transfer(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
) -> Option<u32> {
    sdio_execute_transfer_with_timeout(cmd, arg, flags, frame, block_size, block_count, 0)
}

#[cfg(target_os = "none")]
fn sdio_execute_transfer_with_timeout(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    timeout_us: u32,
) -> Option<u32> {
    match RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) {
        HOT_PATH_CYW43_WIFI => {
            if !cyw43_uses_sdio_bus_link() {
                cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_BUS_LINK);
                return None;
            }
            return sdio_execute_via_bus_link(
                cmd,
                arg,
                flags,
                frame,
                block_size,
                block_count,
                timeout_us,
            );
        }
        HOT_PATH_SDIO_HOST => {}
        _ => return None,
    }
    let timeout_us = sdio_owner_descriptor_timeout_us(timeout_us);
    let mut owner_deadline =
        runtime_deadline_from_micros_or_legacy_spins(timeout_us, SDHCI_CMD_WAIT_LOOPS);
    sdio_execute_transfer_until(
        cmd,
        arg,
        flags,
        frame,
        block_size,
        block_count,
        &mut owner_deadline,
    )
}

#[cfg(target_os = "none")]
fn sdio_execute_transfer_until(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    owner_deadline: &mut RuntimeDeadline,
) -> Option<u32> {
    let mut io = SdioMmioTransferIo;
    sdio_execute_transfer_until_with(
        &mut io,
        cmd,
        arg,
        flags,
        frame,
        block_size,
        block_count,
        owner_deadline,
    )
}

fn sdio_execute_transfer_until_with<I: SdioTransferIo>(
    io: &mut I,
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    owner_deadline: &mut RuntimeDeadline,
) -> Option<u32> {
    if !sdio_r5_response_flags_valid(cmd, flags) {
        sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_RESPONSE, 0);
        return None;
    }
    let has_data = flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0;
    let write = flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0;
    let short_busy_response = flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0;
    if !sdio_wait_inhibit_clear_until_with(
        io,
        sdio_command_waits_for_data_inhibit(flags, has_data),
        owner_deadline,
    ) {
        sdio_record_transfer_failure(
            SDIO_TRANSFER_FAILURE_STAGE_INHIBIT,
            io.read32(SDHCI_PRESENT_STATE),
        );
        return None;
    }
    io.write32(SDHCI_INT_STATUS, SDHCI_INT_COMMAND_DATA_CLEAR_MASK);
    if has_data {
        io.write16(SDHCI_BLOCK_SIZE, block_size);
        io.write16(SDHCI_BLOCK_COUNT, block_count.max(1));
    } else {
        io.write16(SDHCI_TRANSFER_MODE, 0);
    }
    io.write32(SDHCI_ARGUMENT, arg);
    if has_data {
        io.write16(SDHCI_TRANSFER_MODE, sdio_transfer_mode(write, block_count));
    }
    io.write16(SDHCI_COMMAND, sdio_make_command(cmd, flags, has_data));
    let cmd_status = sdio_wait_int_until_with(io, SDHCI_INT_RESPONSE, owner_deadline);
    if cmd_status & SDHCI_INT_ALL_ERROR_MASK != 0 || cmd_status & SDHCI_INT_RESPONSE == 0 {
        sdio_record_interrupt_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_COMMAND, cmd_status);
        return None;
    }
    let response0 = if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE != 0 {
        0
    } else {
        io.read32(SDHCI_RESPONSE)
    };
    if !has_data
        && short_busy_response
        && !sdio_wait_inhibit_clear_until_with(io, true, owner_deadline)
    {
        sdio_record_transfer_failure(
            SDIO_TRANSFER_FAILURE_STAGE_INHIBIT,
            io.read32(SDHCI_PRESENT_STATE),
        );
        return None;
    }
    if let Some(r5) = sdio_r5_error(cmd, response0) {
        sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_RESPONSE, r5);
        return None;
    }
    if has_data && !sdio_transfer_frame_until_with(io, frame, write, block_size, owner_deadline) {
        return None;
    }
    Some(response0)
}

#[cfg(target_os = "none")]
fn sdio_execute_descriptor_transfer_until(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    _timeout_us: u32,
    owner_deadline: &mut RuntimeDeadline,
) -> Option<u32> {
    sdio_execute_transfer_until(
        cmd,
        arg,
        flags,
        frame,
        block_size,
        block_count,
        owner_deadline,
    )
}

#[cfg(not(target_os = "none"))]
fn sdio_execute_descriptor_transfer_until(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    timeout_us: u32,
    _owner_deadline: &mut RuntimeDeadline,
) -> Option<u32> {
    sdio_execute_transfer_with_timeout(cmd, arg, flags, frame, block_size, block_count, timeout_us)
}

#[cfg(target_os = "none")]
fn cyw43_uses_sdio_bus_link() -> bool {
    let descriptor = RUNTIME_DESCRIPTOR.load();
    RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) == HOT_PATH_CYW43_WIFI
        && descriptor.has_sealed_pointer_free_bus_link(
            descriptor.task_key,
            HOT_PATH_SDIO_HOST,
            DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
        )
}

#[cfg(not(target_os = "none"))]
fn cyw43_uses_sdio_bus_link() -> bool {
    false
}

#[cfg(target_os = "none")]
fn sdio_execute_via_bus_link(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
    timeout_us: u32,
) -> Option<u32> {
    if sdio_response_flag_count(flags) != 1 {
        return None;
    }
    let has_data = flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0;
    let write = flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0;
    let sequence = cyw43_sdio_bus_link_next_sequence();
    let command = if has_data {
        let command = sdio_bus_link_descriptor_command(
            sequence,
            cmd,
            arg,
            flags,
            frame,
            block_size,
            block_count,
            timeout_us,
        )?;
        if write {
            sdio_bus_link_copy_to_owner_payload(frame, CYW43_SDIO_BUS_LINK_DATA_OFFSET)?;
        }
        command
    } else {
        sdio_bus_link_card_command_descriptor_command(sequence, cmd, arg, flags)?
    };
    let completion = match sdio_bus_link_call(command) {
        Cyw43BusLinkOutcome::Complete(completion) => completion,
        Cyw43BusLinkOutcome::Pending | Cyw43BusLinkOutcome::Failed => return None,
    };
    if completion.sequence != sequence {
        return None;
    }
    if completion.code == COMPLETION_FAULT {
        cyw43_record_last_fault_with_result(completion.detail, completion.result);
        sdio_record_transfer_failure_result(completion.result);
        return None;
    }
    if has_data && !write {
        if completion.code != COMPLETION_FRAME_READY
            || !sdio_bus_link_payload_bounds(
                completion.frame.offset as usize,
                completion.frame.len as usize,
            )
        {
            return None;
        }
        let copy_len = usize::from(completion.frame.len).min(usize::from(frame.len));
        sdio_bus_link_copy_from_owner_payload(completion.frame.offset as usize, frame, copy_len)?;
    }
    Some(completion.result)
}

fn cyw43_configure_sdio_host(target_hz: u32, flags: u16) -> bool {
    #[cfg(not(target_os = "none"))]
    {
        return sdio_apply_host_config(target_hz, flags);
    }
    #[cfg(target_os = "none")]
    {
        if !cyw43_uses_sdio_bus_link() {
            cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_BUS_LINK);
            return false;
        }
        cyw43_configure_sdio_host_via_bus_link(target_hz, flags)
    }
}

#[cfg(target_os = "none")]
fn cyw43_configure_sdio_host_via_bus_link(target_hz: u32, flags: u16) -> bool {
    let sequence = cyw43_sdio_bus_link_next_sequence();
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: DRIVER_RUNTIME_SDIO_OP_HOST_CONFIG,
        function: 0,
        response_kind: DRIVER_RUNTIME_SDIO_RESP_NONE,
        addr: target_hz,
        data_offset: 0,
        len: 0,
        block_size: 0,
        block_count: 0,
        flags,
        reserved: 0,
        timeout_us: sdio_owner_descriptor_timeout_us(0),
    };
    if !desc.valid() {
        return false;
    }
    if !sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc) {
        return false;
    }
    let command = DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags: 0,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: 0,
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    };
    match sdio_bus_link_call(command) {
        Cyw43BusLinkOutcome::Complete(completion) => {
            completion.sequence == sequence
                && completion.code == COMPLETION_PROGRESS
                && completion.result == 1
        }
        Cyw43BusLinkOutcome::Pending | Cyw43BusLinkOutcome::Failed => false,
    }
}

#[cfg(not(target_os = "none"))]
fn cyw43_configure_sdio_host_via_bus_link(_target_hz: u32, _flags: u16) -> bool {
    true
}

#[cfg(target_os = "none")]
fn cyw43_reset_sdio_generation_via_bus_link(
    requested: u32,
) -> Option<(u32, DriverTaskCompletionRecord)> {
    let sequence = cyw43_sdio_bus_link_next_sequence();
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: DRIVER_RUNTIME_SDIO_OP_GENERATION_RESET,
        function: 0,
        response_kind: DRIVER_RUNTIME_SDIO_RESP_NONE,
        addr: requested,
        data_offset: 0,
        len: 0,
        block_size: 0,
        block_count: 0,
        flags: 0,
        reserved: 0,
        timeout_us: PI4_WIFI_PWRSEQ_OWNER_WORST_CASE_US,
    };
    if !desc.valid() {
        return None;
    }
    if !sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc) {
        return None;
    }
    let command = DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags: 0,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: 0,
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    };
    match sdio_bus_link_call(command) {
        Cyw43BusLinkOutcome::Complete(completion) => Some((sequence, completion)),
        Cyw43BusLinkOutcome::Pending | Cyw43BusLinkOutcome::Failed => None,
    }
}

#[cfg(not(target_os = "none"))]
fn cyw43_reset_sdio_generation_via_bus_link(
    requested: u32,
) -> Option<(u32, DriverTaskCompletionRecord)> {
    let sequence = cyw43_sdio_bus_link_next_sequence();
    Some((
        sequence,
        DriverTaskCompletionRecord::progress(sequence, requested),
    ))
}

