#[cfg(target_os = "none")]
fn write_framebuffer_pixel(addr: usize, color: u32, bytes_per_pixel: usize) {
    match bytes_per_pixel {
        3 => {
            // SAFETY: The caller bounds-checks the framebuffer byte range.
            unsafe {
                core::ptr::write_volatile(addr as *mut u8, (color & 0xff) as u8);
                core::ptr::write_volatile((addr + 1) as *mut u8, ((color >> 8) & 0xff) as u8);
                core::ptr::write_volatile((addr + 2) as *mut u8, ((color >> 16) & 0xff) as u8);
            }
        }
        4 => {
            // SAFETY: The caller bounds-checks the framebuffer byte range and
            // the mapped framebuffer is writable device memory.
            unsafe {
                core::ptr::write_volatile(addr as *mut u32, color);
            }
        }
        _ => {}
    }
}

#[cfg(all(not(target_os = "none"), test))]
fn write_framebuffer_pixel(addr: usize, color: u32, bytes_per_pixel: usize) {
    match bytes_per_pixel {
        3 => {
            write_framebuffer_byte(addr, (color & 0xff) as u8);
            write_framebuffer_byte(addr.saturating_add(1), ((color >> 8) & 0xff) as u8);
            write_framebuffer_byte(addr.saturating_add(2), ((color >> 16) & 0xff) as u8);
        }
        4 => write_framebuffer_u32(addr, color),
        _ => {}
    }
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn write_framebuffer_pixel(_addr: usize, _color: u32, _bytes_per_pixel: usize) {}

#[cfg(all(not(target_os = "none"), test))]
fn test_framebuffer_offset(addr: usize) -> Option<usize> {
    let offset = addr.checked_sub(DRIVER_RUNTIME_FRAMEBUFFER_VADDR as usize)?;
    (offset < TEST_FRAMEBUFFER_BYTES).then_some(offset)
}

#[cfg(all(not(target_os = "none"), test))]
fn test_dma_offset(addr: usize) -> Option<usize> {
    let offset = addr.checked_sub(DRIVER_TASK_DMA_BUFFER_VADDR)?;
    (offset < XHCI_DMA_ZERO_BYTES).then_some(offset)
}

#[cfg(all(not(target_os = "none"), test))]
fn test_genet_mmio_word(offset: usize) -> Option<usize> {
    if offset % core::mem::size_of::<u32>() != 0 {
        return None;
    }
    let word = offset / core::mem::size_of::<u32>();
    (word < TEST_GENET_MMIO_WORDS).then_some(word)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeDeadline {
    Counter { start: u64, cycles: u64 },
    Iterations { remaining: usize },
}

fn runtime_timer_freq_hz() -> u64 {
    option_env!("PI4_DRIVER_RUNTIME_TIMER_CLOCK_HZ")
        .and_then(runtime_parse_u64)
        .unwrap_or(RUNTIME_TIMER_FALLBACK_HZ)
}

fn runtime_parse_u64(value: &str) -> Option<u64> {
    value.parse().ok()
}

fn runtime_legacy_spins_to_cycles(spins: usize) -> u64 {
    runtime_legacy_spins_to_cycles_at_hz(spins, runtime_timer_freq_hz())
}

fn runtime_legacy_spins_to_cycles_at_hz(spins: usize, freq_hz: u64) -> u64 {
    if spins == 0 || freq_hz == 0 {
        return 0;
    }
    let cycles = (spins as u128)
        .saturating_mul(freq_hz as u128)
        .saturating_div(RUNTIME_LEGACY_SPINS_PER_SECOND as u128);
    cycles.clamp(1, u64::MAX as u128) as u64
}

fn runtime_millis_to_cycles_at_hz(ms: u64, freq_hz: u64) -> u64 {
    if ms == 0 || freq_hz == 0 {
        return 0;
    }
    let cycles = (ms as u128)
        .saturating_mul(freq_hz as u128)
        .saturating_div(RUNTIME_MILLIS_PER_SECOND as u128);
    cycles.clamp(1, u64::MAX as u128) as u64
}

fn runtime_millis_to_cycles(ms: u64) -> u64 {
    runtime_millis_to_cycles_at_hz(ms, runtime_timer_freq_hz())
}

fn runtime_micros_to_cycles_at_hz(us: u64, freq_hz: u64) -> u64 {
    if us == 0 || freq_hz == 0 {
        return 0;
    }
    let cycles = (us as u128)
        .saturating_mul(freq_hz as u128)
        .saturating_div(RUNTIME_MICROS_PER_SECOND as u128);
    cycles.clamp(1, u64::MAX as u128) as u64
}

fn runtime_micros_to_cycles(us: u64) -> u64 {
    runtime_micros_to_cycles_at_hz(us, runtime_timer_freq_hz())
}

fn runtime_deadline_from_legacy_spins(spins: usize) -> RuntimeDeadline {
    let start = runtime_timer_counter_ticks();
    let cycles = runtime_legacy_spins_to_cycles(spins);
    let fresh = if start != 0 && cycles != 0 {
        RuntimeDeadline::Counter { start, cycles }
    } else {
        RuntimeDeadline::Iterations { remaining: spins }
    };
    #[cfg(target_os = "none")]
    {
        cyw43_foreground_retain_deadline(
            CYW43_FOREGROUND_DEADLINE_LEGACY_SPINS,
            spins as u64,
            spins,
            fresh,
        )
    }
    #[cfg(not(target_os = "none"))]
    {
        fresh
    }
}

fn runtime_deadline_from_micros_or_legacy_spins(us: u32, fallback_spins: usize) -> RuntimeDeadline {
    if us == 0 {
        return runtime_deadline_from_legacy_spins(fallback_spins);
    }
    let start = runtime_timer_counter_ticks();
    let cycles = runtime_micros_to_cycles(u64::from(us));
    let fresh = if start != 0 && cycles != 0 {
        RuntimeDeadline::Counter { start, cycles }
    } else {
        RuntimeDeadline::Iterations {
            remaining: fallback_spins,
        }
    };
    #[cfg(target_os = "none")]
    {
        cyw43_foreground_retain_deadline(
            CYW43_FOREGROUND_DEADLINE_MICROS,
            u64::from(us),
            fallback_spins,
            fresh,
        )
    }
    #[cfg(not(target_os = "none"))]
    {
        fresh
    }
}

fn runtime_deadline_from_millis_or_iterations(
    ms: u64,
    fallback_iterations: usize,
) -> RuntimeDeadline {
    let start = runtime_timer_counter_ticks();
    let cycles = runtime_millis_to_cycles(ms);
    let fresh = if start != 0 && cycles != 0 {
        RuntimeDeadline::Counter { start, cycles }
    } else {
        RuntimeDeadline::Iterations {
            remaining: fallback_iterations,
        }
    };
    #[cfg(target_os = "none")]
    {
        cyw43_foreground_retain_deadline(
            CYW43_FOREGROUND_DEADLINE_MILLIS,
            ms,
            fallback_iterations,
            fresh,
        )
    }
    #[cfg(not(target_os = "none"))]
    {
        fresh
    }
}

fn runtime_deadline_iteration_cap_reached(
    deadline: &RuntimeDeadline,
    attempts: usize,
    fallback_cap: usize,
) -> bool {
    #[cfg(target_os = "none")]
    if cyw43_foreground_action_suspended() {
        return true;
    }
    matches!(deadline, RuntimeDeadline::Iterations { .. }) && attempts >= fallback_cap
}

fn runtime_settle_micros(us: u32, fallback_iterations: usize) {
    let mut deadline = runtime_deadline_from_micros_or_legacy_spins(us, fallback_iterations);
    #[cfg(target_os = "none")]
    if cyw43_foreground_poll_retained_deadline(deadline).is_some() {
        return;
    }
    while !runtime_deadline_expired(&mut deadline) {
        runtime_poll_pause();
    }
}

fn runtime_deadline_expired(deadline: &mut RuntimeDeadline) -> bool {
    #[cfg(target_os = "none")]
    if cyw43_foreground_action_suspended() {
        return true;
    }
    match deadline {
        RuntimeDeadline::Counter { start, cycles } => {
            runtime_counter_deadline_expired(*start, *cycles, runtime_timer_counter_ticks())
        }
        RuntimeDeadline::Iterations { remaining } => {
            if *remaining == 0 {
                true
            } else {
                *remaining = (*remaining).saturating_sub(1);
                false
            }
        }
    }
}

const fn runtime_counter_deadline_expired(start: u64, cycles: u64, current: u64) -> bool {
    current.wrapping_sub(start) >= cycles
}

fn runtime_poll_pause() {
    core::hint::spin_loop();
}

#[cfg(target_os = "none")]
fn runtime_yield_current_tcb() {
    // SAFETY: Yield carries no pointer or capability payload. Every caller is
    // already executing as the admitted linked-runtime TCB, so this operation
    // only returns its current scheduling quantum to seL4.
    unsafe {
        sel4_sys::seL4_Yield();
    }
}

#[cfg(all(target_os = "none", target_arch = "aarch64"))]
fn runtime_spin(iterations: usize) {
    let mut deadline = runtime_deadline_from_legacy_spins(iterations);
    if cyw43_foreground_poll_retained_deadline(deadline).is_some() {
        return;
    }
    while !runtime_deadline_expired(&mut deadline) {
        runtime_poll_pause();
    }
}

#[cfg(not(all(target_os = "none", target_arch = "aarch64")))]
fn runtime_spin(_iterations: usize) {}

#[cfg(all(
    target_os = "none",
    target_arch = "aarch64",
    sel4_config_export_vcnt_user
))]
fn runtime_timer_counter_ticks() -> u64 {
    let value: u64;
    // SAFETY: this function only compiles when `build.rs` proved the selected
    // seL4 build exports the read-only virtual counter to EL0. The runtime
    // never writes timer-control registers.
    unsafe {
        asm!("mrs {value}, cntvct_el0", value = out(reg) value, options(nomem, nostack, preserves_flags));
    }
    value
}

#[cfg(not(all(
    target_os = "none",
    target_arch = "aarch64",
    sel4_config_export_vcnt_user
)))]
fn runtime_timer_counter_ticks() -> u64 {
    0
}

fn dma_store_barrier() {
    core::sync::atomic::compiler_fence(Ordering::Release);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: A data-memory barrier is required before MMIO doorbells publish
    // runtime-written DMA descriptors to devices.
    unsafe {
        core::arch::asm!("dmb oshst", options(nostack, preserves_flags));
    }
}

fn xhci_dma_publish_barrier() {
    core::sync::atomic::compiler_fence(Ordering::Release);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: The first live xHCI base-pointer publication on Pi 4/VL805 is a
    // device-observable handoff from runtime-filled DMA memory to MMIO state.
    // The full system barrier matches the old local-seat xHCI publish discipline
    // before DCBAAP exposes the command/event context graph to the controller.
    unsafe {
        core::arch::asm!("dsb sy", options(nostack, preserves_flags));
    }
}

fn dma_load_barrier() {
    core::sync::atomic::compiler_fence(Ordering::Acquire);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: A data-memory barrier is required before the runtime reads
    // device-written DMA payloads after descriptor completion.
    unsafe {
        core::arch::asm!("dmb oshld", options(nostack, preserves_flags));
    }
}

fn dma_cache_range(addr: usize, len: usize) -> Option<(usize, usize)> {
    if len == 0 {
        return None;
    }
    let start = addr & !(DMA_CACHE_LINE_BYTES - 1);
    let end = addr
        .saturating_add(len)
        .saturating_add(DMA_CACHE_LINE_BYTES - 1)
        & !(DMA_CACHE_LINE_BYTES - 1);
    Some((start, end.max(start.saturating_add(DMA_CACHE_LINE_BYTES))))
}

fn dma_clean_range(addr: usize, len: usize) {
    let Some((line, end)) = dma_cache_range(addr, len) else {
        return;
    };
    core::sync::atomic::compiler_fence(Ordering::Release);
    #[cfg(all(target_arch = "aarch64", target_os = "none"))]
    {
        let mut line = line;
        while line < end {
            // SAFETY: The address range comes from descriptor-validated DMA
            // buffers. Cleaning to PoC publishes CPU-written descriptors and
            // payloads before the device can fetch them.
            unsafe {
                core::arch::asm!("dc cvac, {}", in(reg) line, options(nostack, preserves_flags));
            }
            line = line.saturating_add(DMA_CACHE_LINE_BYTES);
        }
        // SAFETY: Complete all cache maintenance before the following doorbell
        // or MMIO pointer update becomes visible to the xHCI/SDIO device.
        unsafe {
            core::arch::asm!("dsb oshst", options(nostack, preserves_flags));
        }
    }
    #[cfg(not(all(target_arch = "aarch64", target_os = "none")))]
    {
        let _ = (line, end);
    }
    core::sync::atomic::compiler_fence(Ordering::Release);
}

fn dma_invalidate_range(_addr: usize, len: usize) {
    if len == 0 {
        return;
    }
    // Runtime DMA RAM is HAL-mapped uncached in the child VSpace. A barrier is
    // enough before consuming device-written bytes; data-cache invalidation on
    // this mapping can trap on Pi 4 before the progress marker is published.
    dma_load_barrier();
    core::sync::atomic::compiler_fence(Ordering::Acquire);
}

fn driver_task_shared_clean_range(_addr: usize, _len: usize) {
    // Driver-task command rings, bus-owner rings, and shared control windows are
    // HAL-mapped into linked runtimes with `seL4_ARM_Page_Uncached`. Runtime-side
    // data-cache clean is unnecessary for those pages and can trap on physical
    // Pi 4 before root sees the next progress or completion record. Device DMA
    // buffers still use `dma_clean_range`.
    core::sync::atomic::compiler_fence(Ordering::Release);
    driver_task_shared_store_barrier();
    core::sync::atomic::compiler_fence(Ordering::Release);
}

fn driver_task_shared_invalidate_range(_addr: usize, _len: usize) {
    // Driver-task command rings, bus-owner rings, and shared control windows are
    // HAL-mapped into linked runtimes with `seL4_ARM_Page_Uncached`. Runtime-side
    // data-cache invalidation is unnecessary for those pages and can trap before
    // the first command-intake poll on physical Pi 4. Device DMA buffers still
    // use `dma_invalidate_range`.
    driver_task_shared_load_barrier();
    core::sync::atomic::compiler_fence(Ordering::Acquire);
}

fn driver_task_shared_store_barrier() {
    fence(Ordering::Release);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: Shared driver-task rings are mapped normal memory across TCBs.
    // The store barrier publishes descriptor and payload writes before a
    // send-side notification or completion sequence becomes observable.
    unsafe {
        core::arch::asm!("dmb ishst", options(nostack, preserves_flags));
    }
}

fn driver_task_shared_load_barrier() {
    fence(Ordering::Acquire);
    #[cfg(target_arch = "aarch64")]
    // SAFETY: Shared driver-task rings are mapped normal memory across TCBs.
    // The load barrier pairs with the publisher before consuming descriptors,
    // payload bytes, or completion fields written by another runtime.
    unsafe {
        core::arch::asm!("dmb ishld", options(nostack, preserves_flags));
    }
}

#[cfg(target_os = "none")]
fn read_dma_byte(addr: usize) -> u8 {
    // SAFETY: Callers construct `addr` from descriptor-validated runtime DMA
    // ranges mapped into the child VSpace.
    unsafe { core::ptr::read_volatile(addr as *const u8) }
}

#[cfg(all(not(target_os = "none"), test))]
