    #[test]
    fn cyw43_fault_frame_state_round_trips_and_clears() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let frame = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: SDIO_FAULT_TELEMETRY_BYTES,
            flags: 0x0012,
        };

        cyw43_record_last_fault_with_result(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED, 0x0300_0001);
        cyw43_record_last_fault_frame(frame);

        assert_eq!(
            cyw43_take_last_fault_detail(),
            Some(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED)
        );
        assert_eq!(cyw43_take_last_fault_result(), 0x0300_0001);
        assert_eq!(cyw43_take_last_fault_frame(), frame);

        cyw43_clear_last_fault();

        assert_eq!(cyw43_take_last_fault_detail(), None);
        assert_eq!(cyw43_take_last_fault_result(), 0);
        assert_eq!(
            cyw43_take_last_fault_frame(),
            DriverFrameDescriptor::empty()
        );
    }

    fn runtime_task_key_for_hot_path(hot_path: u32) -> usize {
        match hot_path {
            HOT_PATH_SERIAL_CONSOLE => 0,
            HOT_PATH_USB_KEYBOARD => 1,
            HOT_PATH_HDMI_TEXT => 2,
            HOT_PATH_GENET_NIC => 3,
            HOT_PATH_CYW43_WIFI => 4,
            HOT_PATH_SDIO_HOST => 7,
            HOT_PATH_PCIE_ROOT => 8,
            _ => 0,
        }
    }

    fn runtime_artifact_hash_for_hot_path(hot_path: u32) -> u32 {
        pi4_driver_abi::driver_runtime_artifact_hash(match hot_path {
            HOT_PATH_SERIAL_CONSOLE => "cohesix/bin/pi4-driver-serial",
            HOT_PATH_USB_KEYBOARD => "cohesix/bin/pi4-driver-usb",
            HOT_PATH_HDMI_TEXT => "cohesix/bin/pi4-driver-hdmi",
            HOT_PATH_GENET_NIC => "cohesix/bin/pi4-driver-genet",
            HOT_PATH_CYW43_WIFI => "cohesix/bin/pi4-driver-cyw43",
            HOT_PATH_SDIO_HOST => "cohesix/bin/pi4-driver-sdio",
            HOT_PATH_PCIE_ROOT => "cohesix/bin/pi4-driver-pcie",
            _ => "cohesix/bin/pi4-driver-runtime",
        })
    }

    fn seal_descriptor_for_test(
        descriptor: DriverRuntimeInitDescriptor,
        hot_path: u32,
    ) -> DriverRuntimeInitDescriptor {
        descriptor.with_sealed_identity(
            runtime_task_key_for_hot_path(hot_path) as u32,
            runtime_artifact_hash_for_hot_path(hot_path),
        )
    }

    fn descriptor_for(hot_path: u32, role: u32) -> DriverRuntimeInitDescriptor {
        const TEST_CYW43_SDIO_SHARED_EPOCH: u32 = 0x4359_5301;
        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = hot_path;
        descriptor.role_bit = role;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        let (mmio_pages, dma_pages, shared_pages) = match hot_path {
            HOT_PATH_USB_KEYBOARD => (
                USB_REQUIRED_MMIO_PAGES,
                USB_REQUIRED_DMA_PAGES,
                USB_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_HDMI_TEXT => (
                HDMI_REQUIRED_MMIO_PAGES,
                HDMI_REQUIRED_DMA_PAGES,
                HDMI_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_GENET_NIC => (
                GENET_REQUIRED_MMIO_PAGES,
                GENET_REQUIRED_DMA_PAGES,
                GENET_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_CYW43_WIFI => (
                CYW43_REQUIRED_MMIO_PAGES,
                CYW43_REQUIRED_DMA_PAGES,
                CYW43_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_SDIO_HOST => (
                SDIO_REQUIRED_MMIO_PAGES,
                SDIO_REQUIRED_DMA_PAGES,
                SDIO_REQUIRED_SHARED_PAGES,
            ),
            HOT_PATH_PCIE_ROOT => (PCIE_REQUIRED_MMIO_PAGES, 0, PCIE_REQUIRED_SHARED_PAGES),
            _ => (1, 0, 1),
        };
        let mmio_descriptor_pages =
            mmio_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_MMIO_PAGES as u16);
        let dma_descriptor_pages =
            dma_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_DMA_PAGES as u16);
        let shared_descriptor_pages =
            shared_pages.min(pi4_driver_abi::DRIVER_RUNTIME_INIT_MAX_SHARED_PAGES as u16);
        descriptor.mmio_page_count = mmio_descriptor_pages;
        descriptor.dma_page_count = dma_descriptor_pages;
        descriptor.shared_page_count = shared_descriptor_pages;
        for index in 0..usize::from(mmio_descriptor_pages) {
            descriptor.mmio_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x1000_0000 + index * 0x1000);
        }
        for index in 0..usize::from(dma_descriptor_pages) {
            descriptor.dma_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x2000_0000 + index * 0x1000);
        }
        for index in 0..usize::from(shared_descriptor_pages) {
            descriptor.shared_pages[index] =
                pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000 + index * 0x1000);
        }
        let mut range_index = 0usize;
        if mmio_pages != 0 {
            descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_MMIO_MAPPED;
            let primary_mmio_pages = if hot_path == HOT_PATH_SDIO_HOST {
                1
            } else {
                mmio_pages
            };
            descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                match hot_path {
                    HOT_PATH_USB_KEYBOARD => DRIVER_RUNTIME_RESOURCE_TAG_USB_XHCI,
                    HOT_PATH_GENET_NIC => DRIVER_RUNTIME_RESOURCE_TAG_GENET_REGS,
                    HOT_PATH_CYW43_WIFI => DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    HOT_PATH_SDIO_HOST => DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    HOT_PATH_PCIE_ROOT => DRIVER_RUNTIME_RESOURCE_TAG_PCIE_HOST,
                    _ => pi4_driver_abi::DRIVER_RUNTIME_RESOURCE_TAG_GENERIC,
                },
                DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                0x1000_0000,
                u64::from(primary_mmio_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                primary_mmio_pages,
                0,
            );
            range_index += 1;
            if hot_path == HOT_PATH_SDIO_HOST {
                descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                        | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64 + DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    0x1000_1000,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                    1,
                    1,
                );
                range_index += 1;
            }
        }
        if dma_pages != 0 {
            descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
                if hot_path == HOT_PATH_SDIO_HOST {
                    DRIVER_RUNTIME_RESOURCE_TAG_WIFI_PWRSEQ_REQUEST
                } else {
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA
                },
                DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                0x2000_0000,
                u64::from(dma_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                dma_pages,
                0,
            );
            range_index += 1;
        }
        if shared_pages != 0 {
            descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
                DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                    | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                    | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
                if hot_path == HOT_PATH_CYW43_WIFI {
                    DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL
                } else {
                    DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL
                },
                DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                0x4000_0000,
                u64::from(shared_pages) * DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
                shared_pages,
                0,
            );
            range_index += 1;
        }
        descriptor.resource_range_count = range_index as u16;
        match hot_path {
            HOT_PATH_USB_KEYBOARD => {
                descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS;
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_PCIE_ROOT,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
                    0,
                    DRIVER_RUNTIME_RESOURCE_PAGE_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                );
            }
            HOT_PATH_CYW43_WIFI => {
                descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS;
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
                    DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
                    DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_CLIENT | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                )
                .with_notification_dpc(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_SLOT,
                    TEST_CYW43_SDIO_SHARED_EPOCH,
                );
            }
            HOT_PATH_SDIO_HOST => {
                descriptor.flags &= !DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
                descriptor.flags |=
                    DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS | DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND;
                descriptor.irq_count = 1;
                descriptor.irqs[0] = DriverRuntimeIrqDescriptor {
                    irq: DRIVER_RUNTIME_SDIO_IRQ,
                    badge: DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                    handler_slot: DRIVER_TASK_CHILD_IRQ_HANDLER_BASE_SLOT,
                    notification_slot: DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    trigger: DRIVER_RUNTIME_IRQ_TRIGGER_LEVEL,
                    flags: 0,
                    reserved: 0,
                };
                descriptor.bus_link_count = 1;
                descriptor.bus_links[0] = DriverRuntimeBusLinkDescriptor::new(
                    HOT_PATH_SDIO_HOST,
                    DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
                    DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as u32,
                    DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as u32,
                    DRIVER_RUNTIME_BUS_LINK_FLAG_OWNER | DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE,
                )
                .with_notification_dpc(
                    HOT_PATH_CYW43_WIFI,
                    DRIVER_RUNTIME_LOCAL_NOTIFICATION_SLOT,
                    DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_SLOT,
                    TEST_CYW43_SDIO_SHARED_EPOCH,
                );
            }
            _ => {}
        }
        seal_descriptor_for_test(descriptor, hot_path)
    }

    fn init_runtime_for_test(hot_path: u32, role: u32) {
        let command = DriverTaskCommandRecord {
            sequence: 1,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: hot_path,
            arg1: role,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(hot_path),
                command,
                descriptor_for(hot_path, role)
            ),
            DriverTaskCompletionRecord::progress(1, hot_path)
        );
    }

    fn stage_bytes(offset: usize, bytes: &[u8]) {
        for (index, byte) in bytes.iter().copied().enumerate() {
            write_runtime_payload_byte(offset + index, byte);
        }
    }

    fn stage_sdio_descriptor_service_command(
        sequence: u32,
        desc: DriverRuntimeSdioCommandDescriptor,
    ) -> DriverTaskCommandRecord {
        write_sdio_descriptor_for_test(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
        let transfer_bytes = if desc.block_count == 0 {
            u32::from(desc.len)
        } else {
            u32::from(desc.block_size).saturating_mul(u32::from(desc.block_count))
        };
        DriverTaskCommandRecord {
            sequence,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: 0,
            aux1: 0,
            budget: DriverTaskBudgetGrant {
                max_ops: 1,
                max_frames: 1,
                max_bytes: transfer_bytes,
            },
            frame: DriverFrameDescriptor {
                offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
                flags: 0,
            },
        }
    }

    fn reset_sdio_descriptor_seam_for_test() {
        reset_runtime_for_test();
        init_runtime_for_test(HOT_PATH_SDIO_HOST, ROLE_SDIO);
        SDIO_RUNTIME_FLAGS.store(ENGINE_STATE_INITIALIZED, Ordering::Release);
    }

    fn stage_u16(offset: usize, value: u16) {
        stage_bytes(offset, &value.to_le_bytes());
    }

    fn stage_u32(offset: usize, value: u32) {
        stage_bytes(offset, &value.to_le_bytes());
    }

    fn queue_cyw43_control_reply(
        state: &mut Cyw43RuntimeState,
        cmd: u32,
        id: u16,
        status: u32,
        response: &[u8],
    ) {
        queue_cyw43_control_reply_at(state, 0, cmd, id, status, response);
        state.rx_queue_head = 0;
        state.rx_queue_count = 1;
    }

    fn queue_cyw43_control_reply_at(
        state: &mut Cyw43RuntimeState,
        slot: usize,
        cmd: u32,
        id: u16,
        status: u32,
        response: &[u8],
    ) {
        let len = CYW43_CDC_HEADER_BYTES + response.len();
        state.rx_queue_frames[slot][..len].fill(0);
        state.rx_queue_frames[slot][0..4].copy_from_slice(&cmd.to_le_bytes());
        state.rx_queue_frames[slot][4..8].copy_from_slice(&(response.len() as u32).to_le_bytes());
        state.rx_queue_frames[slot][10..12].copy_from_slice(&id.to_le_bytes());
        state.rx_queue_frames[slot][12..16].copy_from_slice(&status.to_le_bytes());
        state.rx_queue_frames[slot][CYW43_CDC_HEADER_BYTES..len].copy_from_slice(response);
        state.rx_queue_lens[slot] = len as u16;
        state.rx_queue_flags[slot] = cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 1);
    }

    fn queue_cyw43_raw_frame_at(
        state: &mut Cyw43RuntimeState,
        slot: usize,
        flags: u16,
        payload: &[u8],
    ) {
        state.rx_queue_frames[slot][..payload.len()].copy_from_slice(payload);
        state.rx_queue_lens[slot] = payload.len() as u16;
        state.rx_queue_flags[slot] = flags;
    }

    fn stage_sdpcm_rx_header(
        offset: usize,
        packet_len: usize,
        payload_start: usize,
        channel: u8,
        credit: u8,
        glom_descriptor: bool,
    ) {
        stage_sdpcm_rx_header_with_next(
            offset,
            packet_len,
            0,
            payload_start,
            channel,
            credit,
            glom_descriptor,
        );
    }

    fn stage_sdpcm_rx_header_with_next(
        offset: usize,
        packet_len: usize,
        next_frame_len: usize,
        payload_start: usize,
        channel: u8,
        credit: u8,
        glom_descriptor: bool,
    ) {
        stage_u16(offset, packet_len as u16);
        stage_u16(offset + 2, !(packet_len as u16));
        write_runtime_payload_byte(offset + 4, 0);
        write_runtime_payload_byte(offset + 5, channel | if glom_descriptor { 0x80 } else { 0 });
        write_runtime_payload_byte(
            offset + 6,
            (next_frame_len / CYW43_SDPCM_NEXT_FRAME_LEN_UNIT_BYTES).min(u8::MAX as usize) as u8,
        );
        write_runtime_payload_byte(offset + 7, payload_start as u8);
        write_runtime_payload_byte(offset + 8, 0);
        write_runtime_payload_byte(offset + 9, credit);
        write_runtime_payload_byte(offset + 10, 0);
        write_runtime_payload_byte(offset + 11, 0);
    }

    fn stage_bdc_payload(offset: usize, packet: &[u8]) -> usize {
        write_runtime_payload_byte(offset, CYW43_BDC_VERSION << CYW43_BDC_VERSION_SHIFT);
        write_runtime_payload_byte(offset + 1, 0);
        write_runtime_payload_byte(offset + 2, 0);
        write_runtime_payload_byte(offset + 3, 0);
        stage_bytes(offset + CYW43_BDC_HEADER_BYTES, packet);
        CYW43_BDC_HEADER_BYTES + packet.len()
    }

    fn stage_sdpcm_data_subframe(offset: usize, packet: &[u8], credit: u8) -> usize {
        let packet_len = CYW43_SDPCM_HEADER_BYTES + CYW43_BDC_HEADER_BYTES + packet.len();
        stage_sdpcm_rx_header(
            offset,
            packet_len,
            CYW43_SDPCM_HEADER_BYTES,
            CYW43_SDPCM_CHANNEL_DATA,
            credit,
            false,
        );
        stage_bdc_payload(offset + CYW43_SDPCM_HEADER_BYTES, packet);
        packet_len
    }

    fn stage_cyw43_descriptor(desc: DriverRuntimeCyw43CommandDescriptor) {
        let offset = DRIVER_TASK_RING_FRAME_OFFSET;
        stage_u16(offset, desc.op);
        stage_u16(offset + 2, desc.flags);
        stage_u32(offset + 4, desc.target_addr);
        stage_u16(offset + 8, desc.payload_offset);
        stage_u16(offset + 10, desc.payload_len);
        stage_u32(offset + 12, desc.total_len);
        stage_u32(offset + 16, desc.arg0);
        stage_u32(offset + 20, desc.arg1);
        stage_u32(offset + 24, desc.reserved);
    }

    fn stage_cyw43_control_exchange_request(
        cmd: u32,
        id: u16,
        descriptor_flags: u16,
        body: &[u8],
    ) -> DriverRuntimeCyw43CommandDescriptor {
        let payload_offset = cyw43_runtime_payload_offset();
        let payload_start = usize::from(payload_offset);
        stage_u32(payload_start, cmd);
        stage_u32(payload_start + 4, body.len() as u32);
        stage_u16(payload_start + 8, 0);
        stage_u16(payload_start + 10, id);
        stage_u32(payload_start + 12, CYW43_CDC_STATUS_SUCCESS);
        stage_bytes(payload_start + CYW43_CDC_HEADER_BYTES, body);
        let payload_len = (CYW43_CDC_HEADER_BYTES + body.len()) as u16;
        let descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
            flags: descriptor_flags,
            target_addr: 0,
            payload_offset,
            payload_len,
            total_len: u32::from(payload_len),
            arg0: cmd,
            arg1: u32::from(id),
            reserved: 0,
        };
        stage_cyw43_descriptor(descriptor);
        descriptor
    }

    fn arm_cyw43_control_exchange_for_test(sdpcm_seq: u8) {
        CYW43_RUNTIME_STATE.with_mut(|state| {
            assert!(state.initialized);
            assert!(state.transport_ready);
            assert!(state.bus_link_ready);
            assert_ne!(state.dpc_shared_epoch, 0);
            state.firmware_released = true;
            state.dpc_link_ready = true;
            state.recovery_required = false;
            state.control_startup_status_drained = true;
            state.sdpcm_seq = sdpcm_seq;
            state.sdpcm_seq_max = sdpcm_seq.wrapping_add(1);
        });
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);
    }

