    fn retained_gate_test_intake(sequence: u32) -> RuntimeCommandIntake {
        RuntimeCommandIntake {
            command: DriverTaskCommandRecord {
                sequence,
                opcode: OPCODE_SERVICE,
                flags: DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY,
                arg0: HOT_PATH_SDIO_HOST,
                arg1: ROLE_SDIO,
                aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
                aux1: 0x4359_5302,
                budget: DriverTaskBudgetGrant {
                    max_ops: 1,
                    max_frames: 0,
                    max_bytes: 0,
                },
                frame: DriverFrameDescriptor::empty(),
            },
            reply_cap_available: false,
        }
    }

    #[test]
    fn production_loop_routes_idle_and_retained_commands_to_blocking_receive() {
        assert_eq!(
            runtime_command_loop_route(false, false),
            RuntimeCommandLoopRoute::WaitForIdleCommand
        );
        assert_eq!(
            runtime_command_loop_route(true, false),
            RuntimeCommandLoopRoute::RunForeground
        );
        assert_eq!(
            runtime_command_loop_route(true, true),
            RuntimeCommandLoopRoute::WaitForRetainedContinuation
        );
        // An impossible lost-intake state fails closed at the retained
        // receive rather than silently executing or entering an idle spin.
        assert_eq!(
            runtime_command_loop_route(false, true),
            RuntimeCommandLoopRoute::WaitForRetainedContinuation
        );
    }

    #[test]
    fn pending_quantum_requires_one_exact_endpoint_rendezvous() {
        let mut retained = retained_gate_test_intake(0x8000_0042);
        let mut gate = RuntimePendingCommandGate::new();

        assert!(!gate.continuation_required());
        gate.retain_after_pending();
        assert!(gate.continuation_required());
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Notification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
            ),
            RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE)
        );
        assert!(gate.continuation_required());

        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ContinueForeground
        );
        assert!(!gate.continuation_required());
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::Rejected
        );

        gate.retain_after_pending();
        assert_eq!(
            gate.route_wake(&mut retained, RuntimeWake::Notification(0)),
            RuntimePendingWakeRoute::Rejected
        );
        assert!(gate.continuation_required());
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Notification(
                    DRIVER_RUNTIME_RESERVED_ROOT_BADGE | DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                ),
            ),
            RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ContinueForeground
        );
        assert!(!gate.continuation_required());
    }

    #[test]
    fn pending_quantum_coalesced_peer_irq_arbitration_is_fair_and_durable() {
        let mut retained = retained_gate_test_intake(0x8000_0042);
        let mut gate = RuntimePendingCommandGate::new();

        assert_eq!(
            DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE | DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            "the lower peer/IRQ badge OR closure is deliberate",
        );
        assert_eq!(
            DRIVER_RUNTIME_RESERVED_ROOT_BADGE
                & (DRIVER_RUNTIME_BUS_LINK_SDIO_NOTIFICATION_BADGE
                    | DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE
                    | DRIVER_RUNTIME_SDIO_IRQ_BADGE),
            0,
            "the reserved root badge must remain disjoint from service badges",
        );
        gate.retain_after_pending();
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Notification(
                    DRIVER_RUNTIME_RESERVED_ROOT_BADGE
                        | DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
                ),
            ),
            RuntimePendingWakeRoute::ServiceNotification(
                DRIVER_RUNTIME_BUS_LINK_CYW43_NOTIFICATION_BADGE,
            )
        );
        assert!(gate.continuation_required());
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Notification(
                    DRIVER_RUNTIME_RESERVED_ROOT_BADGE | DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                ),
            ),
            RuntimePendingWakeRoute::Rejected,
            "a reasserted level source must remain deferred after one service quantum",
        );
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ContinueForeground
        );
        assert!(!gate.continuation_required());
        assert_eq!(
            gate.deferred_service_badge, DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            "the lower source coalesced with a foreground grant remains durable",
        );

        gate.retain_after_pending();
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE)
        );
        assert!(gate.continuation_required());
        assert_eq!(gate.deferred_service_badge, 0);
        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ContinueForeground,
        );
        assert!(!gate.continuation_required());
        gate.complete();
        assert_eq!(gate.take_deferred_service(), None);
    }

    #[test]
    fn continuously_coalesced_level_irq_cannot_starve_retained_foreground() {
        let mut retained = retained_gate_test_intake(0x8000_0042);
        let mut gate = RuntimePendingCommandGate::new();
        let mut foreground_quanta = 0usize;
        let mut service_quanta = 0usize;
        gate.retain_after_pending();

        for _root_grant in 0..64 {
            let service_route = gate.route_wake(
                &mut retained,
                RuntimeWake::Notification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
            );
            assert_eq!(
                service_route,
                RuntimePendingWakeRoute::ServiceNotification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
            );
            service_quanta = service_quanta.saturating_add(1);
            assert!(gate.continuation_required());

            assert_eq!(
                gate.route_wake(
                    &mut retained,
                    RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
                ),
                RuntimePendingWakeRoute::ContinueForeground,
            );
            foreground_quanta = foreground_quanta.saturating_add(1);
            assert!(!gate.continuation_required());
            // Production re-arms only after this one foreground phase returns
            // Pending to the outer command loop.
            gate.retain_after_pending();
        }

        assert_eq!(foreground_quanta, 64);
        assert_eq!(service_quanta, 64);
        assert!(gate.continuation_required());
    }

    #[test]
    fn standalone_level_irq_reassertions_stop_after_one_service_until_root_continues() {
        let mut retained = retained_gate_test_intake(0x8000_0042);
        let mut gate = RuntimePendingCommandGate::new();
        let mut service_quanta = 0usize;
        let mut rejected_reassertions = 0usize;
        gate.retain_after_pending();

        let first = gate.route_wake(
            &mut retained,
            RuntimeWake::Notification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        if let RuntimePendingWakeRoute::ServiceNotification(badge) = first {
            assert_eq!(badge, DRIVER_RUNTIME_SDIO_IRQ_BADGE);
            service_quanta = service_quanta.saturating_add(1);
        } else {
            panic!("the first standalone level IRQ must receive one service quantum");
        }

        // Both linked runtimes remain at seL4 priority 255 through bootstrap.
        // An always-ready level source must therefore be coalesced after its
        // first quantum rather than repeatedly winning before root can publish
        // the next endpoint rendezvous.
        for _ in 0..4_096 {
            assert_eq!(
                gate.route_wake(
                    &mut retained,
                    RuntimeWake::Notification(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
                ),
                RuntimePendingWakeRoute::Rejected,
            );
            rejected_reassertions = rejected_reassertions.saturating_add(1);
            assert!(gate.continuation_required());
            assert!(gate.foreground_due_after_service);
            assert_eq!(
                gate.deferred_service_badge, DRIVER_RUNTIME_SDIO_IRQ_BADGE,
                "rejected level badges remain durable rather than being lost",
            );
        }
        assert_eq!(service_quanta, 1);
        assert_eq!(rejected_reassertions, 4_096);

        assert_eq!(
            gate.route_wake(
                &mut retained,
                RuntimeWake::Command(retained_gate_test_intake(0x8000_0042)),
            ),
            RuntimePendingWakeRoute::ContinueForeground,
            "an exact endpoint rendezvous must win after the service quantum",
        );
        assert!(!gate.continuation_required());
        assert_eq!(
            gate.deferred_service_badge, DRIVER_RUNTIME_SDIO_IRQ_BADGE,
            "the source coalesced with foreground remains for a later boundary",
        );

        // Model a terminal foreground completion. Production publishes that
        // completion first, then the next loop slice drains at most this one
        // retained source quantum with scheduler handoffs on both sides.
        gate.complete();
        assert_eq!(
            gate.take_deferred_service(),
            Some(DRIVER_RUNTIME_SDIO_IRQ_BADGE),
        );
        service_quanta = service_quanta.saturating_add(1);
        assert_eq!(gate.take_deferred_service(), None);
        assert_eq!(service_quanta, 2);
    }

    #[test]
    fn pending_quantum_accepts_only_the_exact_one_way_endpoint_rendezvous() {
        let original = retained_gate_test_intake(0x8000_0042);
        let mut retained = original;
        let exact = retained_gate_test_intake(0x8000_0042);
        let mut stale_sequence = retained_gate_test_intake(0x8000_0041);
        let mut mutated_action = retained_gate_test_intake(0x8000_0042);
        mutated_action.command.aux0 = DRIVER_RUNTIME_NET_INIT_AUX;
        let mut mutated_generation = retained_gate_test_intake(0x8000_0042);
        mutated_generation.command.aux1 = 0x4359_5303;
        let mut mutated_flags = retained_gate_test_intake(0x8000_0042);
        mutated_flags.command.flags = 0;
        let mut mutated_reply = retained_gate_test_intake(0x8000_0042);
        mutated_reply.reply_cap_available = true;
        stale_sequence.command.sequence = original.command.sequence.wrapping_sub(1);

        let mut gate = RuntimePendingCommandGate::new();
        gate.retain_after_pending();
        for wake in [
            RuntimeWake::Command(stale_sequence),
            RuntimeWake::Command(mutated_action),
            RuntimeWake::Command(mutated_generation),
            RuntimeWake::Command(mutated_flags),
            RuntimeWake::Command(mutated_reply),
            RuntimeWake::None,
        ] {
            assert_eq!(
                gate.route_wake(&mut retained, wake),
                RuntimePendingWakeRoute::Rejected
            );
            assert!(gate.continuation_required());
            assert_eq!(retained, original);
        }

        assert_eq!(
            gate.route_wake(&mut retained, RuntimeWake::Command(exact)),
            RuntimePendingWakeRoute::ContinueForeground
        );
        assert!(!gate.continuation_required());
    }

