    #[test]
    fn cyw43_data_tx_waits_for_credit_by_pumping_rx() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.sdpcm_seq = 7;
        state.sdpcm_seq_max = 7;
        let inbound = [
            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x88, 0xa2, 0x9e, 0x66, 0x59, 0x10, 0x08, 0x00,
        ];
        let inbound_len = stage_sdpcm_data_subframe(CYW43_RUNTIME_RX_BUFFER_OFFSET, &inbound, 9);
        state.sdpcm_next_frame_len =
            cyw43_sdpcm_readahead_len(inbound_len).expect("inbound frame length rounds") as u16;
        let payload_offset = DRIVER_TASK_RING_FRAME_OFFSET + 512;
        let outbound = [
            0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x88, 0xa2, 0x9e, 0x66, 0x59, 0x10, 0x08, 0x00,
        ];
        stage_bytes(payload_offset, &outbound);
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);

        let frame = DriverFrameDescriptor {
            offset: payload_offset as u32,
            len: outbound.len() as u16,
            flags: 0,
        };
        assert_eq!(
            cyw43_submit_sdpcm_frame(&mut state, frame, true, false),
            CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + outbound.len()
        );
        assert_eq!(state.sdpcm_seq, 8);
        assert_eq!(state.sdpcm_seq_max, 9);
        assert_eq!(state.tx_frames, 1);
        assert_eq!(state.rx_queue_count, 1);
        assert!(test_sdio_cmd53_transfer_count(2, false) >= 1);
        assert!(test_sdio_cmd53_transfer_count(2, true) >= 1);
        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: inbound.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 9),
            })
        );
        assert_eq!(
            read_frame_prefix::<14>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: inbound.len() as u16,
                flags: 0,
            }),
            inbound
        );
    }

    #[test]
    fn cyw43_data_tx_keeps_dhcp_sized_frame_in_byte_mode() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.sdpcm_seq = 11;
        state.sdpcm_seq_max = 13;
        let payload_offset = usize::from(cyw43_runtime_shared_payload_offset());
        let mut dhcp_discover = [0u8; 300];
        dhcp_discover[..6].fill(0xff);
        dhcp_discover[6..12].copy_from_slice(&[0x88, 0xa2, 0x9e, 0x66, 0x59, 0x10]);
        dhcp_discover[12..14].copy_from_slice(&[0x08, 0x00]);
        dhcp_discover[14] = 0x45;
        dhcp_discover[14 + 9] = CYW43_IP_PROTO_UDP;
        let udp = 14 + 20;
        dhcp_discover[udp..udp + 2].copy_from_slice(&CYW43_DHCP_CLIENT_PORT.to_be_bytes());
        dhcp_discover[udp + 2..udp + 4].copy_from_slice(&CYW43_DHCP_SERVER_PORT.to_be_bytes());
        stage_bytes(payload_offset, &dhcp_discover);
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);

        let total_len = CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + dhcp_discover.len();
        assert_eq!(total_len, 330);
        assert_eq!(cyw43_data_tx_request_len_default(total_len), 332);
        let frame = DriverFrameDescriptor {
            offset: payload_offset as u32,
            len: dhcp_discover.len() as u16,
            flags: 0,
        };
        let (request_len, block_mode) = cyw43_data_tx_request_len_for_frame(frame, total_len);
        assert_eq!(request_len, cyw43_data_tx_request_len_default(total_len));
        assert!(!block_mode);
        assert_eq!(
            cyw43_submit_sdpcm_frame(&mut state, frame, true, false),
            total_len
        );
        assert_eq!(read_ring_u16(CYW43_SDPCM_TX_OFFSET), total_len as u16);
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                request_len as u16,
                0,
                request_len as u16
            ),
            1
        );
        assert_eq!(
            read_frame_prefix::<14>(DriverFrameDescriptor {
                offset: (CYW43_SDPCM_TX_OFFSET + CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES) as u32,
                len: dhcp_discover.len() as u16,
                flags: 0,
            }),
            dhcp_discover[..14]
        );
    }

    #[test]
    fn cyw43_data_tx_never_replays_ambiguous_function2_write() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.sdpcm_seq = 11;
        state.sdpcm_seq_max = 13;
        let payload_offset = DRIVER_TASK_RING_FRAME_OFFSET + 1024;
        let mut dhcp_request = [0u8; 300];
        dhcp_request[..6].fill(0xff);
        dhcp_request[6..12].copy_from_slice(&[0x88, 0xa2, 0x9e, 0x66, 0x59, 0x10]);
        dhcp_request[12..14].copy_from_slice(&CYW43_ETH_P_IPV4.to_be_bytes());
        dhcp_request[14] = 0x45;
        dhcp_request[14 + 9] = CYW43_IP_PROTO_UDP;
        let udp = CYW43_ETH_HEADER_BYTES + 20;
        dhcp_request[udp..udp + 2].copy_from_slice(&CYW43_DHCP_CLIENT_PORT.to_be_bytes());
        dhcp_request[udp + 2..udp + 4].copy_from_slice(&CYW43_DHCP_SERVER_PORT.to_be_bytes());
        stage_bytes(payload_offset, &dhcp_request);
        let total_len = CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + dhcp_request.len();
        test_sdio_transfer_fail_next(SDIO_CMD53, 2, true);
        reset_test_sdio_transfer_log();

        let frame = DriverFrameDescriptor {
            offset: payload_offset as u32,
            len: dhcp_request.len() as u16,
            flags: 0,
        };
        let (request_len, block_mode) = cyw43_data_tx_request_len_for_frame(frame, total_len);
        assert_eq!(request_len, cyw43_data_tx_request_len_default(total_len));
        assert!(!block_mode);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);

        assert_eq!(cyw43_submit_sdpcm_frame(&mut state, frame, true, false), 0);
        assert_eq!(state.sdpcm_seq, 11);
        assert_eq!(state.tx_frames, 0);
        assert!(state.sdpcm_tx_write_ambiguous);
        assert!(!state.initialized);
        assert!(!state.transport_ready);
        assert!(!state.firmware_released);
        assert_eq!(cyw43_take_last_fault_detail(), Some(FAULT_CYW43_ETH_TX));
        assert_eq!(
            cyw43_take_last_fault_result(),
            sdio_transfer_failure_result(
                SDIO_TRANSFER_FAILURE_STAGE_DATA_END,
                SDHCI_INT_ERROR | SDHCI_INT_DATA_CRC
            )
        );
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                request_len as u16,
                0,
                request_len as u16
            ),
            1
        );
        assert_eq!(
            read_frame_prefix::<14>(DriverFrameDescriptor {
                offset: (CYW43_SDPCM_TX_OFFSET + CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES) as u32,
                len: dhcp_request.len() as u16,
                flags: 0,
            }),
            dhcp_request[..14]
        );
    }

