    #[test]
    fn cyw43_control_tx_extended_header_uses_linux_byte_transport() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.sdpcm_seq = 4;
        state.sdpcm_seq_max = 5;
        // Global and per-priority XOFF gate DATA only; Linux reserves control
        // traffic so firmware ioctls can still make forward progress.
        state.flowcontrol = u8::MAX;
        state.flowcontrol_all = true;
        let payload_offset = DRIVER_TASK_RING_FRAME_OFFSET + 512;
        stage_bytes(payload_offset, b"control-payload");

        let frame = DriverFrameDescriptor {
            offset: payload_offset as u32,
            len: 15,
            flags: 0,
        };
        let unpadded_len = CYW43_SDPCM_CONTROL_TX_EXT_HEADER_BYTES + 15;
        let request_len = cyw43_control_tx_request_len(unpadded_len);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);
        assert_eq!(
            cyw43_submit_sdpcm_frame(&mut state, frame, false, true),
            unpadded_len
        );
        assert_eq!(
            read_ring_u32(CYW43_SDPCM_TX_OFFSET + CYW43_SDPCM_HWHDR_BYTES),
            (unpadded_len - CYW43_SDPCM_HWHDR_BYTES) as u32 | CYW43_SDPCM_LAST_FRAME
        );
        assert_eq!(
            read_ring_u32(CYW43_SDPCM_TX_OFFSET + CYW43_SDPCM_HWHDR_BYTES + 4),
            ((request_len - unpadded_len) as u32) << 16
        );
        let sw_header = read_ring_u32(CYW43_SDPCM_TX_OFFSET + CYW43_SDPCM_HEADER_BYTES);
        assert_eq!(sw_header & 0xff, 4);
        assert_eq!(
            (sw_header >> 8) & 0x0f,
            u32::from(CYW43_SDPCM_CHANNEL_CONTROL)
        );
        assert_eq!(
            (sw_header >> 24) as usize,
            CYW43_SDPCM_CONTROL_TX_EXT_HEADER_BYTES
        );
        assert_eq!(state.sdpcm_seq, 5);
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                request_len as u16,
                0,
                request_len as u16
            ),
            1
        );
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                CYW43_FUNCTION2_BLOCK_BYTES as u16,
                1,
                CYW43_FUNCTION2_BLOCK_BYTES as u16
            ),
            0
        );
    }

    #[test]
    fn cyw43_control_tx_plain_header_preserves_linux_payload_uses_byte_transport() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.initialized = true;
        state.transport_ready = true;
        state.firmware_released = true;
        state.sdpcm_seq = 6;
        state.sdpcm_seq_max = 7;
        let payload_offset = DRIVER_TASK_RING_FRAME_OFFSET + 512;
        let payload = [0x5a; 36];
        stage_bytes(payload_offset, &payload);

        let frame = DriverFrameDescriptor {
            offset: payload_offset as u32,
            len: payload.len() as u16,
            flags: 0,
        };
        let unpadded_len = CYW43_SDPCM_HEADER_BYTES + payload.len();
        assert_eq!(unpadded_len, 48);
        assert_eq!(cyw43_control_tx_request_len(unpadded_len), unpadded_len);
        let txglomalign_arg =
            sdio_cmd53_arg(true, 2, BACKPLANE_32BIT_FLAG, true, 0, unpadded_len as u16);
        assert_eq!(txglomalign_arg, 0xa500_0030);
        assert_eq!(txglomalign_arg & (1 << 27), 0);
        assert_ne!(txglomalign_arg & (1 << 26), 0);
        assert_eq!(txglomalign_arg & 0x1ff, unpadded_len as u32);
        assert_eq!(
            sdio_descriptor_host_block_count(
                0,
                DRIVER_RUNTIME_SDIO_FLAG_DATA
                    | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                    | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            ),
            1
        );
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);
        assert_eq!(
            cyw43_submit_sdpcm_frame(&mut state, frame, false, false),
            unpadded_len
        );
        assert_eq!(state.sdpcm_seq, 7);
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                unpadded_len as u16,
                0,
                unpadded_len as u16
            ),
            1
        );
        assert_eq!(
            test_sdio_cmd53_write_shape_count(
                2,
                BACKPLANE_32BIT_FLAG,
                CYW43_FUNCTION2_BLOCK_BYTES as u16,
                1,
                CYW43_FUNCTION2_BLOCK_BYTES as u16
            ),
            0
        );
    }

