    #[test]
    fn cyw43_control_exchange_timeout_result_encodes_rx_idle_reason() {
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(Cyw43RxIdleReason::NoRframe, 0),
            CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_NO_RFRAME
        );
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(Cyw43RxIdleReason::NoRframe, 3),
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_NONMATCHING_REPLY,
                3
            )
        );
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(
                Cyw43RxIdleReason::FirstreadEmpty {
                    probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
                    source: Cyw43RxSourceSnapshot {
                        probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
                        ..Cyw43RxSourceSnapshot::default()
                    },
                },
                0
            ),
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_EMPTY,
                CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u32
            )
        );
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(
                Cyw43RxIdleReason::FirstreadSourceAssertedEmpty {
                    probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
                    source: Cyw43RxSourceSnapshot {
                        probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
                        frame_indicated: true,
                        host_interrupt: true,
                        function2_ready: true,
                        ..Cyw43RxSourceSnapshot::default()
                    },
                },
                0
            ),
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_SOURCE_ASSERTED_EMPTY,
                CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u32
            )
        );
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(
                Cyw43RxIdleReason::FirstreadInvalidSdpcm(0x3412),
                0
            ),
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_INVALID_SDPCM,
                0x3412
            )
        );
        assert_eq!(
            cyw43_control_exchange_timeout_fault_result(
                Cyw43RxIdleReason::NextFrameReadaheadRetry(16),
                0
            ),
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_NEXT_FRAME_READAHEAD_RETRY,
                16
            )
        );
    }

