    #[test]
    fn cyw43_zero_wanted_mask_queues_service_frames_in_decode_order() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        let data = *b"data-first";
        let event = *b"event-next";
        let control = *b"control-last";
        let base = CYW43_RUNTIME_RX_BUFFER_OFFSET;

        let data_len = stage_sdpcm_data_subframe(base, &data, 1);
        assert_eq!(
            cyw43_runtime_decode_rx_frame_detailed_for(&mut state, base, data_len, 0),
            Cyw43RxDecodeResult::QueuedOrConsumed,
        );

        let event_len = CYW43_SDPCM_HEADER_BYTES + event.len();
        stage_sdpcm_rx_header(
            base,
            event_len,
            CYW43_SDPCM_HEADER_BYTES,
            CYW43_SDPCM_CHANNEL_EVENT,
            2,
            false,
        );
        stage_bytes(base + CYW43_SDPCM_HEADER_BYTES, &event);
        assert_eq!(
            cyw43_runtime_decode_rx_frame_detailed_for(&mut state, base, event_len, 0),
            Cyw43RxDecodeResult::QueuedOrConsumed,
        );

        let control_len = CYW43_SDPCM_HEADER_BYTES + control.len();
        stage_sdpcm_rx_header(
            base,
            control_len,
            CYW43_SDPCM_HEADER_BYTES,
            CYW43_SDPCM_CHANNEL_CONTROL,
            3,
            false,
        );
        stage_bytes(base + CYW43_SDPCM_HEADER_BYTES, &control);
        assert_eq!(
            cyw43_runtime_decode_rx_frame_detailed_for(&mut state, base, control_len, 0),
            Cyw43RxDecodeResult::QueuedOrConsumed,
        );
        assert_eq!(state.rx_queue_count, 3);

        for (payload, flags) in [
            (&data[..], cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1)),
            (&event[..], cyw43_frame_flags(CYW43_SDPCM_CHANNEL_EVENT, 2)),
            (
                &control[..],
                cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 3),
            ),
        ] {
            let frame = cyw43_rx_queue_pop_front(&mut state).expect("queued service frame");
            assert_eq!(frame.len, payload.len() as u16);
            assert_eq!(frame.flags, flags);
            let mut actual = [0u8; 12];
            for (index, byte) in actual.iter_mut().take(payload.len()).enumerate() {
                *byte = read_ring_byte(DRIVER_TASK_RING_FRAME_OFFSET + index);
            }
            assert_eq!(&actual[..payload.len()], payload);
        }
        assert_eq!(state.rx_queue_count, 0);
    }

    #[test]
    fn cyw43_rx_queue_removes_matching_channel_without_reordering_data() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        let data_a = *b"data-a";
        let control = *b"ctrl";
        let data_b = *b"data-b";
        let data_a_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x100;
        let control_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x200;
        let data_b_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x300;
        stage_bytes(data_a_offset, &data_a);
        stage_bytes(control_offset, &control);
        stage_bytes(data_b_offset, &data_b);

        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            data_a_offset,
            data_a.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1)
        ));
        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            control_offset,
            control.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 2)
        ));
        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            data_b_offset,
            data_b.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 3)
        ));
        let control_slot = cyw43_rx_queue_slot_at(&state, 1);

        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: control.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 2),
            })
        );
        assert_eq!(
            read_frame_prefix::<4>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: control.len() as u16,
                flags: 0,
            }),
            control
        );
        assert_eq!(state.rx_queue_lens[control_slot], 0);

        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_a.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1),
            })
        );
        assert_eq!(
            read_frame_prefix::<6>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_a.len() as u16,
                flags: 0,
            }),
            data_a
        );
        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_b.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 3),
            })
        );
        assert_eq!(
            read_frame_prefix::<6>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_b.len() as u16,
                flags: 0,
            }),
            data_b
        );
        assert_eq!(state.rx_queue_count, 0);
    }

    #[test]
    fn cyw43_rx_queue_full_sets_trace_without_overwriting_preserved_frames() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        let payload = *b"pkt!";
        let overflow_payload = *b"drop";
        let payload_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x100;
        let overflow_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x200;
        stage_bytes(payload_offset, &payload);
        stage_bytes(overflow_offset, &overflow_payload);

        for _ in 0..CYW43_RX_QUEUE_CAP {
            assert!(cyw43_rx_queue_push_from_runtime(
                &mut state,
                payload_offset,
                payload.len(),
                cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1)
            ));
        }
        assert_eq!(usize::from(state.rx_queue_count), CYW43_RX_QUEUE_CAP);
        assert_eq!(usize::from(state.rx_queue_high_water), CYW43_RX_QUEUE_CAP);
        assert_eq!(state.rx_queue_overflows, 0);

        assert!(!cyw43_rx_queue_push_from_runtime(
            &mut state,
            overflow_offset,
            overflow_payload.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 2)
        ));
        assert_ne!(
            state.rx_trace_flags & CYW43_RX_IDLE_TRACE_FLAG_QUEUE_PUSH_FAILED,
            0
        );
        assert_ne!(
            state.rx_trace_flags & CYW43_RX_IDLE_TRACE_FLAG_QUEUE_FULL,
            0
        );
        assert_eq!(usize::from(state.rx_queue_count), CYW43_RX_QUEUE_CAP);
        assert_eq!(usize::from(state.rx_queue_high_water), CYW43_RX_QUEUE_CAP);
        assert_eq!(state.rx_queue_overflows, 1);

        for _ in 0..CYW43_RX_QUEUE_CAP {
            assert_eq!(
                cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
                Some(DriverFrameDescriptor {
                    offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                    len: payload.len() as u16,
                    flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1),
                })
            );
            assert_eq!(
                read_frame_prefix::<4>(DriverFrameDescriptor {
                    offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                    len: payload.len() as u16,
                    flags: 0,
                }),
                payload
            );
        }
        assert_eq!(state.rx_queue_count, 0);
        assert_eq!(usize::from(state.rx_queue_high_water), CYW43_RX_QUEUE_CAP);
        assert_eq!(state.rx_queue_overflows, 1);
        state.reset_rx_queue_storage();
        assert_eq!(state.rx_queue_high_water, 0);
        assert_eq!(state.rx_queue_overflows, 0);
    }

    #[test]
    fn cyw43_rx_queue_full_prefers_dhcp_over_post_secure_eapol_noise() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        let eapol_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x100;
        let dhcp_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x300;
        let mut eapol = [0u8; 60];
        eapol[12..14].copy_from_slice(&CYW43_ETH_P_EAPOL.to_be_bytes());
        let mut dhcp = [0u8; 300];
        dhcp[12..14].copy_from_slice(&CYW43_ETH_P_IPV4.to_be_bytes());
        dhcp[14] = 0x45;
        dhcp[14 + 9] = CYW43_IP_PROTO_UDP;
        let udp = 14 + 20;
        dhcp[udp..udp + 2].copy_from_slice(&CYW43_DHCP_SERVER_PORT.to_be_bytes());
        dhcp[udp + 2..udp + 4].copy_from_slice(&CYW43_DHCP_CLIENT_PORT.to_be_bytes());
        stage_bytes(eapol_offset, &eapol);
        stage_bytes(dhcp_offset, &dhcp);

        for _ in 0..CYW43_RX_QUEUE_CAP {
            assert!(cyw43_rx_queue_push_from_runtime(
                &mut state,
                eapol_offset,
                eapol.len(),
                cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1)
            ));
        }
        assert_eq!(usize::from(state.rx_queue_count), CYW43_RX_QUEUE_CAP);
        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            dhcp_offset,
            dhcp.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 2)
        ));
        assert_eq!(usize::from(state.rx_queue_count), CYW43_RX_QUEUE_CAP);
        assert_eq!(state.rx_queue_overflows, 1);

        let frame = cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA)
            .expect("DHCP should preempt lower-value EAPOL backlog");
        assert_eq!(frame.len, dhcp.len() as u16);
        let mut dhcp_prefix = [0u8; 42];
        dhcp_prefix.copy_from_slice(&dhcp[..42]);
        assert_eq!(read_frame_prefix::<42>(frame), dhcp_prefix);
    }

