    #[test]
    fn cyw43_function2_ready_timeout_does_not_toggle_ioex_in_place() {
        let _guard = test_guard();
        reset_runtime_for_test();
        reset_test_sdio_transfer_log();
        test_sdio_cmd52_read_ioex_response(SDIO_FUNC_ENABLE_1);
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_1);

        assert_eq!(
            cyw43_enable_post_release_function2_poll(),
            Err(FAULT_CYW43_POST_RELEASE_F2_READY)
        );
        assert_eq!(
            test_sdio_transfer_count(|record| {
                record.cmd == SDIO_CMD52
                    && record.arg
                        == sdio_cmd52_arg(
                            true,
                            0,
                            SDIO_CCCR_IOEX,
                            SDIO_FUNC_ENABLE_1 | SDIO_FUNC_ENABLE_2,
                        )
            }),
            1
        );
        assert!(!test_sdio_cmd52_write_seen(
            0,
            SDIO_CCCR_IOEX,
            SDIO_FUNC_ENABLE_1
        ));
        // The bounded transfer log fills before the 3,000-poll deadline; the
        // retained fault detail carries the exact completed poll count.
        assert!(
            test_sdio_cmd52_read_count(0, SDIO_CCCR_IORX) > CYW43_SDIO_F2_READY_IORX_READ_RETRIES
        );
        assert_eq!(
            cyw43_take_last_fault_detail(),
            Some(FAULT_CYW43_POST_RELEASE_F2_READY)
        );
        assert_eq!(
            cyw43_take_last_fault_result(),
            cyw43_f2_ready_fault_detail(
                CYW43_F2_READY_DETAIL_REASON_TIMEOUT,
                0,
                CYW43_SDIO_F2_READY_FALLBACK_POLLS,
                SDIO_FUNC_ENABLE_1 | SDIO_FUNC_ENABLE_2,
                SDIO_FUNC_READY_1,
            )
        );
    }

    #[test]
    fn sdio_runtime_without_mmio_rejects_engine_init_before_register_access() {
        let _guard = test_guard();
        reset_runtime_for_test();

        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = HOT_PATH_SDIO_HOST;
        descriptor.role_bit = ROLE_SDIO;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        descriptor.shared_page_count = 1;
        descriptor.shared_pages[0] = pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000);
        descriptor.resource_range_count = 1;
        descriptor.resource_ranges[0] = DriverRuntimeResourceRangeDescriptor::new(
            DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
            DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
            DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
            DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
            0x4000_0000,
            DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
            1,
            0,
        );
        let descriptor = seal_descriptor_for_test(descriptor, HOT_PATH_SDIO_HOST);
        let runtime_init = DriverTaskCommandRecord {
            sequence: 70,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(HOT_PATH_SDIO_HOST),
                runtime_init,
                descriptor
            ),
            DriverTaskCompletionRecord::progress(70, HOT_PATH_SDIO_HOST)
        );

        let engine_init = DriverTaskCommandRecord {
            sequence: 71,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, engine_init),
            DriverTaskCompletionRecord::fault(
                71,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16
            )
        );
    }

    #[test]
    fn sdio_descriptor_helpers_encode_cmd52_and_cmd53_arguments() {
        assert_eq!(
            sdio_cmd52_arg(false, 1, 0x1234, 0),
            (1 << 28) | (0x1234 << 9)
        );
        assert_eq!(
            sdio_cmd52_arg(true, 2, 0x20, 0x5a),
            (1 << 31) | (2 << 28) | (0x20 << 9) | 0x5a
        );
        assert_eq!(
            sdio_cmd53_arg(true, 2, 0x1_0000, true, 4, 0),
            (1 << 31) | (2 << 28) | (1 << 27) | (1 << 26) | (0x1_0000 << 9) | 4
        );
        assert_eq!(
            sdio_descriptor_response_flags(DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY),
            DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
        );
    }

    #[test]
    fn sdio_runtime_int_ack_preserves_other_phase_and_card_interrupt() {
        let upper_error = 1 << 24;
        let status = SDHCI_INT_RESPONSE
            | SDHCI_INT_DATA_AVAIL
            | SDHCI_INT_DATA_END
            | SDHCI_INT_CARD_INT
            | SDHCI_INT_ERROR
            | upper_error;
        assert_eq!(
            sdhci_wait_int_ack_bits(SDHCI_INT_RESPONSE, status),
            SDHCI_INT_RESPONSE | SDHCI_INT_ERROR | upper_error
        );
        assert_eq!(
            sdhci_wait_int_ack_bits(SDHCI_INT_DATA_AVAIL, status),
            SDHCI_INT_DATA_AVAIL | SDHCI_INT_ERROR | upper_error
        );
        assert_eq!(
            sdhci_wait_int_ack_bits(SDHCI_INT_DATA_FINISH_MASK, status),
            SDHCI_INT_DATA_END | SDHCI_INT_ERROR | upper_error
        );
        assert_eq!(SDHCI_INT_ALL_ERROR_MASK, 0xffff_8000);
        assert_eq!(SDHCI_INT_COMMAND_DATA_CLEAR_MASK & SDHCI_INT_CARD_INT, 0);
        assert_ne!(SDHCI_INT_COMMAND_DATA_CLEAR_MASK & upper_error, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_DATA_END, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_DATA_CRC, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_ERROR, 0);
    }

    #[test]
    fn cyw43_backplane_upload_uses_one_linux_normal_lane() {
        assert_eq!(
            CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES / 2
        );
        assert!(CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES < CYW43_FIRMWARE_STAGE_BYTES);
        assert_eq!(
            CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES % SDIO_FUNCTION1_BLOCK_SIZE as usize,
            0
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, 2048),
            (2048, SDIO_FUNCTION1_BLOCK_SIZE, 32)
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, CYW43_FIRMWARE_STAGE_BYTES),
            (
                CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
                SDIO_FUNCTION1_BLOCK_SIZE,
                (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, 32 * 1024),
            (
                CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
                SDIO_FUNCTION1_BLOCK_SIZE,
                (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, SDIO_FUNCTION1_BLOCK_SIZE as usize),
            (
                SDIO_FUNCTION1_BLOCK_SIZE as usize,
                SDIO_FUNCTION1_BLOCK_SIZE,
                0
            )
        );
        assert_eq!(cyw43_backplane_write_chunk_shape(false, 4), (4, 4, 0));
        assert_eq!(
            cyw43_backplane_write_chunk_shape(true, 2048),
            (
                SDIO_FUNCTION2_BLOCK_SIZE as usize,
                SDIO_FUNCTION2_BLOCK_SIZE,
                1
            )
        );
        assert_eq!(cyw43_backplane_write_chunk_shape(true, 4), (4, 4, 1));
        assert_eq!(cyw43_sdio_operating_clock_hz(true), 50_000_000);
        assert_eq!(cyw43_sdio_operating_clock_hz(false), 25_000_000);
    }

    #[test]
    fn cyw43_firmware_upload_uses_byte_mode_at_backplane_window_edge() {
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES
        ));
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES * 2
        ));
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            true,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES
        ));
        assert!(cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            32
        ));
        let arg = sdio_cmd53_arg(
            true,
            1,
            CYW43_RAM_BASE_4345,
            cyw43_backplane_cmd53_increment(),
            0,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
        );
        assert_eq!(arg & 0x1ff, 0);
        assert_ne!(arg & (1 << 26), 0);
        let block_arg = sdio_cmd53_arg(
            true,
            1,
            CYW43_RAM_BASE_4345,
            cyw43_backplane_cmd53_increment(),
            1,
            SDIO_FUNCTION1_BLOCK_SIZE,
        );
        assert_ne!(block_arg & (1 << 26), 0);
    }

    #[test]
    fn cyw43_linked_pre_release_owner_upload_has_no_alternate_lane() {
        let upload_block_count =
            (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16;
        let block_arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            upload_block_count,
            SDIO_FUNCTION1_BLOCK_SIZE,
        );
        assert_ne!(block_arg & (1 << 27), 0);
        assert_ne!(block_arg & (1 << 26), 0);
        assert_eq!(block_arg & 0x1ff, u32::from(upload_block_count));
        let transfer = sdio_transfer_mode(true, upload_block_count);
        assert_ne!(transfer & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(transfer & SDHCI_TRNS_MULTI, 0);
        assert_eq!(
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT, SDHCI_INT_ERROR),
            (SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT << 24) | SDHCI_INT_ERROR
        );
    }

    #[test]
    fn cyw43_linked_pio_firmware_cursor_advances_by_linux_multiblock_commands() {
        let expected = CYW43_FIRMWARE_STAGE_BYTES;
        let mut remaining = expected;
        let mut advanced = 0usize;
        let mut commands = 0usize;
        while remaining != 0 {
            let (chunk_len, block_size, block_count) =
                cyw43_backplane_write_chunk_shape(false, remaining);
            assert_eq!(block_size, SDIO_FUNCTION1_BLOCK_SIZE);
            assert_eq!(chunk_len, CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES);
            assert_eq!(
                block_count,
                (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16
            );
            advanced += chunk_len;
            remaining -= chunk_len;
            commands += 1;
        }
        assert_eq!(commands, 2);
        assert_eq!(advanced, expected);
    }

    #[test]
    fn cyw43_function2_fifo_shape_matches_card_and_host_mode() {
        assert_eq!(
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
            CYW43_FUNCTION2_BLOCK_BYTES
        );
        assert_eq!(
            cyw43_data_tx_request_len_default(CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + 14),
            44
        );
        let tiny_frame = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: 14,
            flags: 0,
        };
        assert_eq!(
            cyw43_data_tx_request_len_for_frame(
                tiny_frame,
                CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + 14
            )
            .0,
            CYW43_DATA_TX_MIN_FUNCTION2_BYTES
        );
        assert_eq!(
            cyw43_data_tx_request_len_default(CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + 300),
            332
        );
        assert_eq!(
            cyw43_data_tx_request_len_for_frame(
                DriverFrameDescriptor {
                    offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                    len: 300,
                    flags: 0,
                },
                CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + 300
            ),
            (
                cyw43_data_tx_request_len_default(CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES + 300),
                false
            )
        );
        assert_eq!(
            cyw43_control_tx_request_len(CYW43_SDPCM_CONTROL_TX_EXT_HEADER_BYTES + 37),
            align4(CYW43_SDPCM_CONTROL_TX_EXT_HEADER_BYTES + 37)
        );
        assert_eq!(
            cyw43_control_tx_request_len(CYW43_SDPCM_HEADER_BYTES + 36),
            CYW43_SDPCM_HEADER_BYTES + 36
        );
        assert_eq!(
            cyw43_function2_cmd53_shape(CYW43_SDPCM_HEADER_BYTES + 36),
            ((CYW43_SDPCM_HEADER_BYTES + 36) as u16, 0)
        );
        assert_eq!(
            cyw43_data_tx_request_len_default(SDIO_CMD53_BYTE_MODE_MAX),
            SDIO_CMD53_BYTE_MODE_MAX
        );
        assert_eq!(
            cyw43_data_tx_request_len_default(SDIO_CMD53_BYTE_MODE_MAX + 1),
            CYW43_FUNCTION2_BLOCK_BYTES * 2
        );
        let (probe_byte_size, probe_byte_count) =
            cyw43_function2_cmd53_shape(CYW43_CONTROL_RX_BLOCK_PROBE_BYTES);
        assert_eq!(probe_byte_size, SDIO_CMD53_BYTE_MODE_MAX as u16);
        assert_eq!(probe_byte_count, 0);
        assert_eq!(
            cyw43_function2_block_probe_cmd53_shape(),
            (probe_byte_size, probe_byte_count)
        );
        let probe_arg = sdio_cmd53_arg(
            false,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            probe_byte_count,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
        );
        assert_eq!(probe_arg & (1 << 27), 0);
        assert_eq!(probe_arg & 0x1ff, 0);

        let (block_size, block_count) =
            cyw43_function2_cmd53_shape(CYW43_FUNCTION2_BLOCK_BYTES * 3);
        assert_eq!(block_size, CYW43_FUNCTION2_BLOCK_BYTES as u16);
        assert_eq!(block_count, 3);
        let block_arg = sdio_cmd53_arg(
            true,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            (CYW43_FUNCTION2_BLOCK_BYTES * 3) as u16,
        );
        assert_ne!(block_arg & (1 << 27), 0);
        assert_eq!(block_arg & 0x1ff, 3);

        let (byte_size, byte_count) = cyw43_function2_cmd53_shape(96);
        assert_eq!(byte_size, 96);
        assert_eq!(byte_count, 0);
        let byte_arg = sdio_cmd53_arg(true, 2, BACKPLANE_32BIT_FLAG, false, byte_count, 96);
        assert_eq!(byte_arg & (1 << 27), 0);
        assert_eq!(byte_arg & 0x1ff, 96);

        assert_eq!(
            cyw43_function2_data_tx_cmd53_shape(CYW43_FUNCTION2_BLOCK_BYTES, true),
            (CYW43_FUNCTION2_BLOCK_BYTES as u16, 1)
        );
        assert_eq!(
            cyw43_function2_data_tx_cmd53_shape(CYW43_FUNCTION2_BLOCK_BYTES, false),
            (CYW43_FUNCTION2_BLOCK_BYTES as u16, 0)
        );
    }

    #[test]
    fn cyw43_function2_fifo_reprimes_chipcommon_window_before_each_cmd53() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.backplane_window = CYW43_CHIPCOMMON_BASE & BACKPLANE_WINDOW_MASK;
        state.backplane_window_valid = true;
        let frame = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
            flags: 0,
        };
        let (block_size, block_count) =
            cyw43_function2_cmd53_shape(CYW43_CONTROL_RX_FIRSTREAD_BYTES);

        assert!(cyw43_function2_execute_transfer(
            &mut state,
            false,
            frame,
            block_size,
            block_count
        ));
        test_sdio_cmd52_read_iorx_response(SDIO_FUNC_READY_2);
        assert!(cyw43_function2_execute_transfer(
            &mut state,
            true,
            frame,
            block_size,
            block_count
        ));

        let (low, mid, high) = cyw43_backplane_window_register_bytes(CYW43_CHIPCOMMON_BASE);
        let low_write = |record: TestSdioTransferRecord| {
            record.cmd == SDIO_CMD52
                && record.arg == sdio_cmd52_arg(true, 1, SBSDIO_FUNC1_SBADDRLOW, low)
        };
        let mid_write = |record: TestSdioTransferRecord| {
            record.cmd == SDIO_CMD52
                && record.arg == sdio_cmd52_arg(true, 1, SBSDIO_FUNC1_SBADDRMID, mid)
        };
        let high_write = |record: TestSdioTransferRecord| {
            record.cmd == SDIO_CMD52
                && record.arg == sdio_cmd52_arg(true, 1, SBSDIO_FUNC1_SBADDRHIGH, high)
        };
        let function2_fifo = |record: TestSdioTransferRecord| {
            record.cmd == SDIO_CMD53
                && sdio_cmd53_arg_function(record.arg) == 2
                && sdio_cmd53_arg_addr(record.arg) == BACKPLANE_32BIT_FLAG
        };
        let first_low = test_sdio_transfer_index(low_write, 0).expect("first low window write");
        let first_mid = test_sdio_transfer_index(mid_write, 0).expect("first mid window write");
        let first_high = test_sdio_transfer_index(high_write, 0).expect("first high window write");
        let first_fifo = test_sdio_transfer_index(function2_fifo, 0).expect("first FIFO CMD53");
        let second_low = test_sdio_transfer_index(low_write, 1).expect("second low window write");
        let second_mid = test_sdio_transfer_index(mid_write, 1).expect("second mid window write");
        let second_high =
            test_sdio_transfer_index(high_write, 1).expect("second high window write");
        let second_fifo = test_sdio_transfer_index(function2_fifo, 1).expect("second FIFO CMD53");

        assert!(first_low < first_mid);
        assert!(first_mid < first_high);
        assert!(first_high < first_fifo);
        assert!(first_fifo < second_low);
        assert!(second_low < second_mid);
        assert!(second_mid < second_high);
        assert!(second_high < second_fifo);
        assert_eq!(
            state.backplane_window,
            CYW43_CHIPCOMMON_BASE & BACKPLANE_WINDOW_MASK
        );
        assert!(state.backplane_window_valid);
    }

