    #[test]
    fn cyw43_runtime_lifecycle_reset_clears_asserted_empty_episode_only() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.rx_irq_preserve_count = 7;
        state.rx_irq_source_asserted_empty_episode_preserves = 2;
        state.rx_irq_source_asserted_empty_rearms = 5;

        state.reset_firmware_upload_state();
        assert_eq!(state.rx_irq_preserve_count, 7);
        assert_eq!(state.rx_irq_source_asserted_empty_episode_preserves, 0);
        assert_eq!(state.rx_irq_source_asserted_empty_rearms, 5);

        state.rx_irq_source_asserted_empty_episode_preserves = 2;
        state.reset();
        assert_eq!(state.rx_irq_preserve_count, 7);
        assert_eq!(state.rx_irq_source_asserted_empty_episode_preserves, 0);
        assert_eq!(state.rx_irq_source_asserted_empty_rearms, 5);
    }

    #[test]
    fn sdio_descriptor_retry_requires_not_issued_function1_cmd53() {
        let mut desc = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
            function: 1,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
            addr: CYW43_RAM_BASE_4345,
            data_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
            len: SDIO_CMD53_BYTE_MODE_MAX as u16,
            block_size: 0,
            block_count: 0,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT,
            reserved: 0,
            timeout_us: 100_000,
        };
        assert!(sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        assert!(sdio_descriptor_retry_after_containment(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_INHIBIT, SDHCI_DATA_INHIBIT,),
        ));
        assert!(!sdio_descriptor_retry_after_containment(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_DATA_END, SDHCI_INT_ERROR),
        ));
        assert!(!sdio_descriptor_retry_after_containment(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            sdio_transfer_failure_result(
                SDIO_TRANSFER_FAILURE_STAGE_POST_ISSUE_QUIESCE,
                SDHCI_DATA_INHIBIT,
            ),
        ));
        desc.function = 2;
        desc.addr = BACKPLANE_32BIT_FLAG;
        desc.flags = 0;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.flags = DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.addr = CYW43_RAM_BASE_4345;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 0;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 2;
        desc.op = DRIVER_RUNTIME_SDIO_OP_CMD53_READ;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 1;
        assert!(sdio_descriptor_retry_after_containment(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_INHIBIT, SDHCI_DATA_INHIBIT,),
        ));
        assert!(!sdio_descriptor_retry_after_containment(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_COMMAND, SDHCI_INT_ERROR),
        ));
    }

    #[test]
    fn sdio_fault_telemetry_frame_encodes_owner_command_snapshot() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            0,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
        );
        let transfer_mode = sdio_transfer_mode_from_flags(
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE,
            1,
        );
        let failure =
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_DATA_END, SDHCI_INT_ERROR);
        let payload = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_PAGE_BYTES as u32,
            len: SDIO_CMD53_BYTE_MODE_MAX as u16,
            flags: 0,
        };
        write_runtime_payload_byte(payload.offset as usize, 0x11);
        write_runtime_payload_byte(
            payload.offset as usize + usize::from(payload.len).saturating_sub(1),
            0x22,
        );

        let frame = sdio_write_fault_telemetry_frame(
            SDIO_CMD53,
            arg,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
            1,
            transfer_mode,
            failure,
            payload,
        );

        assert_eq!(frame.offset, SDIO_FAULT_TELEMETRY_FRAME_OFFSET as u32);
        assert_eq!(frame.len, SDIO_FAULT_TELEMETRY_BYTES);
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET),
            SDIO_FAULT_TELEMETRY_MAGIC
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + 4),
            SDIO_FAULT_TELEMETRY_VERSION
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_ARG_OFFSET),
            arg
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_FAILURE_OFFSET),
            failure
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_LEN_BLOCK_OFFSET
            ),
            u32::from(SDIO_CMD53_BYTE_MODE_MAX as u16)
                | (u32::from(SDIO_CMD53_BYTE_MODE_MAX as u16) << 16)
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_COUNT_MODE_OFFSET
            ),
            u32::from(1u16) | (u32::from(transfer_mode) << 16)
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_PAYLOAD_EDGE_OFFSET
            ),
            0x0033_2211
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_PAYLOAD_SUM_OFFSET
            ),
            0x33
        );
    }

    #[test]
    fn sdio_pio_readiness_masks_stay_in_their_register_namespaces() {
        assert_eq!(sdhci_present_buffer_ready_mask(true), SDHCI_SPACE_AVAILABLE);
        assert_eq!(sdhci_present_buffer_ready_mask(false), SDHCI_DATA_AVAILABLE);
        assert_eq!(
            sdhci_interrupt_buffer_ready_mask(true),
            SDHCI_INT_SPACE_AVAIL
        );
        assert_eq!(
            sdhci_interrupt_buffer_ready_mask(false),
            SDHCI_INT_DATA_AVAIL
        );
        assert_eq!(
            sdhci_present_buffer_ready_mask(true) & sdhci_interrupt_buffer_ready_mask(true),
            0
        );
        assert_eq!(
            sdhci_present_buffer_ready_mask(false) & sdhci_interrupt_buffer_ready_mask(false),
            0
        );
    }

    #[test]
    fn sdio_descriptor_cmd53_byte_mode_keeps_descriptor_zero_and_host_one_block() {
        let flags = DRIVER_RUNTIME_SDIO_FLAG_DATA
            | DRIVER_RUNTIME_SDIO_FLAG_WRITE
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT;
        let arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            0,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
        );
        assert_eq!(arg, 0x9500_0000);

        let host_block_count = sdio_descriptor_host_block_count(0, flags);
        assert_eq!(host_block_count, 1);
        let transfer = sdio_transfer_mode_from_flags(flags, host_block_count);
        assert_ne!(transfer & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(transfer & SDHCI_TRNS_MULTI, 0);
        assert_eq!(transfer & SDHCI_TRNS_READ, 0);

        let read_transfer = sdio_transfer_mode_from_flags(
            DRIVER_RUNTIME_SDIO_FLAG_DATA,
            sdio_descriptor_host_block_count(0, DRIVER_RUNTIME_SDIO_FLAG_DATA),
        );
        assert_ne!(read_transfer & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(read_transfer & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn sdio_r5_rejects_every_linux_error_bit_and_ignores_only_current_state() {
        assert_eq!(SDIO_R5_COM_CRC_ERROR, 0x8000);
        assert_eq!(SDIO_R5_ILLEGAL_COMMAND, 0x4000);
        assert_eq!(SDIO_R5_ERROR, 0x0800);
        assert_eq!(SDIO_R5_FUNCTION_NUMBER, 0x0200);
        assert_eq!(SDIO_R5_OUT_OF_RANGE, 0x0100);
        assert_eq!(SDIO_R5_STATUS_MASK, 0xcb00);
        assert_eq!(sdio_r5_error(SDIO_CMD53, 0), None);
        assert_eq!(
            sdio_r5_error(SDIO_CMD53, SDIO_R5_ERROR),
            Some(SDIO_R5_ERROR)
        );
        assert_eq!(sdio_r5_error(SDIO_CMD53, 0x1800), Some(SDIO_R5_ERROR));
        assert_eq!(
            sdio_r5_error(SDIO_CMD53, 0x1100),
            Some(SDIO_R5_OUT_OF_RANGE)
        );
        for current_state in [0x1000, 0x2000, 0x3000] {
            assert_eq!(sdio_r5_error(SDIO_CMD52, current_state), None);
            assert_eq!(sdio_r5_error(SDIO_CMD53, current_state), None);
        }
        for error in [
            SDIO_R5_COM_CRC_ERROR,
            SDIO_R5_ILLEGAL_COMMAND,
            SDIO_R5_ERROR,
            SDIO_R5_FUNCTION_NUMBER,
            SDIO_R5_OUT_OF_RANGE,
            SDIO_R5_STATUS_MASK,
        ] {
            assert_eq!(sdio_r5_error(SDIO_CMD52, error), Some(error));
            assert_eq!(sdio_r5_error(SDIO_CMD53, error), Some(error));
        }
        assert_eq!(sdio_r5_error(SDIO_CMD5, 0xcb00), None);
        assert!(sdio_r5_response_flags_valid(
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT
        ));
        assert!(!sdio_r5_response_flags_valid(
            SDIO_CMD52,
            DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE
        ));
        assert_eq!(
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_RESPONSE, 0x0800),
            (SDIO_TRANSFER_FAILURE_STAGE_RESPONSE << 24) | 0x0800
        );
    }

