    #[test]
    fn usb_keyboard_arms_known_good_interrupt_queue_depth() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 2;
        state.keyboard_endpoint_id = 3;

        assert_eq!(USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH, 128);
        assert_eq!(USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH, 1);
        assert_eq!(USB_KEYBOARD_STEADY_INTERRUPT_QUEUE_DEPTH, 32);
        assert!(xhci_arm_keyboard_interrupt_queue(&mut state, &descriptor));
        assert_eq!(
            usize::from(state.keyboard_reports_queued),
            USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH
        );
        for slot in 0..USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH {
            assert!(state.keyboard_report_in_use[slot]);
            assert_eq!(state.keyboard_report_trb_indices[slot], slot as u16);
            assert_eq!(
                xhci_keyboard_report_buffer_offset(slot),
                XHCI_DMA_REPORT_BUFFER_OFFSET + slot * USB_KEYBOARD_REPORT_BUFFER_BYTES
            );
        }

        assert!(xhci_arm_keyboard_interrupt_queue(&mut state, &descriptor));
        assert_eq!(
            usize::from(state.keyboard_reports_queued),
            USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH
        );

        let mut steady_state = UsbRuntimeState::new();
        steady_state.db_offset = 0x1000;
        steady_state.keyboard_slot = 2;
        steady_state.keyboard_endpoint_id = 3;
        steady_state.keyboard_transfer_events = 1;
        steady_state.keyboard_valid_report_events = 1;
        assert!(xhci_arm_keyboard_interrupt_queue(
            &mut steady_state,
            &descriptor
        ));
        assert_eq!(
            usize::from(steady_state.keyboard_reports_queued),
            USB_KEYBOARD_STEADY_INTERRUPT_QUEUE_DEPTH
        );

        steady_state.keyboard_last_report_status =
            DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_RECOVERY_SUCCESS;
        assert_eq!(
            xhci_keyboard_interrupt_queue_target(&steady_state),
            USB_KEYBOARD_STEADY_INTERRUPT_QUEUE_DEPTH
        );
    }

    #[test]
    fn usb_keyboard_interrupt_trbs_request_bounded_endpoint_packet_len() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 2;
        state.keyboard_endpoint_id = 3;
        state.keyboard_ep_max_packet = 9;

        assert_eq!(usb_keyboard_report_request_len(&state), 9);
        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
        assert_eq!(state.kbd_enqueue, 1);
        assert_eq!(state.keyboard_reports_queued, 1);

        state.keyboard_ep_max_packet = 512;
        assert_eq!(
            usb_keyboard_report_request_len(&state),
            USB_KEYBOARD_REPORT_BUFFER_BYTES
        );

        state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT;
        assert_eq!(
            usb_keyboard_report_request_len(&state),
            USB_BOOT_REPORT_BYTES
        );

        state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_PROTOCOL_NONE;
        state.keyboard_ep_max_packet = 9;
        assert_eq!(usb_keyboard_report_request_len(&state), 9);
    }

    #[test]
    fn usb_keyboard_interrupt_queue_refuses_owned_trb_index() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 2;
        state.keyboard_endpoint_id = 3;

        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
        assert_eq!(state.kbd_enqueue, 1);
        state.kbd_enqueue = 0;

        assert!(!xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
        assert_eq!(state.keyboard_reports_queued, 1);
        assert!(state.keyboard_report_in_use[0]);
        assert_eq!(state.keyboard_report_trb_indices[0], 0);
        assert_eq!(state.kbd_enqueue, 0);
    }

    #[test]
    fn usb_keyboard_hard_recovery_command_trbs_encode_slot_endpoint_and_dequeue() {
        let slot = 4;
        let endpoint_id = 3;

        assert_eq!(XHCI_TRB_TYPE_RESET_ENDPOINT, 14);
        assert_eq!(XHCI_TRB_TYPE_STOP_ENDPOINT, 15);
        assert_eq!(XHCI_TRB_TYPE_SET_TR_DEQUEUE_POINTER, 16);

        assert_eq!(
            xhci_stop_endpoint_command(slot, endpoint_id),
            XhciTrb {
                parameter: 0,
                status: 0,
                control: (XHCI_TRB_TYPE_STOP_ENDPOINT << 10)
                    | (u32::from(endpoint_id) << 16)
                    | (u32::from(slot) << 24)
            }
        );
        assert_eq!(
            xhci_reset_endpoint_command(slot, endpoint_id),
            XhciTrb {
                parameter: 0,
                status: 0,
                control: (XHCI_TRB_TYPE_RESET_ENDPOINT << 10)
                    | (u32::from(endpoint_id) << 16)
                    | (u32::from(slot) << 24)
            }
        );
        assert_eq!(
            xhci_set_tr_dequeue_pointer_command(slot, endpoint_id, 0x2000_0010, false),
            XhciTrb {
                parameter: 0x2000_0010,
                status: 0,
                control: (XHCI_TRB_TYPE_SET_TR_DEQUEUE_POINTER << 10)
                    | (u32::from(endpoint_id) << 16)
                    | (u32::from(slot) << 24)
            }
        );
        assert_eq!(
            xhci_set_tr_dequeue_pointer_command(slot, endpoint_id, 0x2000_0010, true).parameter,
            0x2000_0011
        );
    }

    #[test]
    fn usb_keyboard_hard_recovery_resets_ring_without_clearing_first_report_proof() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let dma_range = runtime_resource_range(
            &descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )
        .expect("USB descriptor has DMA arena");
        let kbd_ring = xhci_dma_bus_addr(&descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET).unwrap();
        let kbd_base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
        let mut state = UsbRuntimeState::new();
        state.kbd_enqueue = 12;
        state.kbd_cycle = false;
        state.keyboard_reports_queued = 2;
        state.keyboard_report_in_use[0] = true;
        state.keyboard_report_in_use[1] = true;
        state.keyboard_report_trb_indices[0] = 10;
        state.keyboard_report_trb_indices[1] = 11;
        state.keyboard_preserved_event_count = 1;
        state.keyboard_preserved_event_parameters[0] = 0xdead_beef;
        state.keyboard_byte_queue[0] = b'x';
        state.keyboard_byte_queue_len = 1;
        state.keyboard_transfer_events = 9;
        state.keyboard_valid_report_events = 3;
        state.last_keys[0] = 0x04;
        state.caps_lock_on = true;

        assert_eq!(
            xhci_reset_keyboard_transfer_ring(&mut state, &descriptor),
            Some(kbd_ring)
        );

        assert_eq!(state.kbd_enqueue, 0);
        assert!(state.kbd_cycle);
        assert_eq!(state.keyboard_reports_queued, 0);
        assert!(!state.keyboard_report_in_use[0]);
        assert_eq!(state.keyboard_report_trb_indices[0], 0);
        assert_eq!(state.keyboard_preserved_event_count, 0);
        assert_eq!(state.keyboard_byte_queue[0], b'x');
        assert_eq!(state.keyboard_byte_queue_len, 1);
        assert_eq!(state.keyboard_transfer_events, 9);
        assert_eq!(state.keyboard_valid_report_events, 3);
        assert_eq!(state.last_keys[0], 0x04);
        assert!(state.caps_lock_on);
        assert_eq!(
            read_xhci_trb(kbd_base, XHCI_COMMAND_RING_TRBS - 1),
            XhciTrb {
                parameter: kbd_ring,
                status: 0,
                control: (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT | XHCI_TRB_CYCLE
            }
        );
    }

    #[test]
    fn usb_keyboard_endpoint_recovery_sets_dequeue_to_fresh_ring_before_rearm() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let dma_range = runtime_resource_range(
            &descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )
        .expect("USB descriptor has DMA arena");
        let cmd_ring =
            xhci_dma_bus_addr(&descriptor, dma_range, XHCI_DMA_COMMAND_RING_OFFSET).unwrap();
        let kbd_ring = xhci_dma_bus_addr(&descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET).unwrap();
        let cmd_base = dma_range.vaddr as usize + XHCI_DMA_COMMAND_RING_OFFSET;
        let event_base = dma_range.vaddr as usize + XHCI_DMA_EVENT_RING_OFFSET;
        let kbd_base = dma_range.vaddr as usize + XHCI_DMA_KBD_RING_OFFSET;
        zero_dma_range(cmd_base, XHCI_COMMAND_RING_BYTES);
        zero_dma_range(event_base, XHCI_COMMAND_RING_BYTES);
        zero_dma_range(kbd_base, XHCI_COMMAND_RING_BYTES);
        write_xhci_trb(
            event_base,
            0,
            XhciTrb {
                parameter: cmd_ring,
                status: XHCI_COMPLETION_SUCCESS << 24,
                control: XHCI_TRB_CYCLE | (XHCI_TRB_TYPE_COMMAND_COMPLETION << 10),
            },
        );
        write_xhci_trb(
            event_base,
            1,
            XhciTrb {
                parameter: cmd_ring + XHCI_TRB_BYTES as u64,
                status: XHCI_COMPLETION_SUCCESS << 24,
                control: XHCI_TRB_CYCLE | (XHCI_TRB_TYPE_COMMAND_COMPLETION << 10),
            },
        );
        write_xhci_trb(
            event_base,
            2,
            XhciTrb {
                parameter: kbd_ring + (15 * XHCI_TRB_BYTES) as u64 + 0x08,
                status: XHCI_COMPLETION_SHORT_PACKET << 24,
                control: XHCI_TRB_CYCLE
                    | (XHCI_TRB_TYPE_TRANSFER_EVENT << 10)
                    | (3 << 16)
                    | (4 << 24),
            },
        );
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.initialized = true;
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY;
        state.keyboard_slot = 4;
        state.keyboard_endpoint_id = 3;
        state.keyboard_valid_report_events = 3;
        state.keyboard_reports_queued = 2;
        state.keyboard_report_in_use[0] = true;
        state.keyboard_report_in_use[1] = true;
        state.keyboard_report_trb_indices[0] = 21;
        state.keyboard_report_trb_indices[1] = 22;
        state.keyboard_preserved_event_count = 1;
        state.keyboard_preserved_event_parameters[0] = kbd_ring + 21 * XHCI_TRB_BYTES as u64 + 8;
        state.kbd_enqueue = 23;
        state.kbd_cycle = false;
        state.event_dequeue = 0;
        state.event_cycle = true;

        assert!(xhci_recover_keyboard_interrupt_endpoint(
            &mut state,
            &descriptor
        ));

        assert_eq!(state.event_dequeue, 3);
        assert_eq!(state.keyboard_endpoint_recoveries, 1);
        assert_eq!(
            state.keyboard_last_report_status,
            DRIVER_RUNTIME_USB_KEYBOARD_REPORT_STATUS_RECOVERY_SUCCESS
        );
        assert_eq!(state.keyboard_preserved_event_count, 0);
        assert_eq!(
            usize::from(state.keyboard_reports_queued),
            USB_KEYBOARD_STEADY_INTERRUPT_QUEUE_DEPTH
        );
        assert_eq!(
            read_xhci_trb(cmd_base, 0),
            XhciTrb {
                parameter: 0,
                status: 0,
                control: XHCI_TRB_CYCLE
                    | (XHCI_TRB_TYPE_STOP_ENDPOINT << 10)
                    | (3 << 16)
                    | (4 << 24)
            }
        );
        assert_eq!(
            read_xhci_trb(cmd_base, 1),
            XhciTrb {
                parameter: kbd_ring | 1,
                status: 0,
                control: XHCI_TRB_CYCLE
                    | (XHCI_TRB_TYPE_SET_TR_DEQUEUE_POINTER << 10)
                    | (3 << 16)
                    | (4 << 24)
            }
        );
        assert_eq!(
            read_xhci_trb(kbd_base, XHCI_COMMAND_RING_TRBS - 1),
            XhciTrb {
                parameter: kbd_ring,
                status: 0,
                control: (XHCI_TRB_TYPE_LINK << 10) | XHCI_TRB_ENT | XHCI_TRB_CYCLE
            }
        );
        assert_eq!(state.keyboard_report_trb_indices[0], 0);
    }

    #[test]
