    #[test]
    fn usb_control_transfer_completion_requires_status_stage_event() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 64,
            data_stage_event_expected: true,
        };
        let data_event = XhciTrb {
            parameter: plan.data_trb | 0x0c,
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 16,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, data_event, false),
            XhciControlTransferEvent::DataStage { transferred: 48 }
        );

        let setup_event = XhciTrb {
            parameter: plan.setup_trb | 0x04,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_event, false),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_event, true),
            XhciControlTransferEvent::Ignore
        );

        let status_event = XhciTrb {
            parameter: plan.status_trb | 0x08,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, status_event, true),
            XhciControlTransferEvent::Complete
        );

        let failed_status = XhciTrb {
            status: 2 << 24,
            ..status_event
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, failed_status, true),
            XhciControlTransferEvent::Fail { code: 2 }
        );
    }

    #[test]
    fn usb_control_transfer_accepts_same_ep_zero_remaining_status_completion() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0,
            status_trb: 0x4010,
            data_len: 0,
            data_stage_event_expected: false,
        };
        let pointer_mismatch_status = XhciTrb {
            parameter: 0x4050,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, false),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, true),
            XhciControlTransferEvent::Complete
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 2, pointer_mismatch_status, true),
            XhciControlTransferEvent::Ignore
        );
        let partial_event = XhciTrb {
            status: (XHCI_COMPLETION_SUCCESS << 24) | 4,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, partial_event, true),
            XhciControlTransferEvent::Ignore
        );
    }

    #[test]
    fn usb_control_transfer_accepts_same_ep_bounded_data_pointer_mismatch() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 64,
            data_stage_event_expected: true,
        };
        let pointer_mismatch_data = XhciTrb {
            parameter: 0x4050,
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 16,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_data, false),
            XhciControlTransferEvent::DataStage { transferred: 48 }
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_data, true),
            XhciControlTransferEvent::Ignore
        );
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 2, pointer_mismatch_data, false),
            XhciControlTransferEvent::Ignore
        );
        let impossible_remaining = XhciTrb {
            status: (XHCI_COMPLETION_SUCCESS << 24) | 65,
            ..pointer_mismatch_data
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, impossible_remaining, false),
            XhciControlTransferEvent::Ignore
        );
        let setup_echo = XhciTrb {
            parameter: plan.setup_trb | 0x08,
            status: XHCI_COMPLETION_SUCCESS << 24,
            ..pointer_mismatch_data
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_echo, false),
            XhciControlTransferEvent::Ignore
        );
    }

    #[test]
    fn usb_hub_status_no_data_ioc_accepts_zero_remaining_status_pointer_mismatch() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0x4010,
            status_trb: 0x4020,
            data_len: 4,
            data_stage_event_expected: false,
        };
        let pointer_mismatch_status = XhciTrb {
            parameter: 0x4050,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, pointer_mismatch_status, false),
            XhciControlTransferEvent::Complete
        );

        let data_pointer_status = XhciTrb {
            parameter: plan.data_trb | 0x08,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, data_pointer_status, false),
            XhciControlTransferEvent::Complete
        );

        let setup_echo = XhciTrb {
            parameter: plan.setup_trb | 0x08,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_echo, false),
            XhciControlTransferEvent::Complete
        );

        let short_packet_data = XhciTrb {
            status: (XHCI_COMPLETION_SHORT_PACKET << 24) | 2,
            ..pointer_mismatch_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, short_packet_data, false),
            XhciControlTransferEvent::DataStage { transferred: 2 }
        );

        let data_ioc_plan = XhciControlTransferPlan {
            data_stage_event_expected: true,
            ..plan
        };
        assert_eq!(
            xhci_classify_control_transfer_event(
                data_ioc_plan,
                3,
                1,
                pointer_mismatch_status,
                false,
            ),
            XhciControlTransferEvent::DataStage { transferred: 4 }
        );
        assert_eq!(
            xhci_classify_control_transfer_event(data_ioc_plan, 3, 1, data_pointer_status, false),
            XhciControlTransferEvent::DataStage { transferred: 4 }
        );
    }

    #[test]
    fn usb_zero_data_control_accepts_setup_pointer_completion() {
        let plan = XhciControlTransferPlan {
            setup_trb: 0x4000,
            data_trb: 0,
            status_trb: 0x4010,
            data_len: 0,
            data_stage_event_expected: true,
        };
        let setup_pointer_status = XhciTrb {
            parameter: plan.setup_trb | 0x04,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10) | (1 << 16) | (3 << 24),
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, setup_pointer_status, true),
            XhciControlTransferEvent::Complete
        );

        let impossible_remaining = XhciTrb {
            status: (XHCI_COMPLETION_SUCCESS << 24) | 1,
            ..setup_pointer_status
        };
        assert_eq!(
            xhci_classify_control_transfer_event(plan, 3, 1, impossible_remaining, true),
            XhciControlTransferEvent::Ignore
        );
    }

    #[test]
    fn usb_control_event_diagnostics_split_transfer_and_status_waits() {
        let progress = XhciControlProgress {
            sequence: 8,
            aux0: DRIVER_RUNTIME_USB_ENUMERATE_AUX,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_DATA_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_FAILED,
            transfer_timeout:
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_TIMEOUT,
            status_timeout:
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_TIMEOUT,
        };
        let empty = XhciTrb {
            parameter: 0,
            status: 0,
            control: 0,
        };
        assert_eq!(
            xhci_control_pending_event_phase_for_event(empty, true, progress, false),
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_SLOT_EMPTY
        );

        let stale_cycle = XhciTrb {
            parameter: 0x4000,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: XHCI_TRB_TYPE_TRANSFER_EVENT << 10,
        };
        assert_eq!(
            xhci_control_pending_event_phase_for_event(stale_cycle, true, progress, false),
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_CYCLE_MISMATCH
        );
        assert_eq!(
            xhci_control_pending_event_phase_for_event(stale_cycle, true, progress, true),
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_CYCLE_MISMATCH
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(progress, false).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_IGNORED
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(progress, true).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_STATUS_EVENT_IGNORED
        );
        let hub_progress = XhciControlProgress {
            sequence: 8,
            aux0: DRIVER_RUNTIME_USB_ENUMERATE_AUX,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_DATA_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_FAILED,
            transfer_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_TIMEOUT,
            status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_TIMEOUT,
        };
        assert_eq!(
            xhci_control_pending_event_phase_for_event(empty, true, hub_progress, false),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_SLOT_EMPTY
        );
        assert_eq!(
            xhci_control_pending_event_phase_for_event(stale_cycle, true, hub_progress, true),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_CYCLE_MISMATCH
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(hub_progress, false).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_TRANSFER_EVENT_IGNORED
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(hub_progress, true).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_DESCRIPTOR_STATUS_EVENT_IGNORED
        );
        let hub_port_status_progress =
            usb_hub_port_status_progress(8, DRIVER_RUNTIME_USB_ENUMERATE_AUX);
        assert_eq!(
            xhci_control_pending_event_phase_for_event(
                empty,
                true,
                hub_port_status_progress,
                false
            ),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_SLOT_EMPTY
        );
        assert_eq!(
            xhci_control_pending_event_phase_for_event(
                stale_cycle,
                true,
                hub_port_status_progress,
                true
            ),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_CYCLE_MISMATCH
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(hub_port_status_progress, false).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_TRANSFER_EVENT_IGNORED
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(hub_port_status_progress, true).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_PORT_STATUS_STATUS_EVENT_IGNORED
        );
        let hub_set_config_progress = XhciControlProgress {
            sequence: 8,
            aux0: DRIVER_RUNTIME_USB_ENUMERATE_AUX,
            doorbell_done: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_DOORBELL_DONE,
            wait_begin: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_WAIT_BEGIN,
            data_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT,
            status_event: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT,
            failed: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_FAILED,
            transfer_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_TIMEOUT,
            status_timeout: DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_TIMEOUT,
        };
        assert_eq!(
            xhci_control_pending_event_phase_for_event(empty, true, hub_set_config_progress, true),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_SLOT_EMPTY
        );
        assert_eq!(
            xhci_control_pending_event_phase_for_event(
                stale_cycle,
                true,
                hub_set_config_progress,
                true
            ),
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_CYCLE_MISMATCH
        );
        assert_eq!(
            xhci_control_transfer_event_diagnostic_phases(hub_set_config_progress, true).ignored,
            DRIVER_RUNTIME_RING_PROGRESS_USB_HUB_SET_CONFIGURATION_STATUS_EVENT_IGNORED
        );
        assert!(
            xhci_control_pending_event_phase_rank(
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_IGNORED,
            ) > xhci_control_pending_event_phase_rank(
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_CYCLE_MISMATCH,
            )
        );
        assert!(
            xhci_control_pending_event_phase_rank(
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_CYCLE_MISMATCH,
            ) > xhci_control_pending_event_phase_rank(
                DRIVER_RUNTIME_RING_PROGRESS_USB_CONFIG_DESCRIPTOR_HEADER_TRANSFER_EVENT_SLOT_EMPTY,
            )
        );
    }

    #[test]
    fn usb_portsc_neutral_write_mask_does_not_mirror_enable_or_change_bits() {
        let status = XHCI_PORTSC_CCS
            | XHCI_PORTSC_PED
            | XHCI_PORTSC_PR
            | XHCI_PORTSC_PP
            | (XHCI_SPEED_HIGH << XHCI_PORTSC_SPEED_SHIFT)
            | XHCI_PORTSC_CHANGE_BITS;
        let neutral = xhci_portsc_neutral(status);
        assert_ne!(neutral & XHCI_PORTSC_CCS, 0);
        assert_ne!(neutral & XHCI_PORTSC_PP, 0);
        assert_eq!(
            (neutral >> XHCI_PORTSC_SPEED_SHIFT) & XHCI_PORTSC_SPEED_MASK,
            XHCI_SPEED_HIGH
        );
        assert_eq!(neutral & (XHCI_PORTSC_PED | XHCI_PORTSC_PR), 0);
        assert_eq!(neutral & XHCI_PORTSC_CHANGE_BITS, 0);
    }

    #[test]
    fn usb_runtime_preserves_port_status_change_events_for_retry_scans() {
        let mut state = UsbRuntimeState::new();
        state.max_ports = 4;

        let event = XhciTrb {
            parameter: 2 << 24,
            status: 0,
            control: XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT << 10,
        };
        xhci_preserve_port_status_change_event(&mut state, event);

        assert_eq!(state.port_event_candidate_mask, 0b0010);
        assert_eq!(state.port_event_count, 1);

        let transfer = XhciTrb {
            parameter: 1 << 24,
            status: 0,
            control: XHCI_TRB_TYPE_TRANSFER_EVENT << 10,
        };
        xhci_preserve_port_status_change_event(&mut state, transfer);
        assert_eq!(state.port_event_candidate_mask, 0b0010);
        assert_eq!(state.port_event_count, 1);

        let out_of_range = XhciTrb {
            parameter: 5 << 24,
            status: 0,
            control: XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT << 10,
        };
        xhci_preserve_port_status_change_event(&mut state, out_of_range);
        assert_eq!(state.port_event_candidate_mask, 0b0010);
        assert_eq!(state.port_event_count, 1);
    }

    fn write_sdio_descriptor_for_test(offset: usize, desc: DriverRuntimeSdioCommandDescriptor) {
        write_ring_byte(offset, (desc.op & 0xff) as u8);
        write_ring_byte(offset + 1, (desc.op >> 8) as u8);
        write_ring_byte(offset + 2, desc.function);
        write_ring_byte(offset + 3, desc.response_kind);
        write_ring_u32(offset + 4, desc.addr);
        write_ring_byte(offset + 8, (desc.data_offset & 0xff) as u8);
        write_ring_byte(offset + 9, (desc.data_offset >> 8) as u8);
        write_ring_byte(offset + 10, (desc.len & 0xff) as u8);
        write_ring_byte(offset + 11, (desc.len >> 8) as u8);
        write_ring_byte(offset + 12, (desc.block_size & 0xff) as u8);
        write_ring_byte(offset + 13, (desc.block_size >> 8) as u8);
        write_ring_byte(offset + 14, (desc.block_count & 0xff) as u8);
        write_ring_byte(offset + 15, (desc.block_count >> 8) as u8);
        write_ring_byte(offset + 16, (desc.flags & 0xff) as u8);
        write_ring_byte(offset + 17, (desc.flags >> 8) as u8);
        write_ring_byte(offset + 18, (desc.reserved & 0xff) as u8);
        write_ring_byte(offset + 19, (desc.reserved >> 8) as u8);
        write_ring_u32(offset + 20, desc.timeout_us);
    }

    #[test]
    fn pcie_runtime_bounds_mmio_by_descriptor_pages() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_runtime_for_test(HOT_PATH_PCIE_ROOT, ROLE_PCIE);
        let init = DriverTaskCommandRecord {
            sequence: 60,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_PCIE_ROOT,
            arg1: ROLE_PCIE,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, init),
            DriverTaskCompletionRecord::progress(60, 1)
        );
        let limit = usize::from(PCIE_REQUIRED_MMIO_PAGES) * DRIVER_TASK_RING_PAGE_BYTES;
        let command = DriverTaskCommandRecord {
            sequence: 61,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_PCIE_ROOT,
            arg1: ROLE_PCIE,
            aux0: (DRIVER_RUNTIME_PCIE_OP_PORT_READ as u32) << 16,
            aux1: limit as u32,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, command),
            DriverTaskCompletionRecord::fault(61, FAULT_REJECTED_COMMAND)
        );
    }

    #[test]
    fn hdmi_safe_area_insets_and_aligns_text_surface() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let safe = hdmi_safe_area_for_framebuffer(640, 480);
        assert_eq!(
            safe,
            HdmiSafeArea {
                x: 12,
                y: 16,
                width: 616,
                height: 448,
            }
        );
        assert_eq!(safe.width % CHAR_WIDTH, 0);
        assert_eq!(safe.height % CHAR_HEIGHT, 0);
        assert!(safe.x > 0);
        assert!(safe.y > 0);
        assert!(safe.x + safe.width < 640);
        assert!(safe.y + safe.height < 480);

        HDMI_CURSOR_ROW.store(999, Ordering::Release);
        HDMI_CURSOR_COL.store(999, Ordering::Release);
        let mut descriptor = descriptor_for(HOT_PATH_HDMI_TEXT, ROLE_DISPLAY);
        descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER;
        descriptor.framebuffer = DriverRuntimeFramebufferDescriptor {
            vaddr: DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
            paddr: 0x3000_0000,
            width: 640,
            height: 480,
            pitch: 640 * 4,
            format: DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_XRGB8888,
        };
        let state = HdmiRenderState::from_descriptor(&descriptor);
        assert_eq!(state.framebuffer_width, 640);
        assert_eq!(state.framebuffer_height, 480);
        assert_eq!(state.safe_x, 12);
        assert_eq!(state.safe_y, 16);
        assert_eq!(state.width, 616);
        assert_eq!(state.height, 448);
        assert_eq!(state.cols, 77);
        assert_eq!(state.rows, 28);
        assert_eq!(state.row, 27);
        assert_eq!(state.col, 77);
    }

    #[test]
    fn hdmi_linked_runtime_renders_after_framebuffer_descriptor() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut descriptor = descriptor_for(HOT_PATH_HDMI_TEXT, ROLE_DISPLAY);
        descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER;
        descriptor.framebuffer = DriverRuntimeFramebufferDescriptor {
            vaddr: DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
            paddr: 0x3000_0000,
            width: 640,
            height: 480,
            pitch: 640 * 4,
            format: DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_XRGB8888,
        };
        let range_index = descriptor.resource_range_count as usize;
        descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
            DRIVER_RUNTIME_RESOURCE_KIND_FRAMEBUFFER,
            DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
            DRIVER_RUNTIME_RESOURCE_TAG_HDMI_FRAMEBUFFER,
            DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
            0x3000_0000,
            DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
            1,
            0,
        );
        descriptor.resource_range_count += 1;
        let init = DriverTaskCommandRecord {
            sequence: 30,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(
                runtime_task_key_for_hot_path(HOT_PATH_HDMI_TEXT),
                init,
                descriptor
            ),
            DriverTaskCompletionRecord::progress(30, HOT_PATH_HDMI_TEXT)
        );
        let engine_init = DriverTaskCommandRecord {
            sequence: 31,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, engine_init),
            DriverTaskCompletionRecord::progress(31, 1)
        );
        let frame = DriverTaskCommandRecord {
            sequence: 32,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 5,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, frame),
            DriverTaskCompletionRecord::progress(32, 5)
        );
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 0);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 5);
        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"a\nb");
        let newline_frame = DriverTaskCommandRecord {
            sequence: 33,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 3,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, newline_frame),
            DriverTaskCompletionRecord::progress(33, 3)
        );
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 1);
        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"\x1b[");
        let split_csi_begin_frame = DriverTaskCommandRecord {
            sequence: 34,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 2,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, split_csi_begin_frame),
            DriverTaskCompletionRecord::progress(34, 2)
        );
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 2);

        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"Hq");
        let split_csi_finish_frame = DriverTaskCommandRecord {
            sequence: 35,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 2,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, split_csi_finish_frame),
            DriverTaskCompletionRecord::progress(35, 2)
        );
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 0);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 0);

        let stale_row_digest = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0);
        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"\x1b");
        let clear_to_end_begin_frame = DriverTaskCommandRecord {
            sequence: 36,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 1,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, clear_to_end_begin_frame),
            DriverTaskCompletionRecord::progress(36, 1)
        );
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 1);

        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"[J");
        let clear_to_end_finish_frame = DriverTaskCommandRecord {
            sequence: 37,
            opcode: OPCODE_SUBMIT_FRAME,
            flags: 0,
            arg0: HOT_PATH_HDMI_TEXT,
            arg1: ROLE_DISPLAY,
            aux0: 0,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: 2,
                flags: 0,
            },
        };
        assert_eq!(
            service_command(0, clear_to_end_finish_frame),
            DriverTaskCompletionRecord::progress(37, 2)
        );
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 0);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 0);
        let cleared_row_digest = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0);
        let preserved_prompt_digest = test_hdmi_cell_digest(&descriptor.framebuffer, 0, 0);
        let blank_digest = {
            let mut state = HdmiRenderState::from_descriptor(&descriptor);
            state.clear_text_area();
            test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0)
        };
        assert_ne!(stale_row_digest, blank_digest);
        assert_eq!(cleared_row_digest, blank_digest);
        assert_ne!(preserved_prompt_digest, blank_digest);
    }

    fn test_hdmi_cell_digest(
        descriptor: &DriverRuntimeFramebufferDescriptor,
        row: usize,
        col: usize,
    ) -> u32 {
        let safe =
            hdmi_safe_area_for_framebuffer(descriptor.width as usize, descriptor.height as usize);
        let x0 = safe.x + col.saturating_mul(CHAR_WIDTH);
        let y0 = safe.y + row.saturating_mul(CHAR_HEIGHT);
        let mut digest = 0x811c_9dc5u32;
        for y in 0..CHAR_HEIGHT {
            for x in 0..CHAR_WIDTH {
                let abs_x = x0 + x;
                let abs_y = y0 + y;
                let byte_off = abs_y
                    .saturating_mul(descriptor.pitch as usize)
                    .saturating_add(abs_x.saturating_mul(FB_BYTES_PER_PIXEL_32));
                let pixel =
                    read_framebuffer_u32(DRIVER_RUNTIME_FRAMEBUFFER_VADDR as usize + byte_off);
                digest = digest.rotate_left(5) ^ pixel;
            }
        }
        digest
    }

    #[test]
    fn hdmi_runtime_scroll_moves_rows_and_clears_exposed_row() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut descriptor = descriptor_for(HOT_PATH_HDMI_TEXT, ROLE_DISPLAY);
        descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER;
        descriptor.framebuffer = DriverRuntimeFramebufferDescriptor {
            vaddr: DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
            paddr: 0x3000_0000,
            width: 64,
            height: (CHAR_HEIGHT * 3) as u32,
            pitch: 64 * 4,
            format: DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_XRGB8888,
        };
        let mut state = HdmiRenderState::from_descriptor(&descriptor);
        assert_eq!(state.rows, 2);
        state.clear_text_area();
        state.put_str("a\nb");

        let top_before = test_hdmi_cell_digest(&descriptor.framebuffer, 0, 0);
        let bottom_before = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0);
        assert_ne!(top_before, bottom_before);

        state.put_byte(b'\n');

        let top_after = test_hdmi_cell_digest(&descriptor.framebuffer, 0, 0);
        let bottom_after = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0);
        let blank = {
            state.clear_text_area();
            test_hdmi_cell_digest(&descriptor.framebuffer, 1, 0)
        };
        assert_eq!(top_after, bottom_before);
        assert_eq!(bottom_after, blank);
        assert_eq!(state.row, 1);
        assert_eq!(state.col, 0);
    }

    #[test]
    fn hdmi_runtime_csi_cursor_params_persist_across_frames() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut descriptor = descriptor_for(HOT_PATH_HDMI_TEXT, ROLE_DISPLAY);
        descriptor.flags |= DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER;
        descriptor.framebuffer = DriverRuntimeFramebufferDescriptor {
            vaddr: DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
            paddr: 0x3000_0000,
            width: 640,
            height: 480,
            pitch: 640 * 4,
            format: DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_XRGB8888,
        };
        RUNTIME_DESCRIPTOR.store(descriptor);

        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"alpha\nbravo\n\x1b[");
        let first = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: 14,
            flags: 0,
        };
        assert_eq!(hdmi_render_frame(first), 14);
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 2);

        stage_bytes(DRIVER_TASK_RING_FRAME_OFFSET, b"2;3HZ");
        let second = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
            len: 5,
            flags: 0,
        };
        assert_eq!(hdmi_render_frame(second), 5);
        assert_eq!(HDMI_ESCAPE_STATE.load(Ordering::Acquire), 0);
        assert_eq!(HDMI_CURSOR_ROW.load(Ordering::Acquire), 1);
        assert_eq!(HDMI_CURSOR_COL.load(Ordering::Acquire), 3);

        let mut blank_state = HdmiRenderState::from_descriptor(&descriptor);
        blank_state.clear_text_area();
        let blank = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 2);
        let mut state = HdmiRenderState::from_descriptor(&descriptor);
        state.put_str("\x1b[2;3HZ");
        let rendered = test_hdmi_cell_digest(&descriptor.framebuffer, 1, 2);
        assert_ne!(rendered, blank);
    }

